package app

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// CliArgs holds the parsed command line arguments.
type CliArgs struct {
	RepoPath         string
	FilterPath       string
	GitArg           string
	PrintVersionInfo bool
	Debug            bool
	TailLogs         bool
	Profile          bool
	PrintDefaultConfig bool
	PrintConfigDir   bool
	UseConfigDir     string
	WorkTree         string
	GitDir           string
	CustomConfigFile string
	ScreenMode       string
}

type flagDef struct {
	short  string
	long   string
	desc   string
	isBool bool
	set    func(a *CliArgs, v string)
}

var flagDefs = []flagDef{
	{"h", "help", "Displays help with available flag, subcommand, and positional value parameters.", true, nil},
	{"p", "path", "Path of git repo. (equivalent to --work-tree=<path> --git-dir=<path>/.git/)", false, func(a *CliArgs, v string) { a.RepoPath = v }},
	{"f", "filter", "Path to filter on in `git log -- <path>`. When in filter mode, the commits, reflog, and stash are filtered based on the given path, and some operations are restricted", false, func(a *CliArgs, v string) { a.FilterPath = v }},
	{"v", "version", "Print the current version", true, func(a *CliArgs, v string) { a.PrintVersionInfo = parseBool(v) }},
	{"d", "debug", "Run in debug mode with logging (see --logs flag below). Use the LOG_LEVEL env var to set the log level (debug/info/warn/error)", true, func(a *CliArgs, v string) { a.Debug = parseBool(v) }},
	{"l", "logs", "Tail lazygit logs (intended to be used when `lazygit --debug` is called in a separate terminal tab)", true, func(a *CliArgs, v string) { a.TailLogs = parseBool(v) }},
	{"", "profile", "Start the profiler and serve it on http port 6060. See CONTRIBUTING.md for more info.", true, func(a *CliArgs, v string) { a.Profile = parseBool(v) }},
	{"c", "config", "Print the default config", true, func(a *CliArgs, v string) { a.PrintDefaultConfig = parseBool(v) }},
	{"cd", "print-config-dir", "Print the config directory", true, func(a *CliArgs, v string) { a.PrintConfigDir = parseBool(v) }},
	{"ucd", "use-config-dir", "override default config directory with provided directory", false, func(a *CliArgs, v string) { a.UseConfigDir = v }},
	{"w", "work-tree", "equivalent of the --work-tree git argument", false, func(a *CliArgs, v string) { a.WorkTree = v }},
	{"g", "git-dir", "equivalent of the --git-dir git argument", false, func(a *CliArgs, v string) { a.GitDir = v }},
	{"ucf", "use-config-file", "Comma separated list to custom config file(s)", false, func(a *CliArgs, v string) { a.CustomConfigFile = v }},
	{"sm", "screen-mode", "The initial screen-mode, which determines the size of the focused panel. Valid options: 'normal' (default), 'half', 'full'", false, func(a *CliArgs, v string) { a.ScreenMode = v }},
}

func parseBool(v string) bool {
	switch strings.ToLower(v) {
	case "", "true", "t", "1", "yes", "y":
		return true
	}
	return false
}

func programName() string {
	return filepath.Base(os.Args[0])
}

// HelpText renders the usage text in the style of the flaggy library.
func HelpText() string {
	var b strings.Builder
	name := programName()
	b.WriteString(name + "\n\n")
	b.WriteString("  Usage:\n")
	b.WriteString("    " + name + " [git-arg]\n\n")
	b.WriteString("  Positional Variables: \n")
	b.WriteString("    git-arg   Panel to focus upon opening lazygit. Accepted values (based on git terminology): status, branch, log, stash. Ignored if --filter arg is passed.\n")
	b.WriteString("  Flags: \n")
	for _, f := range flagDefs {
		short := "  "
		if f.short != "" {
			short = "-" + f.short
		}
		long := "--" + f.long
		line := fmt.Sprintf("    %s %-20s  %s", short, long, f.desc)
		b.WriteString(line + "\n")
	}
	b.WriteString("\n")
	return b.String()
}

func printHelpAndExit(msg string, code int) {
	fmt.Fprint(os.Stderr, HelpText())
	if msg != "" {
		fmt.Fprintln(os.Stderr, msg)
	}
	os.Exit(code)
}

func findFlag(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].short == name || flagDefs[i].long == name {
			return &flagDefs[i]
		}
	}
	return nil
}

// ParseArgs parses command line arguments, mimicking flaggy's behaviour.
func ParseArgs(args []string) *CliArgs {
	cli := &CliArgs{}
	var positionals []string
	var unknown []string
	helpRequested := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			// everything after is positional
			positionals = append(positionals, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			name := strings.TrimLeft(arg, "-")
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			if name == "" {
				panic("cant add parsed value with no key or value")
			}
			f := findFlag(name)
			if f == nil {
				if hasValue {
					unknown = append(unknown, name+"="+value)
					continue
				}
				if i+1 >= len(args) {
					printHelpAndExit(fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", name), 2)
				}
				unknown = append(unknown, name, args[i+1])
				i++
				continue
			}
			if f.long == "help" {
				helpRequested = true
				continue
			}
			if f.isBool {
				if hasValue {
					f.set(cli, value)
				} else {
					f.set(cli, "true")
				}
				continue
			}
			if hasValue {
				f.set(cli, value)
				continue
			}
			if i+1 >= len(args) {
				printHelpAndExit(fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", name), 2)
			}
			f.set(cli, args[i+1])
			i++
			continue
		}
		positionals = append(positionals, arg)
	}

	if helpRequested {
		printHelpAndExit("", 0)
	}

	if len(positionals) > 0 {
		cli.GitArg = positionals[0]
	}
	if len(positionals) > 1 {
		printHelpAndExit(fmt.Sprintf("Unexpected argument: %s", positionals[1]), 2)
	}
	if len(unknown) > 0 {
		printHelpAndExit("Unknown arguments supplied:  "+strings.Join(unknown, " "), 2)
	}
	return cli
}
EOF
echo ok

