func RuneWidth(r rune) int {
	switch {
	case r == 0:
		return 0
	case r < 0x20:
		return 0
	case r < 0x7f:
		return 1
	case r < 0xa0:
		return 0
	case r >= 0x300 && r <= 0x36f: // combining
		return 0
	case r >= 0x200b && r <= 0x200f:
		return 0
	case r == 0xfe0f || r == 0xfe0e:
