package term

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// Cell is a single character cell on the screen.
type Cell struct {
	R     rune
	Style Style
	// Width is 0 for the trailing half of a wide character.
	Width int
}

// Screen is a double buffered character grid rendered to the terminal.
type Screen struct {
	w, h   int
	cells  []Cell
	prev   []Cell
	out    *bufio.Writer
	tty    *os.File
	cursorVisible bool
	cursorX, cursorY int
	fullRedraw bool
}

func newScreen(tty *os.File, w, h int) *Screen {
	s := &Screen{tty: tty, out: bufio.NewWriterSize(tty, 1<<16)}
	s.Resize(w, h)
	return s
}

func (s *Screen) Size() (int, int) { return s.w, s.h }

func (s *Screen) Resize(w, h int) {
	s.w, s.h = w, h
	s.cells = make([]Cell, w*h)
	s.prev = nil
	s.Clear()
	s.fullRedraw = true
}

func (s *Screen) Clear() {
	for i := range s.cells {
		s.cells[i] = Cell{R: ' ', Style: DefaultStyle, Width: 1}
	}
}

// Set writes a rune at the given position.
func (s *Screen) Set(x, y int, r rune, st Style) {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return
	}
	w := RuneWidth(r)
	if w == 0 {
		return
	}
	s.cells[y*s.w+x] = Cell{R: r, Style: st, Width: w}
	if w == 2 && x+1 < s.w {
		s.cells[y*s.w+x+1] = Cell{R: 0, Style: st, Width: 0}
	}
}

func (s *Screen) Get(x, y int) Cell {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return Cell{R: ' ', Style: DefaultStyle, Width: 1}
	}
	return s.cells[y*s.w+x]
}

func (s *Screen) ShowCursor(x, y int) {
	s.cursorVisible = true
	s.cursorX, s.cursorY = x, y
}

func (s *Screen) HideCursor() {
	s.cursorVisible = false
}

func sgr(st Style) string {
	var b strings.Builder
	b.WriteString("\x1b[0")
	if st.Attr&AttrBold != 0 {
		b.WriteString(";1")
	}
	if st.Attr&AttrDim != 0 {
		b.WriteString(";2")
	}
	if st.Attr&AttrItalic != 0 {
		b.WriteString(";3")
	}
	if st.Attr&AttrUnderline != 0 {
		b.WriteString(";4")
	}
	if st.Attr&AttrBlink != 0 {
		b.WriteString(";5")
	}
	if st.Attr&AttrReverse != 0 {
		b.WriteString(";7")
	}
	if st.Attr&AttrStrike != 0 {
		b.WriteString(";9")
	}
	writeColor(&b, st.Fg, true)
	writeColor(&b, st.Bg, false)
	b.WriteString("m")
	return b.String()
}

func writeColor(b *strings.Builder, c Color, fg bool) {
	if c == ColorDefault {
		return
	}
	if c.IsRGB() {
