	tty    *os.File
	cursorVisible bool
	cursorX, cursorY int
	fullRedraw bool
}

func newScreen(tty *os.File, w, h int) *Screen {
	s := &Screen{tty: tty, out: bufio.NewWriterSize(tty, 1<<16)}
	s.Resize(w, h)
	return s
}

func (s *Screen) Size() (int, int) { return s.w, s.h }

func (s *Screen) Resize(w, h int) {
	s.w, s.h = w, h
	s.cells = make([]Cell, w*h)
	s.prev = nil
	s.Clear()
	s.fullRedraw = true
