package gui

import (
	"strings"

	"lazygit-clone/internal/term"
)

// View is a rectangular region with an optional frame, modelled loosely on
// gocui views.
type View struct {
	Name string
	// frame coordinates (inclusive)
	X0, Y0, X1, Y1 int
	Visible        bool

	Frame      bool
	FrameStyle term.Style
	Title      Line
	Footer     string

	Lines   []Line
	OriginX int
	OriginY int
	Wrap    bool

	Highlight bool
	SelStart  int
	SelEnd    int
	SelBg     term.Color

	CanScrollPastBottom bool
	ShowScrollbar       bool
	// when true, a lone trailing empty line in Lines is not counted
	// (used for views whose content ends with a newline)
	AutoScrollToBottom bool

	// cached wrapped lines
	wrapped      []Line
	wrapWidth    int
	wrapSrcCount int
}

func NewView(name string) *View {
	return &View{Name: name, Visible: true, Frame: true, FrameStyle: term.DefaultStyle, SelStart: -1, SelEnd: -1, SelBg: term.ColorBlue, ShowScrollbar: true}
}

func (v *View) Width() int  { return v.X1 - v.X0 + 1 }
func (v *View) Height() int { return v.Y1 - v.Y0 + 1 }

// InnerWidth is the width of the content area.
func (v *View) InnerWidth() int {
	if v.Frame {
		return v.Width() - 2
	}
	return v.Width()
}

// InnerHeight is the height of the content area.
func (v *View) InnerHeight() int {
	if v.Frame {
		return v.Height() - 2
	}
	return v.Height()
}

func (v *View) SetContent(lines []Line) {
	v.Lines = lines
	v.wrapped = nil
}

func (v *View) SetText(s string) {
	v.SetContent(ParseANSILines(s))
}

// displayLines returns the lines to draw (wrapped if necessary).
func (v *View) displayLines() []Line {
	if !v.Wrap {
		return v.Lines
	}
	w := v.InnerWidth()
	if w <= 0 {
		return v.Lines
	}
	if v.wrapped != nil && v.wrapWidth == w && v.wrapSrcCount == len(v.Lines) {
		return v.wrapped
	}
	var out []Line
	for _, l := range v.Lines {
		out = append(out, wrapLine(l, w)...)
	}
	v.wrapped = out
	v.wrapWidth = w
	v.wrapSrcCount = len(v.Lines)
	return out
}

// wrapLine wraps a line at word boundaries like gocui does (break at spaces
// when possible, otherwise hard-wrap).
func wrapLine(l Line, width int) []Line {
	if l.Width() <= width {
		return []Line{l}
	}
	// flatten into runes with styles
	type cell struct {
		r  rune
		st term.Style
	}
	var cells []cell
	for _, sp := range l {
		for _, r := range sp.Text {
			cells = append(cells, cell{r, sp.Style})
		}
	}
	var result []Line
	start := 0
	for start < len(cells) {
		// find how many cells fit
		w := 0
		end := start
		for end < len(cells) {
			rw := term.RuneWidth(cells[end].r)
			if w+rw > width {
				break
			}
			w += rw
			end++
		}
		if end >= len(cells) {
			result = append(result, cellsToLine(cells[start:]))
			break
		}
		// try to break at last space within [start, end]
		brk := -1
		for i := end; i > start; i-- {
			if cells[i-1].r == ' ' {
				brk = i
				break
			}
		}
		if brk <= start {
			// hard wrap
			result = append(result, cellsToLine(cells[start:end]))
			start = end
		} else {
			// include the space at the end of the line (gocui keeps it)
			result = append(result, cellsToLine(cells[start:brk]))
			start = brk
		}
	}
	return result
}

func cellsToLine(cells []struct {
	r  rune
	st term.Style
}) Line {
	var out Line
	var b strings.Builder
	var cur term.Style
	first := true
	for _, c := range cells {
		if first || c.st != cur {
			if !first {
				out = append(out, Span{Text: b.String(), Style: cur})
				b.Reset()
			}
			cur = c.st
			first = false
		}
		b.WriteRune(c.r)
	}
	if !first {
		out = append(out, Span{Text: b.String(), Style: cur})
	}
	return out
}

// LinesHeight is the number of displayable lines.
func (v *View) LinesHeight() int {
	return len(v.displayLines())
}

// MaxOrigin returns the largest valid vertical origin.
func (v *View) MaxOrigin() int {
	n := v.LinesHeight()
	h := v.InnerHeight()
	if v.CanScrollPastBottom {
		if n-2 < 0 {
			return 0
		}
		return n - 2
	}
	if n-h < 0 {
		return 0
	}
	return n - h
}

func (v *View) ScrollDown(n int) {
	v.OriginY += n
	if max := v.MaxOrigin(); v.OriginY > max {
		v.OriginY = max
	}
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

func (v *View) ScrollUp(n int) {
	v.OriginY -= n
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

func (v *View) ScrollToBottom() {
	v.OriginY = v.MaxOrigin()
}

// FocusLine adjusts the origin so that the selected line is visible.
func (v *View) FocusLine(line int) {
	h := v.InnerHeight()
	if h <= 0 {
		return
	}
	if line < v.OriginY {
		v.OriginY = line
	} else if line >= v.OriginY+h {
		v.OriginY = line - h + 1
	}
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

// FocusLineWithMargin keeps the selected line within the view honouring a
// scroll-off margin.
func (v *View) FocusLineWithMargin(line int, margin int, total int) {
	h := v.InnerHeight()
	if h <= 0 {
		return
	}
	if margin*2 >= h {
		margin = (h - 1) / 2
	}
	if line < v.OriginY+margin {
		v.OriginY = line - margin
	} else if line > v.OriginY+h-1-margin {
		v.OriginY = line - h + 1 + margin
	}
	if v.OriginY > total-h {
		v.OriginY = total - h
	}
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

var frameRunes = struct {
	tl, tr, bl, br, h, v, hl, hr rune
}{'╭', '╮', '╰', '╯', '─', '│', '╶', '╴'}

// Draw renders the view to the screen.
func (v *View) Draw(scr *term.Screen) {
	if !v.Visible {
		return
	}
	if v.Width() <= 0 || v.Height() <= 0 {
		return
	}
	if v.Frame {
		v.drawFrame(scr)
	}
	v.drawContent(scr)
}

func (v *View) drawFrame(scr *term.Screen) {
	st := v.FrameStyle
	w := v.Width()
	h := v.Height()
	if h == 1 {
		// collapsed frame
		scr.Set(v.X0, v.Y0, frameRunes.hl, st)
		for x := v.X0 + 1; x < v.X1; x++ {
			scr.Set(x, v.Y0, frameRunes.h, st)
		}
		scr.Set(v.X1, v.Y0, frameRunes.hr, st)
		v.drawTitle(scr, v.Y0)
		v.drawFooter(scr, v.Y0)
		return
	}
	// top
	scr.Set(v.X0, v.Y0, frameRunes.tl, st)
	for x := v.X0 + 1; x < v.X1; x++ {
		scr.Set(x, v.Y0, frameRunes.h, st)
	}
	scr.Set(v.X1, v.Y0, frameRunes.tr, st)
	// sides
	for y := v.Y0 + 1; y < v.Y1; y++ {
		scr.Set(v.X0, y, frameRunes.v, st)
		scr.Set(v.X1, y, frameRunes.v, st)
	}
	// bottom
