	SelStart  int
	SelEnd    int
	SelBg     term.Color

	CanScrollPastBottom bool
	ShowScrollbar       bool
	// when true, a lone trailing empty line in Lines is not counted
	// (used for views whose content ends with a newline)
	AutoScrollToBottom bool

	// cached wrapped lines
	wrapped      []Line
	wrapWidth    int
	wrapSrcCount int
}

func NewView(name string) *View {
	return &View{Name: name, Visible: true, Frame: true, FrameStyle: term.DefaultStyle, SelStart: -1, SelEnd: -1, SelBg: term.ColorBlue, ShowScrollbar: true}
}

func (v *View) Width() int  { return v.X1 - v.X0 + 1 }
func (v *View) Height() int { return v.Y1 - v.Y0 + 1 }

// InnerWidth is the width of the content area.
func (v *View) InnerWidth() int {
	if v.Frame {
		return v.Width() - 2
	}
	return v.Width()
}

// InnerHeight is the height of the content area.
func (v *View) InnerHeight() int {
	if v.Frame {
		return v.Height() - 2
	}
	return v.Height()
}

func (v *View) SetContent(lines []Line) {
	v.Lines = lines
	v.wrapped = nil
}

func (v *View) SetText(s string) {
	v.SetContent(ParseANSILines(s))
}

// displayLines returns the lines to draw (wrapped if necessary).
func (v *View) displayLines() []Line {
	if !v.Wrap {
		return v.Lines
	}
	w := v.InnerWidth()
	if w <= 0 {
		return v.Lines
	}
	if v.wrapped != nil && v.wrapWidth == w && v.wrapSrcCount == len(v.Lines) {
		return v.wrapped
	}
	var out []Line
	for _, l := range v.Lines {
		out = append(out, wrapLine(l, w)...)
	}
	v.wrapped = out
	v.wrapWidth = w
	v.wrapSrcCount = len(v.Lines)
	return out
}

// wrapLine wraps a line at word boundaries like gocui does (break at spaces
// when possible, otherwise hard-wrap).
func wrapLine(l Line, width int) []Line {
	if l.Width() <= width {
		return []Line{l}
	}
	// flatten into runes with styles
	type cell struct {
		r  rune
		st term.Style
	}
	var cells []cell
	for _, sp := range l {
		for _, r := range sp.Text {
			cells = append(cells, cell{r, sp.Style})
		}
	}
	var result []Line
	start := 0
	for start < len(cells) {
		// find how many cells fit
		w := 0
		end := start
		for end < len(cells) {
			rw := term.RuneWidth(cells[end].r)
			if w+rw > width {
				break
			}
			w += rw
			end++
		}
		if end >= len(cells) {
			result = append(result, cellsToLine(cells[start:]))
			break
		}
		// try to break at last space within [start, end]
		brk := -1
		for i := end; i > start; i-- {
			if cells[i-1].r == ' ' {
				brk = i
				break
			}
		}
		if brk <= start {
			// hard wrap
			result = append(result, cellsToLine(cells[start:end]))
			start = end
		} else {
			// include the space at the end of the line (gocui keeps it)
			result = append(result, cellsToLine(cells[start:brk]))
			start = brk
		}
	}
	return result
}

func cellsToLine(cells []struct {
	r  rune
	st term.Style
}) Line {
	var out Line
	var b strings.Builder
	var cur term.Style
	first := true
	for _, c := range cells {
		if first || c.st != cur {
			if !first {
				out = append(out, Span{Text: b.String(), Style: cur})
				b.Reset()
			}
			cur = c.st
			first = false
		}
		b.WriteRune(c.r)
	}
	if !first {
		out = append(out, Span{Text: b.String(), Style: cur})
	}
	return out
}

