	}
}

func (v *View) ScrollUp(n int) {
	v.OriginY -= n
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

func (v *View) ScrollToBottom() {
	v.OriginY = v.MaxOrigin()
}

// FocusLine adjusts the origin so that the selected line is visible.
func (v *View) FocusLine(line int) {
	h := v.InnerHeight()
	if h <= 0 {
		return
	}
	if line < v.OriginY {
		v.OriginY = line
	} else if line >= v.OriginY+h {
		v.OriginY = line - h + 1
	}
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

// FocusLineWithMargin keeps the selected line within the view honouring a
// scroll-off margin.
func (v *View) FocusLineWithMargin(line int, margin int, total int) {
	h := v.InnerHeight()
	if h <= 0 {
