package gui

// Direction of a box's children.
type Direction int

const (
	Row    Direction = iota // children stacked vertically
	Column                  // children side by side
)

// Box is a node in the layout tree.
type Box struct {
	Direction           Direction
	Weight              int
	Size                int
	Window              string
	Children            []*Box
	ConditionalChildren func(width, height int) []*Box
}

// Dimensions of a window, inclusive coordinates.
type Dimensions struct {
	X0, Y0, X1, Y1 int
}

// ArrangeWindows computes the dimensions of all windows in the tree.
func ArrangeWindows(root *Box, x0, y0, width, height int) map[string]Dimensions {
	result := map[string]Dimensions{}
	arrange(root, x0, y0, width, height, result)
	return result
}

func arrange(box *Box, x0, y0, width, height int, result map[string]Dimensions) {
	children := box.Children
	if box.ConditionalChildren != nil {
		children = box.ConditionalChildren(width, height)
	}
	if len(children) == 0 {
		if box.Window != "" {
			result[box.Window] = Dimensions{X0: x0, Y0: y0, X1: x0 + width - 1, Y1: y0 + height - 1}
		}
		return
	}
	total := width
	if box.Direction == Row {
		total = height
	}
	sizes := distribute(children, total)
	offset := 0
	for i, child := range children {
		sz := sizes[i]
		if box.Direction == Row {
			arrange(child, x0, y0+offset, width, sz, result)
		} else {
			arrange(child, x0+offset, y0, sz, height, result)
		}
		offset += sz
	}
}

func distribute(children []*Box, total int) []int {
	sizes := make([]int, len(children))
	fixed := 0
	weightSum := 0
	for i, c := range children {
		if c.Weight > 0 {
			weightSum += c.Weight
		} else {
			sizes[i] = c.Size
			fixed += c.Size
		}
	}
	remaining := total - fixed
	if remaining < 0 {
		remaining = 0
	}
	if weightSum > 0 {
		unit := remaining / weightSum
		rem := remaining - unit*weightSum
		for i, c := range children {
			if c.Weight > 0 {
				sizes[i] = unit * c.Weight
				if rem > 0 {
					sizes[i]++
					rem--
				}
			}
		}
	}
	return sizes
}
