	for i, v := range basic {
		palette[i] = colorful.Color{R: float64((v>>16)&0xff) / 255, G: float64((v>>8)&0xff) / 255, B: float64(v&0xff) / 255}
	}
	levels := []int{0, 0x5f, 0x87, 0xaf, 0xd7, 0xff}
	for i := 16; i < 232; i++ {
		idx := i - 16
		r := levels[idx/36]
		g := levels[(idx/6)%6]
		b := levels[idx%6]
		palette[i] = colorful.Color{R: float64(r) / 255, G: float64(g) / 255, B: float64(b) / 255}
	}
	for i := 232; i < 256; i++ {
		v := 8 + 10*(i-232)
		palette[i] = colorful.Color{R: float64(v) / 255, G: float64(v) / 255, B: float64(v) / 255}
	}
}

func nearest(c colorful.Color) int {
