package main

import (
	"fmt"
	"hash/crc32"
	"hash/crc64"
	"hash/fnv"
	"hash/adler32"
	"math"
	"math/rand"
	"crypto/md5"
	"crypto/sha1"
	"encoding/binary"
)

type obs struct {
	name string
	r, g, b int
}

func hsl(r, g, b int) (float64, float64, float64) {
	R, G, B := float64(r)/255, float64(g)/255, float64(b)/255
	max := math.Max(R, math.Max(G, B))
	min := math.Min(R, math.Min(G, B))
	l := (max + min) / 2
	var h, s float64
	if max == min {
		return 0, 0, l
	}
	d := max - min
	if l > 0.5 {
		s = d / (2 - max - min)
	} else {
		s = d / (max + min)
	}
	switch max {
	case R:
		h = (G - B) / d
		if G < B {
			h += 6
		}
	case G:
		h = (B-R)/d + 2
	case B:
		h = (R-G)/d + 4
	}
	h /= 6
	return h, s, l
}

