		if f.HasMergeConflicts {
			f.HasStagedChanges = false
			f.HasUnstagedChanges = true
		}
		files = append(files, f)
	}
	return files
}

// Branches returns local branches sorted by committer date.
func (r *Repo) Branches() ([]*Branch, error) {
	out, err := r.Run("for-each-ref", "--sort=-committerdate", "--format=%(HEAD)%00%(refname:short)%00%(upstream:short)%00%(upstream:track)%00%(push:track)%00%(subject)%00%(objectname)%00%(committerdate:unix)", "refs/heads")
	if err != nil {
		return nil, err
	}
	var branches []*Branch
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" {
			continue
		}
		f := strings.Split(line, "\x00")
		if len(f) < 8 {
			continue
		}
		b := &Branch{
			Head:          f[0] == "*",
			Name:          f[1],
			Upstream:      f[2],
			UpstreamTrack: f[3],
			PushTrack:     f[4],
			Subject:       f[5],
			Hash:          f[6],
		}
		b.CommitterDate, _ = strconv.ParseInt(f[7], 10, 64)
		b.HasUpstream = b.Upstream != ""
		if b.UpstreamTrack == "[gone]" {
			b.UpstreamGone = true
		} else if b.HasUpstream {
			b.Pushables, b.Pullables = parseTrack(b.UpstreamTrack)
		}
		branches = append(branches, b)
	}
	return branches, nil
}

func parseTrack(track string) (string, string) {
	pushables, pullables := "0", "0"
	t := strings.Trim(track, "[]")
	for _, part := range strings.Split(t, ",") {
		part = strings.TrimSpace(part)
		if strings.HasPrefix(part, "ahead ") {
			pushables = strings.TrimPrefix(part, "ahead ")
		} else if strings.HasPrefix(part, "behind ") {
			pullables = strings.TrimPrefix(part, "behind ")
		}
	}
	return pushables, pullables
}

// CurrentBranch returns the current branch name, or a description of HEAD
// when detached.
func (r *Repo) CurrentBranch() (name string, detached bool) {
	out, err := r.Run("branch", "--show-current")
	if err == nil {
		n := strings.TrimSpace(out)
		if n != "" {
			return n, false
		}
	}
	out, err = r.Run("rev-parse", "--short", "HEAD")
	if err != nil {
		return "", true
	}
	return strings.TrimSpace(out), true
}

// HasCommits reports whether HEAD exists.
func (r *Repo) HasCommits() bool {
	_, err := r.Run("rev-parse", "--verify", "--quiet", "HEAD")
	return err == nil
}

// Commits returns up to limit commits reachable from ref.
func (r *Repo) Commits(ref string, limit int, order string, filterPath string) ([]*Commit, error) {
	args := []string{"log", ref, "--" + order, "--oneline", "--pretty=format:+%H%x00%at%x00%aN%x00%ae%x00%P%x00%m%x00%D%x00%s", "--abbrev=40"}
	if limit > 0 {
		args = append(args, "-"+strconv.Itoa(limit))
	}
	args = append(args, "--no-show-signature", "--")
	if filterPath != "" {
		args = append(args, filterPath)
	}
	out, err := r.Run(args...)
	if err != nil {
		return nil, err
	}
	var commits []*Commit
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "+") {
			continue
		}
		f := strings.Split(line[1:], "\x00")
		if len(f) < 8 {
			continue
		}
		c := &Commit{Hash: f[0], AuthorName: f[2], AuthorEmail: f[3], Divergence: f[5], Refs: f[6], Subject: f[7]}
		c.UnixTime, _ = strconv.ParseInt(f[1], 10, 64)
		if f[4] != "" {
			c.Parents = strings.Split(f[4], " ")
		}
		for _, ref := range strings.Split(c.Refs, ", ") {
			ref = strings.TrimSpace(ref)
			if strings.HasPrefix(ref, "tag: ") {
				c.Tags = append(c.Tags, strings.TrimPrefix(ref, "tag: "))
			}
		}
		commits = append(commits, c)
	}
	return commits, nil
}

// Stash returns the stash entries.
func (r *Repo) Stash() ([]*StashEntry, error) {
	out, err := r.Run("stash", "list", "-z", "--pretty=%H|%ct|%gs")
	if err != nil {
		return nil, err
	}
	var entries []*StashEntry
	for i, part := range strings.Split(out, "\x00") {
		if part == "" {
			continue
		}
		f := strings.SplitN(part, "|", 3)
		if len(f) < 3 {
			continue
		}
		e := &StashEntry{Index: i, Hash: f[0], Name: f[2]}
		e.UnixTime, _ = strconv.ParseInt(f[1], 10, 64)
		entries = append(entries, e)
	}
	return entries, nil
}

// Tags returns tags sorted by creation date (newest first).
func (r *Repo) Tags() ([]*Tag, error) {
	out, err := r.Run("tag", "--list", "-n", "--sort=-creatordate")
	if err != nil {
		return nil, err
	}
	var tags []*Tag
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		t := &Tag{Name: fields[0]}
		if idx := strings.Index(line, " "); idx >= 0 {
			t.Message = strings.TrimSpace(line[idx:])
		}
		tags = append(tags, t)
	}
	return tags, nil
}

// Remotes returns the remotes with their branches.
func (r *Repo) Remotes() ([]*Remote, error) {
	out, err := r.Run("remote", "-v")
	if err != nil {
		return nil, err
	}
	var remotes []*Remote
	byName := map[string]*Remote{}
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		rem, ok := byName[fields[0]]
		if !ok {
			rem = &Remote{Name: fields[0]}
			byName[fields[0]] = rem
			remotes = append(remotes, rem)
		}
		if len(fields) >= 3 && fields[2] == "(fetch)" || len(fields) == 2 {
			rem.Urls = append(rem.Urls, fields[1])
		}
	}
	bout, err := r.Run("for-each-ref", "--sort=-committerdate", "--format=%(refname)", "refs/remotes")
	if err == nil {
		for _, line := range strings.Split(strings.TrimRight(bout, "\n"), "\n") {
			ref := strings.TrimPrefix(line, "refs/remotes/")
			if ref == "" {
				continue
			}
			idx := strings.Index(ref, "/")
			if idx < 0 {
				continue
			}
			name := ref[:idx]
			branch := ref[idx+1:]
			if branch == "HEAD" {
				continue
			}
			if rem, ok := byName[name]; ok {
				rem.Branches = append(rem.Branches, branch)
			}
		}
	}
	return remotes, nil
}

// Reflog returns HEAD's reflog entries.
func (r *Repo) Reflog(filterPath string) ([]*ReflogEntry, error) {
	args := []string{"-c", "log.showSignature=false", "log", "-g", "--format=+%H%x00%ct%x00%gs%x00%P"}
	if filterPath != "" {
		args = append(args, "--follow", "--", filterPath)
	}
	out, err := r.Run(args...)
	if err != nil {
		return nil, err
	}
	var entries []*ReflogEntry
	for _, line := range strings.Split(out, "\n") {
		if !strings.HasPrefix(line, "+") {
			continue
		}
		f := strings.Split(line[1:], "\x00")
		if len(f) < 4 {
			continue
		}
		e := &ReflogEntry{Hash: f[0], Name: f[2]}
		e.UnixTime, _ = strconv.ParseInt(f[1], 10, 64)
		if f[3] != "" {
			e.Parents = strings.Split(f[3], " ")
		}
		entries = append(entries, e)
	}
	return entries, nil
}

// Worktrees lists worktrees.
func (r *Repo) Worktrees() ([]*Worktree, error) {
	out, err := r.Run("worktree", "list", "--porcelain")
	if err != nil {
		return nil, err
	}
	var wts []*Worktree
	var cur *Worktree
	for _, line := range strings.Split(out, "\n") {
		switch {
		case strings.HasPrefix(line, "worktree "):
			cur = &Worktree{Path: strings.TrimPrefix(line, "worktree ")}
			cur.IsMain = len(wts) == 0
			wts = append(wts, cur)
		case strings.HasPrefix(line, "HEAD ") && cur != nil:
			cur.Head = strings.TrimPrefix(line, "HEAD ")
		case strings.HasPrefix(line, "branch ") && cur != nil:
			cur.Branch = strings.TrimPrefix(strings.TrimPrefix(line, "branch "), "refs/heads/")
		case line == "bare" && cur != nil:
			cur.Bare = true
		}
	}
	for _, w := range wts {
		if w.Path == r.WorkTree {
			w.IsCurrent = true
		}
	}
	return wts, nil
}

// ConfigGet reads a git config value.
func (r *Repo) ConfigGet(key string) string {
	out, err := r.Run("config", "--get", "--null", key)
	if err != nil {
		return ""
	}
	return strings.TrimRight(out, "\x00\n")
}
