func (n *FileNode) IsDir() bool { return n.File == nil }

// BuildFileTree builds a tree from files. If flat is true a flat list is
// returned (with a nil root wrapper).
func BuildFileTree(files []*git.File, showRoot bool, flat bool) *FileNode {
	root := &FileNode{Path: "", Name: "/"}
	if flat {
		for _, f := range files {
			root.Children = append(root.Children, &FileNode{Path: f.Name, Name: f.Name, File: f, Parent: root})
		}
		sortFlat(root.Children)
		return root
	}
	for _, f := range files {
		parts := strings.Split(f.Name, "/")
		cur := root
		for i, part := range parts {
			if i == len(parts)-1 {
				cur.Children = append(cur.Children, &FileNode{Path: f.Name, Name: part, File: f, Parent: cur})
				break
			}
			var next *FileNode
			for _, c := range cur.Children {
				if c.IsDir() && c.Name == part {
					next = c
					break
				}
			}
			if next == nil {
				p := part
				if cur.Path != "" {
					p = cur.Path + "/" + part
				}
				next = &FileNode{Path: p, Name: part, Parent: cur}
				cur.Children = append(cur.Children, next)
			}
			cur = next
		}
	}
	sortTree(root)
	compressTree(root)
	return root
}

func sortFlat(nodes []*FileNode) {
	sort.SliceStable(nodes, func(i, j int) bool {
		a, b := nodes[i], nodes[j]
		// merge conflicts first
		ac := a.File != nil && a.File.HasMergeConflicts
		bc := b.File != nil && b.File.HasMergeConflicts
		if ac != bc {
			return ac
		}
		return a.Path < b.Path
	})
}

func sortTree(n *FileNode) {
	sort.SliceStable(n.Children, func(i, j int) bool {
		a, b := n.Children[i], n.Children[j]
		if a.IsDir() != b.IsDir() {
			return a.IsDir()
		}
		return a.Name < b.Name
	})
	for _, c := range n.Children {
		if c.IsDir() {
			sortTree(c)
		}
	}
}

// compressTree merges directories that contain exactly one child directory.
func compressTree(n *FileNode) {
	for _, c := range n.Children {
		if !c.IsDir() {
			continue
		}
		for len(c.Children) == 1 && c.Children[0].IsDir() {
			child := c.Children[0]
			c.Name = c.Name + "/" + child.Name
			c.Path = child.Path
			c.Children = child.Children
			for _, gc := range c.Children {
				gc.Parent = c
			}
		}
		compressTree(c)
	}
}

// Flatten returns the visible nodes in display order.
func (n *FileNode) Flatten(collapsed map[string]bool, showRoot bool) []*FileNode {
	var out []*FileNode
	var walk func(node *FileNode, depth int)
	walk = func(node *FileNode, depth int) {
		node.Depth = depth
		out = append(out, node)
		if node.IsDir() && !collapsed[node.Path] {
			for _, c := range node.Children {
				walk(c, depth+1)
			}
		}
	}
	if showRoot && len(n.Children) > 0 {
		walk(n, 0)
	} else {
		for _, c := range n.Children {
			walk(c, 0)
		}
	}
	return out
}

// Files returns all files beneath the node.
func (n *FileNode) Files() []*git.File {
	if n.File != nil {
		return []*git.File{n.File}
	}
	var out []*git.File
	for _, c := range n.Children {
		out = append(out, c.Files()...)
	}
	return out
}
