package gui

import (
	"fmt"
	"strings"
	"time"
	"unicode/utf8"

	"lazygit-clone/internal/git"
	"lazygit-clone/internal/term"
)

var (
	styleDefault = term.DefaultStyle
	styleRed     = term.DefaultStyle.WithFg(term.ColorRed)
	styleGreen   = term.DefaultStyle.WithFg(term.ColorGreen)
	styleYellow  = term.DefaultStyle.WithFg(term.ColorYellow)
	styleBlue    = term.DefaultStyle.WithFg(term.ColorBlue)
	styleMagenta = term.DefaultStyle.WithFg(term.ColorMagenta)
	styleCyan    = term.DefaultStyle.WithFg(term.ColorCyan)
	styleWhite   = term.DefaultStyle.WithFg(term.ColorWhite)
	styleBold    = term.DefaultStyle.Bold()
)

// renderFileNode renders a single node of the file tree.
func renderFileNode(node *FileNode, collapsed bool) Line {
	indent := strings.Repeat("  ", node.Depth)
	if node.IsDir() {
		icon := "▼"
		if collapsed {
			icon = "▶"
		}
		st := dirStyle(node)
		return Line{{Text: indent, Style: styleDefault}, {Text: icon, Style: st}, {Text: " ", Style: styleDefault}, {Text: node.Name, Style: st}}
	}
	f := node.File
	status := f.ShortStatus
	var line Line
	line = append(line, Span{Text: indent, Style: styleDefault})
	name := node.Name
	if f.IsRename {
		name = f.PreviousName + " → " + f.Name
	}
	if f.HasMergeConflicts {
		line = append(line, Span{Text: status, Style: styleRed})
		line = append(line, Span{Text: " " + name, Style: styleRed})
		return line
	}
	if !f.Tracked {
		line = append(line, Span{Text: status, Style: styleRed})
		line = append(line, Span{Text: " " + name, Style: styleDefault})
		return line
	}
	if f.HasStagedChanges && !f.HasUnstagedChanges {
		line = append(line, Span{Text: status + " " + name, Style: styleGreen})
		return line
	}
	// first char (staged part)
	x := status[:1]
	y := status[1:]
	if x != " " {
		line = append(line, Span{Text: x, Style: styleGreen})
	} else {
		line = append(line, Span{Text: x, Style: styleDefault})
	}
	if y != " " {
		line = append(line, Span{Text: y, Style: styleRed})
	} else {
		line = append(line, Span{Text: y, Style: styleDefault})
	}
	nameStyle := styleDefault
	if f.HasStagedChanges && f.HasUnstagedChanges {
		nameStyle = styleYellow
	}
	line = append(line, Span{Text: " " + name, Style: nameStyle})
	return line
}

func dirStyle(node *FileNode) term.Style {
	files := node.Files()
	allStaged := len(files) > 0
	anyStaged := false
	for _, f := range files {
		if f.HasStagedChanges {
			anyStaged = true
		}
		if !f.HasStagedChanges || f.HasUnstagedChanges {
			allStaged = false
		}
	}
	if allStaged {
		return styleGreen
	}
	if anyStaged {
		return styleYellow
	}
	return styleDefault
}

// recency formats a unix time relative to now, e.g. "7s", "4m", "2h", "3d".
