{"command":"cat > /workspace/internal/gui/graph.go <<'EOF'
package gui

import (
	"sort"
	"strings"

	"lazygit-clone/internal/git"
	"lazygit-clone/internal/term"
)

type pipeKind uint8

const (
	pipeTerminates pipeKind = iota
	pipeStarts
	pipeContinues
)

type pipe struct {
	fromPos  int
	toPos    int
	fromHash string
	toHash   string
	kind     pipeKind
	style    term.Style
}

func (p *pipe) left() int {
	if p.fromPos < p.toPos {
		return p.fromPos
	}
	return p.toPos
}

func (p *pipe) right() int {
	if p.fromPos > p.toPos {
		return p.fromPos
	}
	return p.toPos
}

const emptyTreeHash = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"

// getPipeSets computes the pipes for each commit row.
func getPipeSets(commits []*git.Commit, getStyle func(*git.Commit) term.Style) [][]*pipe {
	if len(commits) == 0 {
		return nil
	}
	pipes := []*pipe{{fromPos: 0, toPos: 0, fromHash: "START", toHash: commits[0].Hash, kind: pipeStarts, style: term.DefaultStyle}}
	out := make([][]*pipe, len(commits))
	for i, c := range commits {
		pipes = getNextPipes(pipes, c, getStyle)
		out[i] = pipes
	}
	return out
}

func getNextPipes(prevPipes []*pipe, commit *git.Commit, getStyle func(*git.Commit) term.Style) []*pipe {
	maxPos := 0
	for _, p := range prevPipes {
		if p.toPos > maxPos {
			maxPos = p.toPos
		}
	}
	var current []*pipe
	for _, p := range prevPipes {
		if p.kind != pipeTerminates {
			current = append(current, p)
		}
	}
	newPipes := make([]*pipe, 0, len(current)+len(commit.Parents))
	pos := maxPos + 1
	for _, p := range current {
		if p.toHash == commit.Hash {
			pos = p.toPos
			break
		}
	}
	taken := map[int]bool{}
	traversed := map[int]bool{}

	if len(commit.Parents) > 0 {
		newPipes = append(newPipes, &pipe{fromPos: pos, toPos: pos, fromHash: commit.Hash, toHash: commit.Parents[0], kind: pipeStarts, style: getStyle(commit)})
	} else {
		newPipes = append(newPipes, &pipe{fromPos: pos, toPos: pos, fromHash: commit.Hash, toHash: emptyTreeHash, kind: pipeStarts, style: getStyle(commit)})
	}

	traversedForContinuing := map[int]bool{}
	for _, p := range current {
		if p.toHash != commit.Hash {
			traversedForContinuing[p.toPos] = true
		}
	}

	for _, p := range current {
		if p.toHash == commit.Hash {
			newPipes = append(newPipes, &pipe{fromPos: p.toPos, toPos: pos, fromHash: p.fromHash, toHash: p.toHash, kind: pipeTerminates, style: p.style})
			lo, hi := p.toPos, pos
			if lo > hi {
				lo, hi = hi, lo
			}
			for i := lo; i <= hi; i++ {
				traversed[i] = true
			}
		} else if p.toPos < pos {
			newPipes = append(newPipes, &pipe{fromPos: p.toPos, toPos: p.toPos, fromHash: p.fromHash, toHash: p.toHash, kind: pipeContinues, style: p.style})
			traversed[p.toPos] = true
		}
	}

	if len(commit.Parents) > 1 {
		for _, parent := range commit.Parents[1:] {
			availablePos := pos + 1
			for {
				if !taken[availablePos] && !traversedForContinuing[availablePos] {
					break
				}
				availablePos++
			}
			newPipes = append(newPipes, &pipe{fromPos: pos, toPos: availablePos, fromHash: commit.Hash, toHash: parent, kind: pipeStarts, style: getStyle(commit)})
			taken[availablePos] = true
		}
	}

	for _, p := range current {
		if p.toHash != commit.Hash && p.toPos > pos {
			last := p.toPos
			for i := p.toPos; i > pos; i-- {
				if taken[i] || traversed[i] {
					break
				}
				last = i
			}
			newPipes = append(newPipes, &pipe{fromPos: p.toPos, toPos: last, fromHash: p.fromHash, toHash: p.toHash, kind: pipeContinues, style: p.style})
			taken[last] = true
			lo, hi := last, p.toPos
			for i := lo; i <= hi; i++ {
				traversed[i] = true
			}
		}
	}

	sort.SliceStable(newPipes, func(i, j int) bool {
		if newPipes[i].toPos == newPipes[j].toPos {
			return newPipes[i].kind < newPipes[j].kind
		}
		return newPipes[i].toPos < newPipes[j].toPos
	})
	return newPipes
}

type cellType int

const (
	cellConnection cellType = iota
	cellCommit
	cellMerge
)

type graphCell struct {
	up, down, left, right bool
	typ                   cellType
	style                 term.Style
	rightStyle            *term.Style
}

func (c *graphCell) reset() {
	c.up, c.down, c.left, c.right = false, false, false, false
	c.rightStyle = nil
}

func (c *graphCell) setUp(st term.Style) *graphCell    { c.up = true; c.style = st; return c }
func (c *graphCell) setDown(st term.Style) *graphCell  { c.down = true; c.style = st; return c }
func (c *graphCell) setLeft(st term.Style) *graphCell  { c.left = true; c.style = st; return c }
func (c *graphCell) setRight(st term.Style, override bool) *graphCell {
	c.right = true
	if c.rightStyle == nil || override {
		s := st
		c.rightStyle = &s
	}
	return c
}

func boxChars(up, down, left, right bool) (rune, rune) {
	switch {
	case up && down && left && right:
		return '│', '─'
	case up && down && left && !right:
		return '│', ' '
	case up && down && !left && right:
		return '│', '─'
	case up && down && !left && !right:
		return '│', ' '
	case up && !down && left && right:
		return '┴', '─'
	case up && !down && left && !right:
		return '╯', ' '
	case up && !down && !left && right:
		return '╰', '─'
	case up && !down && !left && !right:
		return '╵', ' '
	case !up && down && left && right:
		return '┬', '─'
	case !up && down && left && !right:
		return '╮', ' '
	case !up && down && !left && right:
		return '╭', '─'
	case !up && down && !left && !right:
		return '╷', ' '
	case !up && !down && left && right:
		return '─', '─'
	case !up && !down && left && !right:
		return '─', ' '
	case !up && !down && !left && right:
		return '╶', '─'
	}
	return ' ', ' '
}

var graphHighlightStyle = term.DefaultStyle.WithFg(term.ColorWhite + 8).Bold()

// renderPipeSet renders a row of the graph into a Line.
func renderPipeSet(pipes []*pipe, selectedHash string, prevCommit *git.Commit) Line {
	maxPos := 0
	commitPos := 0
	startCount := 0
	for _, p := range pipes {
		if p.kind == pipeStarts {
			startCount++
			commitPos = p.fromPos
		} else if p.kind == pipeTerminates {
			commitPos = p.toPos
		}
		if p.toPos > maxPos {
			maxPos = p.toPos
		}
	}
	isMerge := startCount > 1
	cells := make([]*graphCell, maxPos+1)
	for i := range cells {
		cells[i] = &graphCell{typ: cellConnection, style: term.DefaultStyle}
	}
	renderPipe := func(p *pipe, st term.Style, overrideRight bool) {
		left, right := p.left(), p.right()
		if left != right {
			for i := left + 1; i < right; i++ {
				cells[i].setLeft(st).setRight(st, overrideRight)
			}
			cells[left].setRight(st, overrideRight)
			cells[right].setLeft(st)
		}
		if p.kind == pipeStarts || p.kind == pipeContinues {
			cells[p.toPos].setDown(st)
		}
		if p.kind == pipeTerminates || p.kind == pipeContinues {
			cells[p.fromPos].setUp(st)
		}
	}

	highlight := true
	if prevCommit != nil && prevCommit.Hash == selectedHash {
		highlight = false
		for _, p := range pipes {
			if p.fromHash == selectedHash && (p.kind != pipeTerminates || p.fromPos != p.toPos) {
				highlight = true
			}
		}
	}
	var selected, nonSelected []*pipe
	for _, p := range pipes {
		if highlight && p.fromHash == selectedHash {
			selected = append(selected, p)
		} else {
			nonSelected = append(nonSelected, p)
		}
	}
	for _, p := range nonSelected {
		if p.kind == pipeStarts {
			renderPipe(p, p.style, true)
		}
	}
	for _, p := range nonSelected {
		if p.kind != pipeStarts && !(p.kind == pipeTerminates && p.fromPos == commitPos && p.toPos == commitPos) {
			renderPipe(p, p.style, false)
		}
	}
	for _, p := range selected {
		for i := p.left(); i <= p.right(); i++ {
			cells[i].reset()
		}
	}
	for _, p := range selected {
		renderPipe(p, graphHighlightStyle, true)
		if p.toPos == commitPos {
			cells[p.toPos].style = graphHighlightStyle
		}
	}
	if isMerge {
		cells[commitPos].typ = cellMerge
	} else {
		cells[commitPos].typ = cellCommit
	}

	var line Line
	for i, c := range cells {
		first, second := boxChars(c.up, c.down, c.left, c.right)
		switch c.typ {
		case cellCommit:
			first = '◯'
		case cellMerge:
			first = '⏣'
		}
		line = append(line, Span{Text: string(first), Style: c.style})
		if i == len(cells)-1 {
			// trailing character is dropped
			break
		}
		rs := c.style
		if c.rightStyle != nil {
			rs = *c.rightStyle
		}
		if second == ' ' {
			line = append(line, Span{Text: " ", Style: term.DefaultStyle})
		} else {
			line = append(line, Span{Text: string(second), Style: rs})
		}
	}
	return mergeSpans(line)
}

// mergeSpans joins adjacent spans with identical styles.
func mergeSpans(l Line) Line {
	if len(l) == 0 {
		return l
	}
	out := Line{l[0]}
	for _, sp := range l[1:] {
		last := &out[len(out)-1]
		if last.Style == sp.Style {
			last.Text += sp.Text
		} else {
			out = append(out, sp)
		}
	}
	return out
}

// renderCommitGraph renders the graph for all commits.
func renderCommitGraph(commits []*git.Commit, selectedHash string, getStyle func(*git.Commit) term.Style) []Line {
	pipeSets := getPipeSets(commits, getStyle)
	lines := make([]Line, len(commits))
	for i, ps := range pipeSets {
		var prev *git.Commit
		if i > 0 {
			prev = commits[i-1]
		}
		lines[i] = renderPipeSet(ps, selectedHash, prev)
	}
	return lines
}

