}

func (c rgb) lab() (float64, float64, float64) {
	r, g, b := linearize(c.r), linearize(c.g), linearize(c.b)
	x := 0.41239079926595948*r + 0.35758433938387796*g + 0.18048078840183429*b
	y := 0.21263900587151036*r + 0.71516867876775593*g + 0.072192315360733715*b
	z := 0.019330818715591851*r + 0.11919477979462599*g + 0.95053215224966058*b
	fy := labF(y / 1.0)
	l := 1.16*fy - 0.16
	a := 5.0 * (labF(x/0.95047) - fy)
	bb := 2.0 * (fy - labF(z/1.08883))
	return l, a, bb
}

func labDistance(c1, c2 rgb) float64 {
	l1, a1, b1 := c1.lab()
	l2, a2, b2 := c2.lab()
	return math.Sqrt((l1-l2)*(l1-l2) + (a1-a2)*(a1-a2) + (b1-b2)*(b1-b2))
}

var palette256 [256]rgb

func init() {
	basic := []int{0x000000, 0x800000, 0x008000, 0x808000, 0x000080, 0x800080, 0x008080, 0xC0C0C0, 0x808080, 0xFF0000, 0x00FF00, 0xFFFF00, 0x0000FF, 0xFF00FF, 0x00FFFF, 0xFFFFFF}
	for i, v := range basic {
		palette256[i] = rgb{float64((v>>16)&0xff) / 255, float64((v>>8)&0xff) / 255, float64(v&0xff) / 255}
	}
	levels := []int{0, 0x5f, 0x87, 0xaf, 0xd7, 0xff}
	for i := 16; i < 232; i++ {
		idx := i - 16
		palette256[i] = rgb{float64(levels[idx/36]) / 255, float64(levels[(idx/6)%6]) / 255, float64(levels[idx%6]) / 255}
	}
	for i := 232; i < 256; i++ {
		v := float64(8+10*(i-232)) / 255
		palette256[i] = rgb{v, v, v}
	}
}

// nearest256 finds the closest palette colour (CIE76 distance).
func nearest256(r, g, b uint8) term.Color {
	c := rgb{float64(r) / 255, float64(g) / 255, float64(b) / 255}
	best := 0
	bd := math.Inf(1)
	for i, p := range palette256 {
		d := labDistance(c, p)
		if math.IsNaN(d) {
			d = math.Inf(1)
		}
		if d < bd {
			bd = d
			best = i
		}
	}
	return term.Color(best)
}

var trueColorSupported = func() bool {
	switch os.Getenv("COLORTERM") {
	case "truecolor", "24bit", "24-bit":
		return true
	}
	return strings.HasSuffix(os.Getenv("TERM"), "-truecolor")
}()

// RGBColor returns a terminal colour for the given RGB values, downgrading to
// the 256 colour palette when true colour is unavailable.
func RGBColor(r, g, b uint8) term.Color {
	if trueColorSupported {
		return term.RGB(int(r), int(g), int(b))
	}
	return nearest256(r, g, b)
}

var authorStyleCache = map[string]term.Style{}

func hashString(s string) uint64 {
	h := fnv.New64a()
	h.Write([]byte(s))
	return h.Sum64()
}

func randFloat(seed uint64) float64 {
	return rand.New(rand.NewSource(int64(seed))).Float64()
}

// authorStyle returns a deterministic colour for an author name.
func authorStyle(name string, configured map[string]string) term.Style {
	if st, ok := authorStyleCache[name]; ok {
		return st
	}
	if configured != nil {
		if c, ok := configured[name]; ok {
			st := term.DefaultStyle.WithFg(parseColorName(c))
			authorStyleCache[name] = st
			return st
		}
		if c, ok := configured["*"]; ok {
			st := term.DefaultStyle.WithFg(parseColorName(c))
			authorStyleCache[name] = st
			return st
		}
	}
	h := hashString(name)
	c := hslToRGB(randFloat(h)*360.0, 0.6+0.4*randFloat(h+1), 0.4+randFloat(h+2)*0.2)
	st := term.DefaultStyle.WithFg(RGBColor(uint8(c.r*255), uint8(c.g*255), uint8(c.b*255)))
	authorStyleCache[name] = st
	return st
}

// parseColorName converts a lazygit colour name or hex value into a colour.
func parseColorName(name string) term.Color {
	switch strings.ToLower(name) {
	case "default":
		return term.ColorDefault
	case "black":
		return term.ColorBlack
	case "red":
		return term.ColorRed
	case "green":
		return term.ColorGreen
	case "yellow":
		return term.ColorYellow
	case "blue":
		return term.ColorBlue
	case "magenta":
		return term.ColorMagenta
	case "cyan":
		return term.ColorCyan
	case "white":
		return term.ColorWhite
	case "brightblack":
		return term.ColorBlack + 8
	case "brightred":
		return term.ColorRed + 8
	case "brightgreen":
		return term.ColorGreen + 8
	case "brightyellow":
		return term.ColorYellow + 8
	case "brightblue":
		return term.ColorBlue + 8
	case "brightmagenta":
		return term.ColorMagenta + 8
	case "brightcyan":
		return term.ColorCyan + 8
	case "brightwhite":
		return term.ColorWhite + 8
	}
	if strings.HasPrefix(name, "#") && len(name) == 7 {
		var r, g, b int
		n, _ := parseHex(name[1:3]), 0, 0
		r = n
		g = parseHex(name[3:5])
		b = parseHex(name[5:7])
		return RGBColor(uint8(r), uint8(g), uint8(b))
	}
	return term.ColorDefault
}

func parseHex(s string) int {
	v := 0
	for _, c := range s {
		v *= 16
		switch {
		case c >= '0' && c <= '9':
			v += int(c - '0')
		case c >= 'a' && c <= 'f':
			v += int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v += int(c-'A') + 10
		}
	}
	return v
}

// styleFromConfig builds a style from a list of colour/attribute names as used
// in the theme config.
func styleFromConfig(names []string) term.Style {
	st := term.DefaultStyle
	for _, n := range names {
		switch strings.ToLower(n) {
		case "bold":
			st = st.Bold()
		case "underline":
			st = st.Underline()
		case "reverse":
			st = st.WithAttr(term.AttrReverse)
		case "strikethrough":
			st = st.WithAttr(term.AttrStrike)
		case "italic":
			st = st.WithAttr(term.AttrItalic)
		default:
			st.Fg = parseColorName(n)
		}
	}
	return st
}

// bgStyleFromConfig is like styleFromConfig but colours apply to the background.
func bgStyleFromConfig(names []string) term.Style {
	st := term.DefaultStyle
	for _, n := range names {
		switch strings.ToLower(n) {
		case "bold":
			st = st.Bold()
		case "underline":
			st = st.Underline()
		case "reverse":
			st = st.WithAttr(term.AttrReverse)
		default:
			st.Bg = parseColorName(n)
		}
	}
	return st
}
