	"gopkg.in/yaml.v3"
)

// AppState mirrors lazygit's state.yml.
type AppState struct {
	LastUpdateCheck         int64    `yaml:"lastupdatecheck"`
	RecentRepos             []string `yaml:"recentrepos"`
	StartupPopupVersion     int      `yaml:"startuppopupversion"`
	DidShowHunkStagingHint  bool     `yaml:"didshowhunkstaginghint"`
	LastVersion             string   `yaml:"lastversion"`
	CustomCommandsHistory   []string `yaml:"customcommandshistory"`
	HideCommandLog          bool     `yaml:"hidecommandlog"`
	path                    string
}

const StartupPopupVersion = 5

// LoadState loads the state file from dir (creating the directory).
func LoadState(dir string, version string) *AppState {
	st := &AppState{RecentRepos: []string{}, CustomCommandsHistory: []string{}, path: filepath.Join(dir, "state.yml")}
	data, err := os.ReadFile(st.path)
	if err == nil {
		_ = yaml.Unmarshal(data, st)
		if st.RecentRepos == nil {
			st.RecentRepos = []string{}
		}
		if st.CustomCommandsHistory == nil {
			st.CustomCommandsHistory = []string{}
		}
	}
	st.LastVersion = version
	return st
}

// Save writes the state file.
func (s *AppState) Save() error {
	if err := os.MkdirAll(filepath.Dir(s.path), 0o700); err != nil {
		return err
	}
	var buf []byte
	buf, err := marshalState(s)
	if err != nil {
		return err
	}
	return os.WriteFile(s.path, buf, 0o644)
}

func marshalState(s *AppState) ([]byte, error) {
	var b []byte
	enc := &yamlBuf{}
	e := yaml.NewEncoder(enc)
	e.SetIndent(4)
	if err := e.Encode(s); err != nil {
		return nil, err
	}
	e.Close()
	b = enc.data
	return b, nil
}

type yamlBuf struct{ data []byte }

func (y *yamlBuf) Write(p []byte) (int, error) {
	y.data = append(y.data, p...)
	return len(p), nil
}

// AddRecentRepo moves repo to the front of the recent repos list.
func (s *AppState) AddRecentRepo(repo string) {
	out := []string{repo}
	for _, r := range s.RecentRepos {
		if r != repo {
			out = append(out, r)
		}
	}
	s.RecentRepos = out
}
