package gui

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"lazygit-clone/internal/config"
	"lazygit-clone/internal/git"
	"lazygit-clone/internal/term"
)

// ScreenMode controls how much space the focused panel takes.
type ScreenMode int

const (
	ScreenNormal ScreenMode = iota
	ScreenHalf
	ScreenFull
)

// Options passed to the GUI.
type Options struct {
	Config      *config.UserConfig
	State       *AppState
	Repo        *git.Repo
	RepoName    string
	Version     string
	StartupArg  string // "status", "branch", "log", "stash" or ""
	FilterPath  string
	ScreenMode  ScreenMode
	Debug       bool
	LogFunc     func(string)
	NewDirFile  string
}

// Gui is the main application structure.
type Gui struct {
	t     *term.Terminal
	scr   *term.Screen
	cfg   *config.UserConfig
	state *AppState
	repo  *git.Repo
	opts  Options

	mu sync.Mutex

	// model
	files      []*git.File
	fileTree   *FileNode
	fileNodes  []*FileNode
	collapsed  map[string]bool
	branches   []*git.Branch
	currentBranch string
	detached   bool
	commits    []*git.Commit
	reflog     []*git.ReflogEntry
	stash      []*git.StashEntry
	tags       []*git.Tag
	remotes    []*git.Remote
	worktrees  []*git.Worktree
	hasCommits bool
	workingTreeState string // "", "rebasing", "merging", ...

	// ui state
	views          map[string]*View
	windowContexts map[string][]*ListContext // tabs per window
	activeTab      map[string]int
	currentWindow  string
	previousSideWindow string
	screenMode     ScreenMode
	contexts       map[string]*ListContext
	cmdLog         []Line
	cmdLogView     *View
	showCommandLog bool
	popups         []*Popup
	quit           bool
	flatFileTree   bool
	mainTitle      string
	secondaryTitle string
	mainSplit      bool
	mainFocused    bool // "0" pressed
	focusedMainView string // "main" or "secondary"
	lastRefresh    time.Time
	needsRedraw    bool
	searchState    *searchState
	rangeSelect    bool
	// information string components
	informationLine Line
	appStatus      string
	fetchDone      bool
	suspendForEditor func(cmd []string) error
	showRootItem   bool
	// hashes of commits
	unpushedSet    map[string]bool
	unmergedSet    map[string]bool
	authorColors   map[string]string
	now            time.Time
	diffContextSize int
	ignoreWhitespace bool
	renameThreshold int
	toasts         []string
}

type searchState struct {
	active bool
	text   string
	window string
}

// New creates the GUI.
func New(t *term.Terminal, opts Options) *Gui {
	g := &Gui{
		t:              t,
		scr:            t.Screen,
		cfg:            opts.Config,
		state:          opts.State,
		repo:           opts.Repo,
		opts:           opts,
		views:          map[string]*View{},
		windowContexts: map[string][]*ListContext{},
		activeTab:      map[string]int{},
		contexts:       map[string]*ListContext{},
		collapsed:      map[string]bool{},
		screenMode:     opts.ScreenMode,
		focusedMainView: "main",
		showRootItem:   opts.Config.Gui.ShowRootItemInFileTree,
		diffContextSize: opts.Config.Git.DiffContextSize,
		ignoreWhitespace: opts.Config.Git.IgnoreWhitespaceInDiffView,
		renameThreshold: opts.Config.Git.RenameSimilarityThreshold,
	}
	g.flatFileTree = !opts.Config.Gui.ShowFileTree
	g.showCommandLog = opts.Config.Gui.ShowCommandLog && !opts.State.HideCommandLog
	g.authorColors = opts.Config.Gui.AuthorColors
	g.setupViews()
	g.setupContexts()
	g.currentWindow = "files"
	switch opts.StartupArg {
	case "status":
		g.currentWindow = "status"
	case "branch":
		g.currentWindow = "branches"
	case "log":
		g.currentWindow = "commits"
	case "stash":
		g.currentWindow = "stash"
	}
	g.previousSideWindow = g.currentWindow
	g.initCommandLog()
	return g
}

func (g *Gui) log(msg string) {
	if g.opts.LogFunc != nil {
		g.opts.LogFunc(msg)
	}
}

func (g *Gui) setupViews() {
	for _, name := range []string{"status", "files", "branches", "commits", "stash", "main", "secondary", "extras"} {
		v := NewView(name)
		g.views[name] = v
	}
	g.views["main"].CanScrollPastBottom = g.cfg.Gui.ScrollPastBottom
	g.views["secondary"].CanScrollPastBottom = g.cfg.Gui.ScrollPastBottom
	g.views["main"].Wrap = true
	g.views["secondary"].Wrap = true
	g.views["extras"].Wrap = true
	g.views["extras"].ShowScrollbar = false
	g.views["extras"].AutoScrollToBottom = true
	g.views["status"].ShowScrollbar = false
	g.cmdLogView = g.views["extras"]
}

func (g *Gui) initCommandLog() {
	g.cmdLog = nil
	if g.cfg.Gui.ShowRandomTip {
		g.cmdLog = append(g.cmdLog, styled("You can hide/focus this panel by pressing '@'", styleCyan))
		g.cmdLog = append(g.cmdLog, plain(""))
		tip := randomTip()
		parts := strings.Split(tip, "\n")
		first := Line{{Text: "Random tip", Style: styleYellow}, {Text: ": ", Style: styleDefault}, {Text: parts[0], Style: styleGreen}}
		g.cmdLog = append(g.cmdLog, first)
		for _, p := range parts[1:] {
			g.cmdLog = append(g.cmdLog, styled(p, styleGreen))
		}
	}
}

// logCommand appends a command to the command log panel.
func (g *Gui) logCommand(cmd string, isGit bool) {
	g.cmdLog = append(g.cmdLog, styled(cmd, styleDefault))
	if len(g.cmdLog) > 500 {
		g.cmdLog = g.cmdLog[len(g.cmdLog)-500:]
	}
	g.cmdLogView.OriginY = 1 << 30
}

func (g *Gui) logAction(action string) {
	g.cmdLog = append(g.cmdLog, styled(action, styleYellow))
	g.cmdLogView.OriginY = 1 << 30
}

// Run starts the main loop.
func (g *Gui) Run() error {
	g.refreshAll()
	g.updateMainView()
	if !g.cfg.DisableStartupPopups && g.state.StartupPopupVersion < StartupPopupVersion {
		g.showStartupPopup()
	}
	g.draw()

	ticker := time.NewTicker(time.Duration(g.cfg.Refresher.RefreshInterval) * time.Second)
	defer ticker.Stop()
	if g.cfg.Git.AutoFetch {
		go g.backgroundFetch()
	}
	redraw := time.NewTicker(50 * time.Millisecond)
	defer redraw.Stop()
	for !g.quit {
		select {
		case ev := <-g.t.Events():
			g.mu.Lock()
			g.handleEvent(ev)
			g.needsRedraw = true
			g.mu.Unlock()
		case <-ticker.C:
			g.mu.Lock()
			if g.cfg.Git.AutoRefresh {
				g.refreshAll()
				g.updateMainView()
				g.needsRedraw = true
			}
			g.mu.Unlock()
		case <-redraw.C:
			g.mu.Lock()
			if g.needsRedraw {
				g.draw()
				g.needsRedraw = false
			}
			g.mu.Unlock()
		}
		if g.quit {
			break
		}
		g.mu.Lock()
		g.draw()
		g.needsRedraw = false
		g.mu.Unlock()
	}
	return nil
}

func (g *Gui) backgroundFetch() {
	for {
		if g.quit {
			return
		}
		if len(g.remotes) > 0 || !g.fetchDone {
			g.repo.Run("fetch", "--all", "--no-write-fetch-head")
			g.mu.Lock()
			g.fetchDone = true
			g.refreshBranches()
			g.refreshCommits()
			g.needsRedraw = true
			g.mu.Unlock()
		}
		time.Sleep(time.Duration(g.cfg.Refresher.FetchInterval) * time.Second)
	}
}

func (g *Gui) handleEvent(ev term.Event) {
	switch ev.Key {
	case term.KeyResize:
		g.scr.Resize(ev.W, ev.H)
		return
	case term.KeyMouse:
		g.handleMouse(ev)
		return
	}
	name := ev.Name()
	if name == "" {
		return
	}
	g.handleKey(name, ev)
}

// ---------------------------------------------------------------------------
// model refresh

func (g *Gui) refreshAll() {
	g.now = time.Now()
	g.hasCommits = g.repo.HasCommits()
	g.refreshFiles()
	g.refreshBranches()
	g.refreshCommits()
	g.refreshReflog()
	g.refreshStash()
	g.refreshTags()
	g.refreshRemotes()
	g.refreshWorktrees()
	g.refreshWorkingTreeState()
	g.refreshContexts()
}

func (g *Gui) refreshWorkingTreeState() {
	gitDir := g.repo.GitDir
	exists := func(p string) bool {
		_, err := os.Stat(filepath.Join(gitDir, p))
		return err == nil
	}
	switch {
	case exists("rebase-merge") || exists("rebase-apply"):
		g.workingTreeState = "rebasing"
	case exists("MERGE_HEAD"):
		g.workingTreeState = "merging"
	case exists("CHERRY_PICK_HEAD"):
		g.workingTreeState = "cherry-picking"
	case exists("REVERT_HEAD"):
		g.workingTreeState = "reverting"
	case exists("BISECT_LOG"):
		g.workingTreeState = "bisecting"
	default:
		g.workingTreeState = ""
	}
}

func (g *Gui) refreshFiles() {
	files, err := g.repo.Status(g.renameThreshold)
	if err == nil {
		g.files = files
	}
	g.rebuildFileTree()
}

func (g *Gui) rebuildFileTree() {
	prevSelectedPath := ""
	if ctx := g.contexts["files"]; ctx != nil && ctx.selected < len(g.fileNodes) && ctx.selected >= 0 {
		prevSelectedPath = g.fileNodes[ctx.selected].Path
	}
	g.fileTree = BuildFileTree(g.files, g.showRootItem, g.flatFileTree)
	g.fileNodes = g.fileTree.Flatten(g.collapsed, g.showRootItem && !g.flatFileTree)
	if ctx := g.contexts["files"]; ctx != nil {
		if prevSelectedPath != "" {
			for i, n := range g.fileNodes {
				if n.Path == prevSelectedPath {
					ctx.selected = i
					break
				}
			}
		}
		ctx.clampSelection()
	}
}

func (g *Gui) refreshBranches() {
	branches, err := g.repo.Branches()
	if err == nil {
		g.branches = branches
	}
	g.currentBranch, g.detached = g.repo.CurrentBranch()
	if g.detached {
		// detached head: add a pseudo branch at the top
		g.branches = append([]*git.Branch{{Name: g.currentBranch, Head: true, Detached: true}}, g.branches...)
	} else {
		found := false
		for _, b := range g.branches {
			if b.Head {
				found = true
			}
		}
		if !found && g.currentBranch != "" {
			g.branches = append([]*git.Branch{{Name: g.currentBranch, Head: true}}, g.branches...)
		}
	}
	if ctx := g.contexts["localBranches"]; ctx != nil {
		ctx.clampSelection()
	}
}

func (g *Gui) mainBranchRefs() []string {
	var refs []string
	for _, name := range g.cfg.Git.MainBranches {
		if _, err := g.repo.Run("rev-parse", "--verify", "--quiet", "refs/remotes/origin/"+name); err == nil {
			refs = append(refs, "refs/remotes/origin/"+name)
			continue
		}
		if _, err := g.repo.Run("rev-parse", "--verify", "--quiet", "refs/heads/"+name); err == nil {
			refs = append(refs, "refs/heads/"+name)
		}
	}
	return refs
}

func (g *Gui) refreshCommits() {
	if !g.hasCommits {
		g.commits = nil
		return
	}
	commits, err := g.repo.Commits("HEAD", 300, g.cfg.Git.Log.Order, g.opts.FilterPath)
	if err != nil {
		return
	}
	mainRefs := g.mainBranchRefs()
	g.unmergedSet = map[string]bool{}
	g.unpushedSet = map[string]bool{}
	if len(mainRefs) > 0 {
		args := []string{"rev-list", "HEAD"}
		for _, r := range mainRefs {
			args = append(args, "^"+r)
		}
		out, err := g.repo.Run(args...)
		if err == nil {
			for _, h := range strings.Fields(out) {
				g.unmergedSet[h] = true
			}
		}
	}
	var cur *git.Branch
	for _, b := range g.branches {
		if b.Head {
			cur = b
		}
	}
	if cur != nil && cur.HasUpstream && !cur.UpstreamGone {
		args := []string{"rev-list", "refs/heads/" + cur.Name, "^" + cur.Name + "@{u}"}
		for _, r := range mainRefs {
			args = append(args, "^"+r)
		}
		out, err := g.repo.Run(args...)
		if err == nil {
			for _, h := range strings.Fields(out) {
				g.unpushedSet[h] = true
			}
		}
	}
	for _, c := range commits {
		switch {
		case g.unpushedSet[c.Hash]:
			c.Status = "unpushed"
		case g.unmergedSet[c.Hash]:
			c.Status = "pushed"
		default:
			c.Status = "merged"
		}
	}
	g.commits = commits
	if ctx := g.contexts["commits"]; ctx != nil {
		ctx.clampSelection()
	}
}

func (g *Gui) refreshReflog() {
	entries, err := g.repo.Reflog(g.opts.FilterPath)
	if err == nil {
		g.reflog = entries
	}
}

func (g *Gui) refreshStash() {
	entries, err := g.repo.Stash()
	if err == nil {
		g.stash = entries
	}
	if ctx := g.contexts["stash"]; ctx != nil {
		ctx.clampSelection()
	}
}

func (g *Gui) refreshTags() {
	tags, err := g.repo.Tags()
	if err == nil {
		g.tags = tags
	}
}

func (g *Gui) refreshRemotes() {
	remotes, err := g.repo.Remotes()
	if err == nil {
		g.remotes = remotes
	}
}

func (g *Gui) refreshWorktrees() {
	wts, err := g.repo.Worktrees()
	if err == nil {
		g.worktrees = wts
	}
}

func (g *Gui) refreshContexts() {
	for _, ctx := range g.contexts {
		ctx.clampSelection()
	}
}

// ---------------------------------------------------------------------------
// misc helpers

func (g *Gui) currentContext() *ListContext {
	if len(g.popups) > 0 {
		return nil
	}
	return g.activeContextForWindow(g.currentWindow)
}

func (g *Gui) activeContextForWindow(window string) *ListContext {
	ctxs := g.windowContexts[window]
	if len(ctxs) == 0 {
		return nil
	}
	idx := g.activeTab[window]
	if idx >= len(ctxs) {
		idx = 0
	}
	return ctxs[idx]
}

func (g *Gui) currentSideWindow() string {
	if g.currentWindow == "main" || g.currentWindow == "secondary" || g.currentWindow == "extras" {
		return g.previousSideWindow
	}
	return g.currentWindow
}

func (g *Gui) Quit() {
	g.quit = true
}

func (g *Gui) errorf(format string, args ...interface{}) {
	g.showErrorPopup(fmt.Sprintf(format, args...))
}
