func (g *Gui) rebuildFileTree() {
	prevSelectedPath := ""
	if ctx := g.contexts["files"]; ctx != nil && ctx.selected < len(g.fileNodes) && ctx.selected >= 0 {
		prevSelectedPath = g.fileNodes[ctx.selected].Path
	}
	g.fileTree = BuildFileTree(g.files, g.showRootItem, g.flatFileTree)
	g.fileNodes = g.fileTree.Flatten(g.collapsed, g.showRootItem && !g.flatFileTree)
	if ctx := g.contexts["files"]; ctx != nil {
		if prevSelectedPath != "" {
			for i, n := range g.fileNodes {
				if n.Path == prevSelectedPath {
