// ListContext is a tab within a window showing a list of items.
type ListContext struct {
	key      string
	window   string
	title    string
	selected int
	rangeStart int // -1 when no range selection
	g        *Gui

	getLen  func() int
	render  func() []Line
	// options for the bottom line (when focused)
	options func() []string
	// called to update the main view for the selection
	updateMain func()
	// optional key handler; returns true if handled
	handleKey func(name string) bool
	// whether an empty list hides the footer count
	noFooter bool
	// cached lines
	lines []Line
}

func (c *ListContext) length() int {
	if c.getLen == nil {
		return 0
	}
	return c.getLen()
}

func (c *ListContext) clampSelection() {
	n := c.length()
	if c.selected >= n {
		c.selected = n - 1
	}
	if c.selected < 0 {
		c.selected = 0
	}
	if c.rangeStart >= n {
		c.rangeStart = n - 1
	}
}

func (c *ListContext) selectionRange() (int, int) {
	if c.rangeStart < 0 {
		return c.selected, c.selected
	}
	if c.rangeStart < c.selected {
		return c.rangeStart, c.selected
	}
	return c.selected, c.rangeStart
}

func (g *Gui) newListContext(key, window, title string) *ListContext {
	ctx := &ListContext{key: key, window: window, title: title, g: g, rangeStart: -1}
	g.contexts[key] = ctx
	g.windowContexts[window] = append(g.windowContexts[window], ctx)
