	tags.updateMain = g.updateTagsMain

	// commits
	commits := g.newListContext("commits", "commits", "Commits")
	commits.getLen = func() int { return len(g.commits) }
	commits.render = g.renderCommits
	commits.options = g.commitsOptions
	commits.updateMain = g.updateCommitsMain
	commits.handleKey = g.handleCommitsKey

	reflog := g.newListContext("reflog", "commits", "Reflog")
	reflog.getLen = func() int { return len(g.reflog) }
	reflog.render = func() []Line { return renderReflog(g.reflog, g.cfg.Gui.CommitHashLength) }
	reflog.options = func() []string {
		return []string{"Checkout: <space>", "Reset: g", "Copy (cherry-pick): C", "Keybindings: ?"}
	}
	reflog.updateMain = g.updateReflogMain

	// stash
	stash := g.newListContext("stash", "stash", "Stash")
	stash.getLen = func() int { return len(g.stash) }
	stash.render = func() []Line { return renderStashEntries(g.stash, g.now) }
	stash.options = g.stashOptions
	stash.updateMain = g.updateStashMain
	stash.handleKey = g.handleStashKey
}

