// renderers

func (g *Gui) renderStatus() []Line {
	var line Line
	var cur *git.Branch
	for _, b := range g.branches {
		if b.Head {
			cur = b
			break
		}
	}
	if g.workingTreeState != "" {
		line = append(line, Span{Text: "(" + g.workingTreeState + ") ", Style: styleYellow})
	}
	if cur != nil {
		if st := branchStatus(cur); len(st) > 0 {
			line = append(line, st...)
			line = append(line, Span{Text: " ", Style: styleDefault})
		}
	}
	line = append(line, Span{Text: g.opts.RepoName + " → ", Style: styleDefault})
	name := g.currentBranch
	if cur != nil {
		name = cur.Name
	}
	line = append(line, Span{Text: name, Style: styleDefault})
	return []Line{line}
}

func (g *Gui) renderFiles() []Line {
	lines := make([]Line, len(g.fileNodes))
	for i, n := range g.fileNodes {
		lines[i] = renderFileNode(n, g.collapsed[n.Path])
	}
	return lines
}

func (g *Gui) renderWorktrees() []Line {
	lines := make([]Line, len(g.worktrees))
	for i, w := range g.worktrees {
		name := filepath.Base(w.Path)
		var l Line
		if w.IsCurrent {
			l = append(l, Span{Text: "* " + name, Style: styleGreen})
		} else {
			l = append(l, Span{Text: "  " + name, Style: styleDefault})
		}
		if w.IsMain {
			l = append(l, Span{Text: " (main)", Style: styleDefault})
		}
		lines[i] = l
	}
	return lines
}

func (g *Gui) renderLocalBranches() []Line {
	return renderBranches(g.branches, g.now)
}

func (g *Gui) renderRemotes() []Line {
	lines := make([]Line, len(g.remotes))
	for i, r := range g.remotes {
		url := ""
		if len(r.Urls) > 0 {
			url = r.Urls[0]
		}
		lines[i] = Line{{Text: r.Name, Style: styleDefault}, {Text: " " + url, Style: styleDefault}}
	}
	return lines
}

func (g *Gui) commitAuthorStyle(c *git.Commit) term.Style {
	return authorStyle(c.AuthorName, g.authorColors)
}

func (g *Gui) renderCommits() []Line {
	ctx := g.contexts["commits"]
	selectedHash := ""
	if ctx != nil && ctx.selected >= 0 && ctx.selected < len(g.commits) {
		selectedHash = g.commits[ctx.selected].Hash
	}
	var graphLines []Line
	if g.cfg.Git.Log.ShowGraph != "never" {
		graphLines = renderCommitGraph(g.commits, selectedHash, g.commitAuthorStyle)
	}
	lines := make([]Line, len(g.commits))
	hashLen := g.cfg.Gui.CommitHashLength
	for i, c := range g.commits {
		var l Line
		hash := c.Hash
		if len(hash) > hashLen {
			hash = hash[:hashLen]
		}
		hashStyle := styleGreen
		switch c.Status {
		case "unpushed":
			hashStyle = styleRed
		case "pushed":
			hashStyle = styleYellow
		case "merged":
			hashStyle = styleGreen
		}
		l = append(l, Span{Text: hash, Style: hashStyle})
		l = append(l, Span{Text: " ", Style: styleDefault})
		author := padToWidth(authorInitials(c.AuthorName, g.cfg.Gui.CommitAuthorShortLength), g.cfg.Gui.CommitAuthorShortLength)
		l = append(l, Span{Text: author, Style: g.commitAuthorStyle(c)})
		l = append(l, Span{Text: " ", Style: styleDefault})
		if graphLines != nil {
			l = append(l, graphLines[i]...)
			l = append(l, Span{Text: " ", Style: styleDefault})
		}
		for _, t := range c.Tags {
			l = append(l, Span{Text: t, Style: styleMagenta.Bold()})
			l = append(l, Span{Text: " ", Style: styleDefault})
		}
		l = append(l, Span{Text: c.Subject, Style: styleDefault})
		lines[i] = l
	}
	return lines
}

