func (g *Gui) setMainContent(title string, content string, split bool) {
	g.mainTitle = title
	g.mainSplit = split
	v := g.views["main"]
	prevOrigin := v.OriginY
	v.SetText(content)
	v.OriginY = prevOrigin
	if v.OriginY > v.MaxOrigin() {
		v.OriginY = v.MaxOrigin()
	}
}

func (g *Gui) setSecondaryContent(title string, content string) {
	g.secondaryTitle = title
	v := g.views["secondary"]
	v.SetText(content)
	if v.OriginY > v.MaxOrigin() {
		v.OriginY = v.MaxOrigin()
	}
}

func (g *Gui) resetMainOrigin() {
	g.views["main"].OriginY = 0
	g.views["main"].OriginX = 0
	g.views["secondary"].OriginY = 0
	g.views["secondary"].OriginX = 0
}

func (g *Gui) updateMainView() {
	if len(g.popups) > 0 {
		return
	}
	ctx := g.activeContextForWindow(g.currentSideWindow())
	if ctx != nil && ctx.updateMain != nil {
		ctx.updateMain()
	}
}

func (g *Gui) diffArgs() []string {
	args := []string{"diff", "--no-ext-diff", "--submodule", fmt.Sprintf("--unified=%d", g.diffContextSize), "--color=always"}
	if g.ignoreWhitespace {
		args = append(args, "--ignore-all-space")
	}
	args = append(args, fmt.Sprintf("--find-renames=%d%%", g.renameThreshold))
	return args
}

func (g *Gui) workTreeDiff(path string, cached bool, untracked bool) string {
	args := append([]string{"-C", g.repo.WorkTree}, g.diffArgs()...)
	if untracked {
		args = append(args, "--no-index", "--", "/dev/null", path)
		out, _ := g.repo.Run(args...)
		return out
	}
	if cached {
		args = append(args, "--cached")
	}
	args = append(args, "--", path)
	out, _ := g.repo.Run(args...)
	return out
}

func (g *Gui) updateFilesMain() {
	node := g.selectedFileNode()
	if node == nil {
		g.setMainContent("Diff", "No changed files", false)
		return
	}
	if node.IsDir() {
		files := node.Files()
		anyStaged, anyUnstaged := false, false
		for _, f := range files {
			if f.HasStagedChanges {
				anyStaged = true
			}
			if f.HasUnstagedChanges {
				anyUnstaged = true
			}
		}
		path := node.Path
		if path == "" {
			path = "."
		}
		unstaged := g.workTreeDiff(path, false, false)
		staged := g.workTreeDiff(path, true, false)
		if anyStaged && anyUnstaged {
			g.setMainContent("Unstaged changes", unstaged, true)
			g.setSecondaryContent("Staged changes", staged)
		} else if anyStaged {
			g.setMainContent("Staged changes", staged, false)
		} else {
			g.setMainContent("Unstaged changes", unstaged, false)
		}
		return
	}
	f := node.File
	if !f.Tracked {
		g.setMainContent("Unstaged changes", g.workTreeDiff(f.Name, false, true), false)
		return
	}
	if f.HasMergeConflicts {
		content, _ := g.repo.Run("-C", g.repo.WorkTree, "diff", "--no-ext-diff", "--color=always", "--", f.Name)
		g.setMainContent("Unstaged changes", content, false)
		return
	}
	if f.HasStagedChanges && f.HasUnstagedChanges {
		g.setMainContent("Unstaged changes", g.workTreeDiff(f.Name, false, false), true)
		g.setSecondaryContent("Staged changes", g.workTreeDiff(f.Name, true, false))
	} else if f.HasStagedChanges {
		g.setMainContent("Staged changes", g.workTreeDiff(f.Name, true, false), false)
	} else {
		g.setMainContent("Unstaged changes", g.workTreeDiff(f.Name, false, false), false)
	}
}

func (g *Gui) updateStatusMain() {
	g.setMainContent("Status", g.statusDashboard(), false)
}

func (g *Gui) statusDashboard() string {
	year := g.now.Year()
	if year == 1 {
		year = time.Now().Year()
	}
	lines := []string{
		lazygitLogo,
		fmt.Sprintf("Copyright %d Jesse Duffield", year),
		"",
		"Keybindings:",
		"https://github.com/jesseduffield/lazygit/blob/master/docs/keybindings",
		"",
		"Config Options:",
		"https://github.com/jesseduffield/lazygit/blob/master/docs/Config.md",
		"",
		"Tutorial: https://youtu.be/VDXvbHZYeKY",
		"",
		"Raise an Issue: https://github.com/jesseduffield/lazygit/issues",
		"",
		"Release Notes: https://github.com/jesseduffield/lazygit/releases",
		"",
		"Become a sponsor: https://github.com/sponsors/jesseduffield",
	}
	return strings.Join(lines, "\n")
}

func (g *Gui) updateBranchesMain() {
	b := g.selectedBranch()
	if b == nil {
		g.setMainContent("Log", "No branches for this repo", false)
		return
	}
	ref := "refs/heads/" + b.Name
	if b.Detached {
		ref = b.Name
	}
	cmd := strings.ReplaceAll(g.cfg.Git.BranchLogCmd, "{{branchName}}", ref)
	out, _ := g.repo.RunShell(cmd)
	g.setMainContent("Log", out, false)
}

func (g *Gui) updateRemotesMain() {
	r := g.selectedRemote()
	if r == nil {
		g.setMainContent("Remote", "No remotes", false)
		return
	}
	var b strings.Builder
	b.WriteString(r.Name + "\n")
	for _, u := range r.Urls {
		b.WriteString(u + "\n")
	}
	g.setMainContent("Remote", b.String(), false)
}

func (g *Gui) updateTagsMain() {
	t := g.selectedTag()
	if t == nil {
		g.setMainContent("Tag", "No tags", false)
		return
	}
	cmd := strings.ReplaceAll(g.cfg.Git.BranchLogCmd, "{{branchName}}", t.Name)
	out, _ := g.repo.RunShell(cmd)
	g.setMainContent("Tag", out, false)
}

func (g *Gui) showCommand(hash string) string {
	out, _ := g.repo.Run("-C", g.repo.WorkTree, "-c", "diff.noprefix=false", "show", "--no-ext-diff", "--submodule", "--color=always", fmt.Sprintf("--unified=%d", g.diffContextSize), "--stat", "--decorate", "-p", hash, fmt.Sprintf("--find-renames=%d%%", g.renameThreshold), "--")
	return out
}

func (g *Gui) updateCommitsMain() {
	c := g.selectedCommit()
	if c == nil {
		g.setMainContent("Patch", "No commits for this branch", false)
		return
	}
	g.setMainContent("Patch", g.showCommand(c.Hash), false)
}

func (g *Gui) updateReflogMain() {
	e := g.selectedReflog()
	if e == nil {
		g.setMainContent("Reflog Entry", "No reflog history", false)
		return
	}
	g.setMainContent("Reflog Entry", g.showCommand(e.Hash), false)
}

func (g *Gui) updateStashMain() {
	e := g.selectedStash()
	if e == nil {
		g.setMainContent("Stash", "No stash entries", false)
		return
	}
	out, _ := g.repo.Run("-C", g.repo.WorkTree, "stash", "show", "-p", "--stat", "-u", "--no-ext-diff", "--color=always", fmt.Sprintf("--unified=%d", g.diffContextSize), fmt.Sprintf("--find-renames=%d%%", g.renameThreshold), fmt.Sprintf("refs/stash@{%d}", e.Index))
	g.setMainContent("Stash", out, false)
}

func (g *Gui) updateWorktreesMain() {
	g.setMainContent("Worktree", "", false)
}
