func (g *Gui) sidePanelChildren(width, height int) []*Box {
	current := g.currentSideWindow()
	if g.screenMode == ScreenHalf || g.screenMode == ScreenFull {
		box := func(w string) *Box {
			if w == current {
				return &Box{Window: w, Weight: 1}
			}
			return &Box{Window: w, Size: 0}
		}
		return []*Box{box("status"), box("files"), box("branches"), box("commits"), box("stash")}
	}
	if height >= 28 {
		accordion := g.cfg.Gui.ExpandFocusedSidePanel
		weighted := func(w string) *Box {
			if accordion && w == current {
				weight := g.cfg.Gui.ExpandedSidePanelWeight
				if weight < 1 {
					weight = 2
				}
				return &Box{Window: w, Weight: weight}
			}
			return &Box{Window: w, Weight: 1}
		}
		stashBox := &Box{Window: "stash", Size: 3}
		if current == "stash" {
			stashBox = weighted("stash")
		}
		return []*Box{
			{Window: "status", Size: 3},
			weighted("files"),
			weighted("branches"),
			weighted("commits"),
			stashBox,
		}
	}
	squashed := 1
	if height >= 21 {
		squashed = 3
	}
	box := func(w string) *Box {
		if w == current {
			return &Box{Window: w, Weight: 1}
		}
		return &Box{Window: w, Size: squashed}
	}
	return []*Box{box("status"), box("files"), box("branches"), box("commits"), box("stash")}
}

func (g *Gui) splitMainPanelSideBySide(width, height int) bool {
	if !g.mainSplit {
		return false
	}
	switch g.cfg.Gui.MainPanelSplitMode {
	case "vertical":
		return false
	case "horizontal":
		return true
	}
	if width < 200 && height > 30 {
		return false
	}
	return true
}

func (g *Gui) extrasWindowSize(height int) int {
	if !g.showCommandLog {
		return 0
	}
	if height < 40 {
		return 3
	}
	size := g.cfg.Gui.CommandLogSize
	if size <= 0 {
		size = 8
	}
	return size + 2
}

func (g *Gui) portraitMode(width, height int) bool {
	switch g.cfg.Gui.PortraitMode {
	case "always":
		return true
	case "never":
		return false
	}
	return width <= 84 && height > 45
}

func (g *Gui) midSectionWeights(width, height int) (int, int) {
	ratio := g.cfg.Gui.SidePanelWidth
	if ratio <= 0 || ratio >= 1 {
		ratio = 0.3333
	}
	mainWeight := int(1/ratio) - 1
	sideWeight := 1
	if g.splitMainPanelSideBySide(width, height) {
		mainWeight = sideWeight * 5
	}
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		if g.screenMode == ScreenHalf || g.screenMode == ScreenFull {
			sideWeight = 0
		}
	} else {
		if g.screenMode == ScreenHalf {
			mainWeight = 1
		} else if g.screenMode == ScreenFull {
			mainWeight = 0
		}
	}
	return sideWeight, mainWeight
}

func (g *Gui) windowDimensions() map[string]Dimensions {
	width, height := g.scr.Size()
	sideWeight, mainWeight := g.midSectionWeights(width, height)
	sideDirection := Column
	if g.portraitMode(width, height) {
		sideDirection = Row
	}
	mainDirection := Row
	if g.splitMainPanelSideBySide(width, height) {
		mainDirection = Column
	}
	var mainChildren []*Box
	if g.mainSplit {
		mainChildren = []*Box{{Window: "main", Weight: 1}, {Window: "secondary", Weight: 1}}
	} else {
		mainChildren = []*Box{{Window: "main", Weight: 1}}
	}
	infoSize := 0
	if g.cfg.Gui.ShowBottomLine || g.searchState != nil {
		infoSize = 1
	}
	root := &Box{
		Direction: Row,
		Children: []*Box{
			{
				Direction: sideDirection,
				Weight:    1,
				Children: []*Box{
					{Direction: Row, Weight: sideWeight, ConditionalChildren: g.sidePanelChildren},
					{
						Direction: Row,
						Weight:    mainWeight,
						Children: []*Box{
							{Direction: mainDirection, Weight: 1, Children: mainChildren},
							{Window: "extras", Size: g.extrasWindowSize(height)},
						},
					},
				},
			},
			{
				Direction: Column,
				Size:      infoSize,
				Children: []*Box{
					{Window: "options", Weight: 1},
					{Window: "information", Size: 1},
				},
			},
		},
	}
	return ArrangeWindows(root, 0, 0, width, height)
}

func (g *Gui) frameStyle(window string) term.Style {
	if window == g.currentWindow && len(g.popups) == 0 {
		return styleFromConfig(g.cfg.Gui.Theme.ActiveBorderColor)
	}
	if window == g.currentWindow && len(g.popups) > 0 {
		return styleFromConfig(g.cfg.Gui.Theme.InactiveBorderColor)
	}
	return styleFromConfig(g.cfg.Gui.Theme.InactiveBorderColor)
}

var windowJumpNumbers = map[string]string{"status": "1", "files": "2", "branches": "3", "commits": "4", "stash": "5", "main": "0"}

// windowTitle builds the styled title for a side window with its tabs.
func (g *Gui) windowTitle(window string, frameSt term.Style) Line {
	var title Line
	if g.cfg.Gui.ShowPanelJumps {
		if n, ok := windowJumpNumbers[window]; ok {
			title = append(title, Span{Text: "[" + n + "]─", Style: frameSt})
		}
	}
	ctxs := g.windowContexts[window]
	if len(ctxs) <= 1 {
		if len(ctxs) == 1 {
			title = append(title, Span{Text: ctxs[0].title, Style: frameSt})
		}
		return title
	}
	active := g.activeTab[window]
	focused := window == g.currentWindow && len(g.popups) == 0
	for i, ctx := range ctxs {
		if i == active {
			st := styleGreen
			if focused {
				st = frameSt
			}
			text := ctx.title
			if i < len(ctxs)-1 {
				text += " "
			}
			title = append(title, Span{Text: text, Style: st})
			if i < len(ctxs)-1 {
				title = append(title, Span{Text: "- ", Style: styleDefault})
			}
		} else {
			text := ctx.title
			if i < len(ctxs)-1 {
				text += " - "
			}
			title = append(title, Span{Text: text, Style: styleDefault})
		}
	}
	return title
}

func (g *Gui) footerFor(ctx *ListContext) string {
	if ctx == nil || ctx.noFooter || !g.cfg.Gui.ShowListFooter {
		return ""
	}
	n := ctx.length()
	if n == 0 {
		return "0 of 0"
	}
	if ctx.rangeStart >= 0 && ctx.rangeStart != ctx.selected {
		lo, hi := ctx.selectionRange()
		return fmt.Sprintf("%d-%d of %d", lo+1, hi+1, n)
	}
	return fmt.Sprintf("%d of %d", ctx.selected+1, n)
}

// draw renders the whole screen.
func (g *Gui) draw() {
	g.scr.Clear()
	g.scr.HideCursor()
	dims := g.windowDimensions()
	width, height := g.scr.Size()

	// side windows
	for _, window := range []string{"status", "files", "branches", "commits", "stash"} {
		v := g.views[window]
		d, ok := dims[window]
		if !ok || d.X1 < d.X0 || d.Y1 < d.Y0 {
			v.Visible = false
			continue
		}
		v.Visible = true
		v.X0, v.Y0, v.X1, v.Y1 = d.X0, d.Y0, d.X1, d.Y1
		st := g.frameStyle(window)
		v.FrameStyle = st
		v.Title = g.windowTitle(window, st)
		ctx := g.activeContextForWindow(window)
		v.Footer = g.footerFor(ctx)
		if ctx != nil {
			lines := ctx.render()
			ctx.lines = lines
			v.SetContent(lines)
			focused := window == g.currentWindow && len(g.popups) == 0
			v.Highlight = focused && ctx.length() > 0
			lo, hi := ctx.selectionRange()
			v.SelStart, v.SelEnd = lo, hi
			v.SelBg = g.selectedLineBg()
			// keep selection visible
			if ctx.length() > 0 {
				v.FocusLineWithMargin(ctx.selected, g.cfg.Gui.ScrollOffMargin, ctx.length())
				if v.InnerHeight() > 0 && v.OriginY > v.MaxOrigin() {
					v.OriginY = v.MaxOrigin()
				}
			} else {
				v.OriginY = 0
			}
		}
		v.Draw(g.scr)
	}

	// main views
	mainSt := g.frameStyle("main")
	if g.currentWindow == "secondary" {
		mainSt = g.frameStyle("secondary")
	}
	_ = mainSt
	if d, ok := dims["main"]; ok {
		v := g.views["main"]
		v.Visible = true
		v.X0, v.Y0, v.X1, v.Y1 = d.X0, d.Y0, d.X1, d.Y1
		v.FrameStyle = g.frameStyle("main")
		var title Line
		if g.cfg.Gui.ShowPanelJumps {
			title = append(title, Span{Text: "[0]─", Style: v.FrameStyle})
		}
		title = append(title, Span{Text: g.mainTitle, Style: v.FrameStyle})
		v.Title = title
		v.Footer = ""
		v.Highlight = false
		if v.OriginY > v.MaxOrigin() {
			v.OriginY = v.MaxOrigin()
		}
		v.Draw(g.scr)
	}
	if d, ok := dims["secondary"]; ok && g.mainSplit {
		v := g.views["secondary"]
		v.Visible = true
		v.X0, v.Y0, v.X1, v.Y1 = d.X0, d.Y0, d.X1, d.Y1
		v.FrameStyle = g.frameStyle("secondary")
		v.Title = Line{{Text: g.secondaryTitle, Style: v.FrameStyle}}
		v.Highlight = false
		if v.OriginY > v.MaxOrigin() {
			v.OriginY = v.MaxOrigin()
		}
		v.Draw(g.scr)
	}

	// extras (command log)
	if d, ok := dims["extras"]; ok && g.showCommandLog && d.Y1 >= d.Y0 {
		v := g.cmdLogView
		v.Visible = true
		v.X0, v.Y0, v.X1, v.Y1 = d.X0, d.Y0, d.X1, d.Y1
		v.FrameStyle = g.frameStyle("extras")
		v.Title = Line{{Text: "Command log", Style: v.FrameStyle}}
		v.SetContent(g.cmdLog)
		v.Highlight = false
		// autoscroll: show the bottom when content exceeds the view
		max := v.LinesHeight() - v.InnerHeight()
		if max < 0 {
			max = 0
		}
		if v.OriginY > max {
			v.OriginY = max
		}
		v.Draw(g.scr)
	}

	// bottom line
	if g.cfg.Gui.ShowBottomLine || g.searchState != nil {
		g.drawBottomLine(width, height)
	}

	// popups
	for _, p := range g.popups {
		p.draw(g, width, height)
	}

	g.scr.Flush()
}

func (g *Gui) selectedLineBg() term.Color {
	st := bgStyleFromConfig(g.cfg.Gui.Theme.SelectedLineBgColor)
	if st.Bg == term.ColorDefault {
		return term.ColorBlue
	}
	return st.Bg
}

func (g *Gui) optionsItems() []string {
	if len(g.popups) > 0 {
		return g.popups[len(g.popups)-1].options()
	}
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		return []string{"Switch view: <tab>", "Exit back to side panel: <esc>", "Keybindings: ?"}
	}
	if g.currentWindow == "extras" {
		return []string{"Keybindings: ?"}
	}
	ctx := g.currentContext()
	if ctx == nil || ctx.options == nil {
		return []string{"Keybindings: ?"}
	}
	return ctx.options()
}

func (g *Gui) informationString() Line {
	return Line{
		{Text: "Donate", Style: styleMagenta.Underline()},
		{Text: " ", Style: styleDefault},
		{Text: "Ask Question", Style: styleYellow.Underline()},
		{Text: " ", Style: styleDefault},
		{Text: g.opts.Version, Style: styleDefault},
	}
}

func (g *Gui) drawBottomLine(width, height int) {
	y := height - 1
	if g.searchState != nil {
		g.drawSearchLine(width, y)
		return
	}
	info := g.informationString()
	infoWidth := info.Width()
	optionsWidth := width - infoWidth - 1
	if optionsWidth < 0 {
		optionsWidth = 0
	}
	// options text
	items := g.optionsItems()
	limit := optionsWidth - 2
	text := joinOptions(items, limit)
	optStyle := styleFromConfig(g.cfg.Gui.Theme.OptionsTextColor)
	x := 0
	for _, r := range text {
		if x >= optionsWidth {
			break
		}
		g.scr.Set(x, y, r, optStyle)
		x += term.RuneWidth(r)
	}
	for ; x < optionsWidth-1; x++ {
		g.scr.Set(x, y, ' ', optStyle)
	}
	// information string, right aligned
	x = width - infoWidth
	for _, sp := range info {
		for _, r := range sp.Text {
			g.scr.Set(x, y, r, sp.Style)
			x += term.RuneWidth(r)
		}
	}
}

// joinOptions joins option items with " | " keeping within limit, appending
// an ellipsis item when not everything fits.
func joinOptions(items []string, limit int) string {
	var kept []string
	cur := 0
	for i, it := range items {
		add := term.StringWidth(it)
		if i > 0 {
			add += 3
		}
		if cur+add > limit {
			if len(kept) == 0 {
				return "…"
			}
			return strings.Join(kept, " | ") + " | …"
		}
		kept = append(kept, it)
		cur += add
	}
	return strings.Join(kept, " | ")
}
