func (g *Gui) midSectionWeights(width, height int) (int, int) {
	ratio := g.cfg.Gui.SidePanelWidth
	if ratio <= 0 || ratio >= 1 {
		ratio = 0.3333
	}
	mainWeight := int(1/ratio) - 1
	sideWeight := 1
	if g.splitMainPanelSideBySide(width, height) {
		mainWeight = sideWeight * 5
	}
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		if g.screenMode == ScreenHalf || g.screenMode == ScreenFull {
			sideWeight = 0
		}
	} else {
		if g.screenMode == ScreenHalf {
			mainWeight = 1
		} else if g.screenMode == ScreenFull {
			mainWeight = 0
		}
	}
	return sideWeight, mainWeight
}

func (g *Gui) windowDimensions() map[string]Dimensions {
