// Popup is a modal dialog.
type Popup struct {
	kind    PopupKind
	title   string
	message string
	// confirm
	onConfirm func()
	onCancel  func()
	// menu
	items    []*MenuItem
	rows     []*MenuItem // rendered rows including headers
	selected int         // index into rows
	origin   int
	// prompt
