	view      *View
	alert     bool
	// which window should regain focus
	findSuggestions func(string) []string
}

func (p *Popup) options() []string {
	if p.optionsFn != nil {
		return p.optionsFn()
	}
	switch p.kind {
	case PopupMenu:
		return []string{"Execute: <enter>", "Close/Cancel: <esc>"}
	case PopupPrompt:
		return []string{"Confirm: <enter>", "Close/Cancel: <esc>"}
	case PopupCommitMessage:
		return []string{"Confirm: <enter>", "Close/Cancel: <esc>", "Switch to editor: <c-o>"}
	}
	return []string{"Confirm: <enter>", "Close/Cancel: <esc>", "Copy to clipboard: <c-o>"}
}

