	g.popups = append(g.popups, p)
}

func (g *Gui) popPopup() {
	if len(g.popups) > 0 {
		g.popups = g.popups[:len(g.popups)-1]
	}
	if len(g.popups) == 0 {
		g.updateMainView()
	}
