		rows = append(rows, it)
	}
	p.rows = rows
	// select first selectable
	for i, r := range rows {
		if !r.isHeader && !r.blank {
			p.selected = i
			break
		}
	}
	g.pushPopup(p)
}

func (g *Gui) showPrompt(title string, initial string, onSubmit func(string)) {
	p := &Popup{kind: PopupPrompt, title: title, input: []rune(initial), onSubmit: onSubmit}
	p.cursor = len(p.input)
	g.pushPopup(p)
}

// ---------------------------------------------------------------------------
// geometry

func confirmationPanelWidth(width int) int {
	panelWidth := 80
	if width-2 < 80 {
		panelWidth = width - 2
	}
	return panelWidth
}

func menuPanelWidth(width int) int {
	panelWidth := 4 * width / 7
	if panelWidth < 80 {
		if width-2 < 80 {
			panelWidth = width - 2
		} else {
			panelWidth = 80
		}
	}
	if panelWidth > 90 {
		panelWidth = 90
	}
	return panelWidth
}

func (p *Popup) selectableCount() int {
	n := 0
	for _, r := range p.rows {
		if !r.isHeader && !r.blank {
			n++
		}
	}
	return n
}

func (p *Popup) selectedOrdinal() int {
	n := 0
	for i, r := range p.rows {
		if r.isHeader || r.blank {
			continue
		}
		n++
		if i == p.selected {
			return n
		}
	}
	return n
}

func (p *Popup) menuLines() []Line {
	keyWidth := 0
	labelWidth := 0
	hasCommand := false
	for _, r := range p.rows {
		if r.isHeader || r.blank {
			continue
		}
		if w := term.StringWidth(r.Key); w > keyWidth {
			keyWidth = w
		}
		if w := term.StringWidth(r.Label); w > labelWidth {
			labelWidth = w
		}
		if r.Command != "" {
			hasCommand = true
		}
	}
	lines := make([]Line, len(p.rows))
	for i, r := range p.rows {
		if r.blank {
			lines[i] = plain("")
			continue
		}
		if r.isHeader {
			lines[i] = Line{{Text: strings.Repeat(" ", keyWidth) + " " + r.headerText, Style: styleDefault}}
			continue
		}
		var l Line
		key := r.Key
		if keyWidth > 0 {
			pad := keyWidth - term.StringWidth(key)
			l = append(l, Span{Text: strings.Repeat(" ", pad), Style: styleDefault})
			l = append(l, Span{Text: key, Style: styleDefault})
			l = append(l, Span{Text: " ", Style: styleDefault})
		}
		labelStyle := styleDefault
		if r.Disabled {
			labelStyle = styleDefault.WithFg(term.ColorWhite + 1) // dimmed-ish
		}
		if hasCommand {
			l = append(l, Span{Text: padToWidth(r.Label, labelWidth), Style: labelStyle})
			if r.Command != "" {
				l = append(l, Span{Text: " ", Style: styleDefault})
				l = append(l, Span{Text: r.Command, Style: styleCyan})
			}
		} else {
			l = append(l, Span{Text: r.Label, Style: labelStyle})
		}
		lines[i] = l
	}
	return lines
}

func (p *Popup) draw(g *Gui, width, height int) {
	v := p.view
	switch p.kind {
	case PopupConfirm:
		pw := confirmationPanelWidth(width)
		x0 := width/2 - pw/2
		x1 := width/2 + pw/2
		v.X0, v.X1 = x0, x1
		v.Frame = true
		v.Wrap = true
		v.Visible = true
		v.FrameStyle = styleFromConfig(g.cfg.Gui.Theme.ActiveBorderColor)
		v.Title = Line{{Text: p.title, Style: v.FrameStyle}}
		if p.title == "" {
			v.Title = nil
		}
		v.SetContent(ParseANSILines(p.message))
		v.X0, v.X1 = x0, x1 // needed for wrap width
		inner := v.LinesHeight()
		if inner < 1 {
			inner = 1
		}
		if max := 3 * height / 4; inner > max {
			inner = max
		}
		y0 := height/2 - inner/2 - 1
		if y0 < 0 {
			y0 = 0
		}
		v.Y0, v.Y1 = y0, y0+inner+1
		v.Highlight = false
		v.ShowScrollbar = true
		if v.OriginY > v.MaxOrigin() {
			v.OriginY = v.MaxOrigin()
		}
		v.Draw(g.scr)
	case PopupMenu:
		pw := menuPanelWidth(width)
		x0 := width/2 - pw/2
		x1 := width/2 + pw/2
		v.X0, v.X1 = x0, x1
		v.Frame = true
		v.Wrap = false
		v.Visible = true
		v.FrameStyle = styleFromConfig(g.cfg.Gui.Theme.ActiveBorderColor)
		v.Title = Line{{Text: p.title, Style: v.FrameStyle}}
		lines := p.menuLines()
		v.SetContent(lines)
		inner := len(p.items)
		if inner < 1 {
			inner = 1
		}
		if max := 3*height/4 - 3; inner > max {
			inner = max
		}
		if inner < 1 {
			inner = 1
		}
		y0 := height/2 - inner/2 - 3
		if y0 < 0 {
			y0 = 0
		}
		v.Y0, v.Y1 = y0, y0+inner+1
		v.Highlight = true
		v.SelStart, v.SelEnd = p.selected, p.selected
		v.SelBg = g.selectedLineBg()
		v.Footer = ""
		if g.cfg.Gui.ShowListFooter {
			v.Footer = strings.TrimSpace(strings.Join([]string{itoa(p.selectedOrdinal()), "of", itoa(p.selectableCount())}, " "))
		}
		v.FocusLine(p.selected)
		if v.OriginY > v.MaxOrigin() {
			v.OriginY = v.MaxOrigin()
		}
		v.Draw(g.scr)
		// tooltip
		if sel := p.rows[p.selected]; sel.Tooltip != "" {
			tv := NewView("tooltip")
			tv.X0, tv.X1 = x0, x1
			tv.Wrap = true
			tv.FrameStyle = styleFromConfig(g.cfg.Gui.Theme.InactiveBorderColor)
			tv.SetContent(ParseANSILines(sel.Tooltip))
			th := tv.LinesHeight()
			tv.Y0 = v.Y1 + 1
			tv.Y1 = tv.Y0 + th + 1
			if tv.Y1 < height-1 {
				tv.ShowScrollbar = false
				tv.Draw(g.scr)
			}
		}
	case PopupPrompt:
		pw := confirmationPanelWidth(width)
		x0 := width/2 - pw/2
		x1 := width/2 + pw/2
		v.X0, v.X1 = x0, x1
		v.Frame = true
		v.Wrap = true
		v.Visible = true
		v.FrameStyle = styleFromConfig(g.cfg.Gui.Theme.ActiveBorderColor)
		v.Title = Line{{Text: p.title, Style: v.FrameStyle}}
		text := string(p.input)
		v.SetContent([]Line{plain(text)})
		inner := v.LinesHeight()
		if inner < 1 {
			inner = 1
		}
		y0 := height/2 - inner/2 - 1
		v.Y0, v.Y1 = y0, y0+inner+1
		v.Highlight = false
		v.ShowScrollbar = false
		v.Draw(g.scr)
		// cursor
		cx := v.X0 + 1 + term.StringWidth(string(p.input[:p.cursor]))
		cy := v.Y0 + 1
		iw := v.InnerWidth()
		for cx-v.X0-1 >= iw && iw > 0 {
			cx -= iw
			cy++
		}
		g.scr.ShowCursor(cx, cy)
	case PopupCommitMessage:
		g.drawCommitMessagePopup(p, width, height)
	}
}

func itoa(n int) string {
	return strings.TrimSpace(strings.Replace(fmtInt(n), " ", "", -1))
}

func fmtInt(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b []byte
	for n > 0 {
		b = append([]byte{byte('0' + n%10)}, b...)
		n /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}

// ---------------------------------------------------------------------------
// key handling for popups

func (g *Gui) handlePopupKey(p *Popup, name string, ev term.Event) {
	switch p.kind {
	case PopupConfirm:
		switch name {
		case "<enter>":
			g.popPopup()
			if p.onConfirm != nil {
				p.onConfirm()
			}
		case "<esc>", "q":
			g.popPopup()
			if p.onCancel != nil {
				p.onCancel()
			}
		case "<c-c>":
			g.Quit()
		case "<pgup>", "<c-u>", "K":
			p.view.ScrollUp(g.cfg.Gui.ScrollHeight)
		case "<pgdown>", "<c-d>", "J":
			p.view.ScrollDown(g.cfg.Gui.ScrollHeight)
		case "<up>", "k":
			p.view.ScrollUp(1)
		case "<down>", "j":
			p.view.ScrollDown(1)
		}
	case PopupMenu:
		g.handleMenuKey(p, name, ev)
	case PopupPrompt:
		g.handlePromptKey(p, name, ev)
	case PopupCommitMessage:
		g.handleCommitMessageKey(p, name, ev)
	}
}

func (p *Popup) moveSelection(delta int) {
	n := len(p.rows)
	if n == 0 {
		return
	}
	i := p.selected
	for {
		i += delta
		if i < 0 || i >= n {
			return
		}
		if !p.rows[i].isHeader && !p.rows[i].blank {
			p.selected = i
			return
		}
	}
}

func (g *Gui) handleMenuKey(p *Popup, name string, ev term.Event) {
	switch name {
	case "<esc>", "q":
		g.popPopup()
		return
	case "<c-c>":
		g.Quit()
		return
	case "<enter>":
		if p.selected < len(p.rows) {
			item := p.rows[p.selected]
			if item.Disabled {
				return
			}
			g.popPopup()
			if item.OnPress != nil {
				item.OnPress()
			}
		}
		return
	case "<up>", "k":
		p.moveSelection(-1)
		return
	case "<down>", "j":
		p.moveSelection(1)
		return
	case "<pgup>", ",":
		h := p.view.InnerHeight()
		for i := 0; i < h; i++ {
			p.moveSelection(-1)
		}
		return
	case "<pgdown>", ".":
		h := p.view.InnerHeight()
		for i := 0; i < h; i++ {
			p.moveSelection(1)
		}
		return
	case "<", "<home>":
		for i := range p.rows {
			if !p.rows[i].isHeader && !p.rows[i].blank {
				p.selected = i
				break
			}
		}
		return
	case ">", "<end>":
		for i := len(p.rows) - 1; i >= 0; i-- {
			if !p.rows[i].isHeader && !p.rows[i].blank {
				p.selected = i
				break
			}
		}
		return
	}
	// key shortcuts
	for _, r := range p.rows {
		if r.isHeader || r.blank || r.Key == "" {
			continue
		}
		if r.Key == name && !r.Disabled {
			g.popPopup()
			if r.OnPress != nil {
				r.OnPress()
			}
			return
		}
	}
}

func (g *Gui) handlePromptKey(p *Popup, name string, ev term.Event) {
	switch name {
	case "<esc>":
		g.popPopup()
		if p.onCancel != nil {
			p.onCancel()
		}
		return
	case "<c-c>":
		g.Quit()
		return
	case "<enter>":
		text := string(p.input)
		g.popPopup()
		if p.onSubmit != nil {
			p.onSubmit(text)
		}
		return
	case "<backspace>":
		if p.cursor > 0 {
			p.input = append(p.input[:p.cursor-1], p.input[p.cursor:]...)
			p.cursor--
		}
		return
	case "<delete>":
		if p.cursor < len(p.input) {
			p.input = append(p.input[:p.cursor], p.input[p.cursor+1:]...)
		}
		return
	case "<left>":
		if p.cursor > 0 {
			p.cursor--
		}
		return
	case "<right>":
		if p.cursor < len(p.input) {
			p.cursor++
		}
		return
	case "<home>", "<c-a>":
		p.cursor = 0
		return
	case "<end>", "<c-e>":
		p.cursor = len(p.input)
		return
	case "<c-u>":
		p.input = p.input[p.cursor:]
		p.cursor = 0
		return
	case "<c-k>":
		p.input = p.input[:p.cursor]
		return
	case "<c-w>":
		// delete word backwards
		i := p.cursor
		for i > 0 && p.input[i-1] == ' ' {
			i--
		}
		for i > 0 && p.input[i-1] != ' ' {
			i--
		}
		p.input = append(p.input[:i], p.input[p.cursor:]...)
		p.cursor = i
		return
	}
	if ev.Key == term.KeyRune && ev.Mod&term.ModAlt == 0 {
		p.input = append(p.input[:p.cursor], append([]rune{ev.Rune}, p.input[p.cursor:]...)...)
		p.cursor++
	} else if ev.Key == term.KeyTab {
		p.input = append(p.input[:p.cursor], append([]rune{'\t'}, p.input[p.cursor:]...)...)
		p.cursor++
	}
}
