	PopupMenu
	PopupPrompt
	PopupCommitMessage
)

// MenuItem is an entry in a menu popup.
type MenuItem struct {
	Label    string
	Key      string
	Tooltip  string
	Command  string // shown in a dimmed column
	Section  string // section header (rendered before the item)
	Disabled bool
	OnPress  func()
	// non-selectable row (section header / separator)
	isHeader bool
	headerText string
	blank    bool
}

