package gui

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"lazygit-clone/internal/term"
)

var sideWindows = []string{"status", "files", "branches", "commits", "stash"}

func (g *Gui) handleKey(name string, ev term.Event) {
	if g.searchState != nil && g.searchState.active {
		g.handleSearchKey(name, ev)
		return
	}
	if len(g.popups) > 0 {
		p := g.popups[len(g.popups)-1]
		g.handlePopupKey(p, name, ev)
		return
	}
	kb := &g.cfg.Keybinding.Universal

	// global keys
	switch name {
	case kb.Quit, kb.QuitAlt1:
		g.handleQuit(false)
		return
	case kb.QuitWithoutChangingDirectory:
		g.handleQuit(true)
		return
	case kb.OptionMenuAlt1:
		g.showKeybindingsMenu()
		return
	case kb.NextScreenMode:
		g.screenMode = (g.screenMode + 1) % 3
		return
	case kb.PrevScreenMode:
		g.screenMode = (g.screenMode + 2) % 3
		return
	case kb.ExtrasMenu:
		g.showExtrasMenu()
		return
	case kb.Refresh:
		g.refreshAll()
		g.updateMainView()
		return
	case kb.FocusMainView:
		g.focusMain()
		return
	case kb.ScrollUpMain, kb.ScrollUpMainAlt1, kb.ScrollUpMainAlt2:
		g.scrollMain(-g.cfg.Gui.ScrollHeight)
		return
	case kb.ScrollDownMain, kb.ScrollDownMainAlt1, kb.ScrollDownMainAlt2:
		g.scrollMain(g.cfg.Gui.ScrollHeight)
		return
	case kb.ToggleWhitespaceInDiffView:
		g.ignoreWhitespace = !g.ignoreWhitespace
		g.updateMainView()
		return
	case kb.IncreaseContextInDiffView:
		g.diffContextSize++
		g.updateMainView()
		return
	case kb.DecreaseContextInDiffView:
		if g.diffContextSize > 0 {
			g.diffContextSize--
		}
		g.updateMainView()
		return
	case kb.IncreaseRenameSimilarityThreshold:
		if g.renameThreshold < 100 {
			g.renameThreshold += 5
		}
		g.refreshFiles()
		g.updateMainView()
		return
	case kb.DecreaseRenameSimilarityThreshold:
		if g.renameThreshold > 5 {
			g.renameThreshold -= 5
		}
		g.refreshFiles()
		g.updateMainView()
		return
	case kb.PushFiles:
		g.push()
		return
	case kb.PullFiles:
		g.pull()
		return
	case kb.ExecuteShellCommand:
		g.showPrompt("Shell command:", "", func(cmd string) {
			if strings.TrimSpace(cmd) == "" {
				return
			}
			g.runSubprocessShell(cmd)
		})
		return
	case kb.CreateRebaseOptionsMenu:
		g.showRebaseOptionsMenu()
		return
	case kb.Undo, kb.Redo:
		return
	case kb.StartSearch:
		if g.currentContext() != nil && g.currentWindow != "status" {
			g.startSearch()
			return
		}
	}

	for i, k := range kb.JumpToBlock {
		if name == k && i < len(sideWindows) {
			g.focusWindow(sideWindows[i])
			return
		}
	}

	// main view keys
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		g.handleMainKey(name, ev)
		return
	}
	if g.currentWindow == "extras" {
		g.handleExtrasKey(name, ev)
		return
	}

	ctx := g.currentContext()
	if ctx == nil {
		return
	}

	// context specific first (so that e.g. space can be overridden)
	if ctx.handleKey != nil && ctx.handleKey(name) {
		return
	}

	switch name {
	case kb.PrevItem, kb.PrevItemAlt:
		g.moveSelection(ctx, -1)
	case kb.NextItem, kb.NextItemAlt:
		g.moveSelection(ctx, 1)
	case kb.PrevPage:
		g.moveSelection(ctx, -g.pageSize(ctx))
	case kb.NextPage:
		g.moveSelection(ctx, g.pageSize(ctx))
	case kb.GotoTop, kb.GotoTopAlt:
		g.setSelection(ctx, 0)
	case kb.GotoBottom, kb.GotoBottomAlt:
		g.setSelection(ctx, ctx.length()-1)
	case kb.RangeSelectDown:
		if ctx.rangeStart < 0 {
			ctx.rangeStart = ctx.selected
		}
		g.moveSelectionKeepRange(ctx, 1)
	case kb.RangeSelectUp:
		if ctx.rangeStart < 0 {
			ctx.rangeStart = ctx.selected
		}
		g.moveSelectionKeepRange(ctx, -1)
	case kb.ToggleRangeSelect:
		if ctx.rangeStart >= 0 {
			ctx.rangeStart = -1
		} else {
			ctx.rangeStart = ctx.selected
		}
	case kb.NextBlock, kb.NextBlockAlt, kb.NextBlockAlt2, kb.TogglePanel:
		g.nextSideWindow(1)
	case kb.PrevBlock, kb.PrevBlockAlt, kb.PrevBlockAlt2:
		g.nextSideWindow(-1)
	case kb.NextTab:
		g.nextTab(1)
	case kb.PrevTab:
		g.nextTab(-1)
	case kb.Return:
		if ctx.rangeStart >= 0 {
			ctx.rangeStart = -1
		} else if g.cfg.QuitOnTopLevelReturn {
			g.handleQuit(false)
		}
	case kb.ScrollLeft:
		g.views[ctx.window].OriginX -= 1
		if g.views[ctx.window].OriginX < 0 {
			g.views[ctx.window].OriginX = 0
		}
	case kb.ScrollRight:
		g.views[ctx.window].OriginX += 1
	case kb.CopyToClipboard:
		// clipboard not available
	}
}

func (g *Gui) pageSize(ctx *ListContext) int {
	v := g.views[ctx.window]
	h := v.InnerHeight()
	if h < 1 {
		h = 1
	}
	return h
}

func (g *Gui) moveSelection(ctx *ListContext, delta int) {
	if ctx.rangeStart >= 0 && !g.rangeSelectSticky(ctx) {
		// moving with a range active (toggle mode) keeps the range
	}
	g.setSelection(ctx, ctx.selected+delta)
}

func (g *Gui) rangeSelectSticky(ctx *ListContext) bool { return true }

func (g *Gui) moveSelectionKeepRange(ctx *ListContext, delta int) {
	g.setSelection(ctx, ctx.selected+delta)
}

func (g *Gui) setSelection(ctx *ListContext, idx int) {
	n := ctx.length()
	if n == 0 {
		ctx.selected = 0
		return
	}
	if idx < 0 {
		idx = 0
	}
	if idx >= n {
		idx = n - 1
	}
	if idx != ctx.selected {
		ctx.selected = idx
		g.resetMainOrigin()
	}
	if ctx.updateMain != nil {
		ctx.updateMain()
	}
}

func (g *Gui) focusWindow(window string) {
	if g.currentWindow == window {
		if g.cfg.Gui.SwitchTabsWithPanelJumpKeys {
			g.nextTab(1)
		}
		return
	}
	g.currentWindow = window
	if window != "main" && window != "secondary" && window != "extras" {
		g.previousSideWindow = window
	}
	g.resetMainOrigin()
	g.updateMainView()
}

func (g *Gui) nextSideWindow(delta int) {
	cur := g.currentSideWindow()
	idx := 0
	for i, w := range sideWindows {
		if w == cur {
			idx = i
		}
	}
	idx = (idx + delta + len(sideWindows)) % len(sideWindows)
	g.focusWindow(sideWindows[idx])
}

func (g *Gui) nextTab(delta int) {
	window := g.currentSideWindow()
	ctxs := g.windowContexts[window]
	if len(ctxs) <= 1 {
		return
	}
	g.activeTab[window] = (g.activeTab[window] + delta + len(ctxs)) % len(ctxs)
	g.resetMainOrigin()
	g.updateMainView()
}

func (g *Gui) focusMain() {
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		return
	}
	g.previousSideWindow = g.currentSideWindow()
	g.currentWindow = "main"
}

func (g *Gui) scrollMain(delta int) {
	v := g.views["main"]
	if g.currentWindow == "secondary" {
		v = g.views["secondary"]
	}
	if delta < 0 {
		v.ScrollUp(-delta)
	} else {
		v.ScrollDown(delta)
	}
}

func (g *Gui) handleMainKey(name string, ev term.Event) {
	kb := &g.cfg.Keybinding.Universal
	v := g.views[g.currentWindow]
	switch name {
	case kb.Return:
		g.currentWindow = g.previousSideWindow
	case kb.TogglePanel, kb.NextBlockAlt2:
		if g.mainSplit {
			if g.currentWindow == "main" {
				g.currentWindow = "secondary"
			} else {
				g.currentWindow = "main"
			}
		}
	case kb.PrevItem, kb.PrevItemAlt:
		v.ScrollUp(1)
	case kb.NextItem, kb.NextItemAlt:
		v.ScrollDown(1)
	case kb.PrevPage:
		v.ScrollUp(v.InnerHeight())
	case kb.NextPage:
		v.ScrollDown(v.InnerHeight())
	case kb.GotoTop, kb.GotoTopAlt:
		v.OriginY = 0
	case kb.GotoBottom, kb.GotoBottomAlt:
		v.ScrollToBottom()
	case kb.ScrollLeft, kb.PrevBlock, kb.PrevBlockAlt:
		if v.OriginX > 0 {
			v.OriginX--
		}
	case kb.ScrollRight, kb.NextBlock, kb.NextBlockAlt:
		v.OriginX++
	}
}

func (g *Gui) handleExtrasKey(name string, ev term.Event) {
	kb := &g.cfg.Keybinding.Universal
	v := g.cmdLogView
	switch name {
	case kb.Return:
		g.currentWindow = g.previousSideWindow
	case kb.PrevItem, kb.PrevItemAlt:
		v.ScrollUp(1)
	case kb.NextItem, kb.NextItemAlt:
		v.ScrollDown(1)
	case kb.GotoTop:
		v.OriginY = 0
	case kb.GotoBottom:
		v.ScrollToBottom()
	}
}

// ---------------------------------------------------------------------------
// quitting

func (g *Gui) handleQuit(withoutChangingDir bool) {
	if g.cfg.ConfirmOnQuit {
		g.showConfirm("", "Are you sure you want to quit?", func() {
			g.doQuit(withoutChangingDir)
		}, nil)
		return
	}
	g.doQuit(withoutChangingDir)
}

func (g *Gui) doQuit(withoutChangingDir bool) {
	if !withoutChangingDir && g.opts.NewDirFile != "" {
		cwd, err := os.Getwd()
		if err == nil {
			_ = os.MkdirAll(filepath.Dir(g.opts.NewDirFile), 0o755)
			_ = os.WriteFile(g.opts.NewDirFile, []byte(cwd), 0o644)
		}
	}
	g.state.Save()
	g.quit = true
}

// ---------------------------------------------------------------------------
// status panel

func (g *Gui) handleStatusKey(name string) bool {
	switch name {
	case g.cfg.Keybinding.Universal.Edit:
		g.editFile(g.configPath())
		return true
	case g.cfg.Keybinding.Status.CheckForUpdate:
		g.showAlert("", "Binary is not built with the buildBinary flag so we won't check for an update")
		return true
	case g.cfg.Keybinding.Universal.GoInto, g.cfg.Keybinding.Status.RecentRepos:
		g.showRecentReposMenu()
		return true
	case g.cfg.Keybinding.Status.AllBranchesLogGraph:
		if len(g.cfg.Git.AllBranchesLogCmds) > 0 {
			out, _ := g.repo.RunShell(g.cfg.Git.AllBranchesLogCmds[0])
			g.setMainContent("Log", out, false)
		}
		return true
	}
	return false
}

func (g *Gui) configPath() string {
	return g.opts.ConfigPath()
}

// ConfigPath returns the path to the user config file.
func (o Options) ConfigPath() string {
	return o.configPath
}

func (g *Gui) showRecentReposMenu() {
	var items []*MenuItem
	for _, r := range g.state.RecentRepos {
		if r == g.repo.WorkTree {
			continue
		}
		repo := r
		items = append(items, &MenuItem{Label: filepath.Base(repo), Command: repo, OnPress: func() {}})
	}
	items = append(items, &MenuItem{Label: "Cancel"})
	g.showMenu("Recent repositories", items)
}

// ---------------------------------------------------------------------------
// subprocesses

func (g *Gui) runSubprocess(args []string) {
	g.t.Suspend()
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Dir = g.repo.WorkTree
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
