func (g *Gui) handleFilesKey(name string) bool {
	kb := &g.cfg.Keybinding
	ctx := g.contexts["files"]
	node := g.selectedFileNode()
	switch name {
	case kb.Universal.Select:
		if node == nil {
			return true
		}
		g.toggleStaged(node)
		return true
	case kb.Universal.GoInto:
		if node == nil {
			return true
		}
		if node.IsDir() {
			g.collapsed[node.Path] = !g.collapsed[node.Path]
			g.rebuildFileTree()
			g.updateMainView()
