		g.showDiscardMenu(node)
		return true
	case kb.Files.ViewResetOptions:
		g.showResetMenu()
		return true
	case kb.Files.ViewUpstreamResetOptions():
		g.showUpstreamResetMenu()
		return true
	case kb.Files.IgnoreFile:
		if node == nil {
			return true
		}
		g.showIgnoreMenu(node)
		return true
	case kb.Files.ToggleTreeView:
		g.flatFileTree = !g.flatFileTree
		g.rebuildFileTree()
		g.updateMainView()
		return true
	case kb.Files.CollapseAll:
		for _, n := range g.fileTree.allDirs() {
			g.collapsed[n.Path] = true
		}
		g.rebuildFileTree()
		g.updateMainView()
		return true
	case kb.Files.ExpandAll:
		g.collapsed = map[string]bool{}
		g.rebuildFileTree()
		g.updateMainView()
		return true
	case kb.Universal.Edit:
		if node != nil && !node.IsDir() {
			g.editFile(filepath.Join(g.repo.WorkTree, node.Path))
		}
		return true
	case kb.Universal.OpenFile:
		if node != nil && !node.IsDir() {
			g.editFile(filepath.Join(g.repo.WorkTree, node.Path))
		}
		return true
	case kb.Files.Fetch:
		g.logCommand("git fetch", true)
		g.repo.Run("fetch")
		g.refreshAll()
		g.updateMainView()
		return true
	case kb.Files.OpenMergeOptions:
		if !g.anyMergeConflicts() {
			g.showToast("Disabled: There are no files with merge conflicts.")
			return true
		}
		g.showRebaseOptionsMenu()
		return true
	case kb.Files.CopyFileInfoToClipboard:
		if node == nil {
			return true
		}
		g.showMenu("Copy to clipboard", []*MenuItem{
			{Label: "File name", Key: "n"},
			{Label: "Relative path", Key: "p"},
			{Label: "Absolute path", Key: "P"},
			{Label: "Diff of selected file", Key: "s"},
			{Label: "Diff of all files", Key: "a"},
			{Label: "Cancel"},
		})
		return true
	case kb.Files.OpenStatusFilter:
		g.showMenu("Filtering", []*MenuItem{
			{Label: "Show only staged files", Key: "s"},
			{Label: "Show only unstaged files", Key: "u"},
			{Label: "Show only tracked files", Key: "t"},
			{Label: "Show only untracked files", Key: "T"},
			{Label: "Show only conflicted files", Key: "c"},
			{Label: "Reset filter", Key: "r"},
			{Label: "Cancel"},
		})
		return true
	case kb.Files.FindBaseCommitForFixup:
		return true
	}
	_ = ctx
	return false
}

func (g *Gui) anyMergeConflicts() bool {
	for _, f := range g.files {
		if f.HasMergeConflicts {
			return true
		}
	}
	return false
}

func (g *Gui) anyStagedChanges() bool {
	for _, f := range g.files {
		if f.HasStagedChanges {
			return true
		}
	}
	return false
}

func (n *FileNode) allDirs() []*FileNode {
	var out []*FileNode
	if n.IsDir() {
		out = append(out, n)
		for _, c := range n.Children {
			out = append(out, c.allDirs()...)
		}
	}
	return out
}

func (g *Gui) toggleStaged(node *FileNode) {
	files := node.Files()
	if len(files) == 0 {
		return
	}
	if node.IsDir() {
		// if any file has unstaged changes, stage all; else unstage all
		anyUnstaged := false
		for _, f := range files {
			if f.HasUnstagedChanges {
				anyUnstaged = true
			}
		}
		path := node.Path
		if path == "" {
			path = "."
		}
		if anyUnstaged {
			g.gitRun("add", "--", path)
		} else {
			g.gitRun("reset", "--", path)
		}
		g.afterFileAction()
		return
	}
	f := files[0]
	if f.HasMergeConflicts {
		g.gitRun("add", "--", f.Name)
	} else if f.HasUnstagedChanges {
		if f.Tracked {
			g.gitRun("add", "--", f.Name)
		} else {
			g.gitRun("add", "--", f.Name)
		}
	} else {
		if f.Added && !g.hasCommits {
			g.gitRun("rm", "--cached", "--", f.Name)
		} else {
			g.gitRun("reset", "--", f.Name)
		}
	}
	g.afterFileAction()
}

func (g *Gui) toggleStagedAll() {
	anyUnstaged := false
	for _, f := range g.files {
		if f.HasUnstagedChanges {
			anyUnstaged = true
		}
	}
	if anyUnstaged {
		g.gitRun("add", "-A")
	} else {
		if g.hasCommits {
			g.gitRun("reset")
		} else {
			g.gitRun("rm", "-r", "--cached", ".")
		}
	}
	g.afterFileAction()
}

func (g *Gui) commitChanges(noVerify bool) {
	if len(g.files) == 0 {
		g.showErrorPopup("There are no files to commit")
		return
	}
	if g.anyMergeConflicts() {
		g.showErrorPopup("There are files with merge conflicts")
		return
	}
	if !g.anyStagedChanges() {
		if g.cfg.Gui.SkipNoStagedFilesWarning {
			g.gitRun("add", "-A")
			g.afterFileAction()
			g.openCommitMessagePanel(noVerify)
			return
		}
		g.showConfirm("No files staged", "You have not staged any files. Commit all files?", func() {
			g.gitRun("add", "-A")
			g.refreshFiles()
			g.openCommitMessagePanel(noVerify)
		}, nil)
		return
	}
	g.openCommitMessagePanel(noVerify)
}

func (g *Gui) showDiscardMenu(node *FileNode) {
	var items []*MenuItem
	label := "Discard all changes"
	items = append(items, &MenuItem{Label: label, Key: "x", OnPress: func() {
		g.discardAll(node)
	}})
	hasStaged := false
	for _, f := range node.Files() {
		if f.HasStagedChanges {
			hasStaged = true
		}
	}
	if hasStaged || node.IsDir() {
		items = append(items, &MenuItem{Label: "Discard unstaged changes", Key: "u", OnPress: func() {
			g.discardUnstaged(node)
		}})
	}
	items = append(items, &MenuItem{Label: "Cancel"})
	g.showMenu("Discard changes", items)
}

func (g *Gui) discardAll(node *FileNode) {
	for _, f := range node.Files() {
		if !f.Tracked {
			g.logCommand("rm "+f.Name, false)
			os.RemoveAll(filepath.Join(g.repo.WorkTree, f.Name))
			continue
		}
		if f.Added {
			g.gitRun("rm", "--cached", "--force", "--", f.Name)
			os.RemoveAll(filepath.Join(g.repo.WorkTree, f.Name))
			continue
		}
		g.gitRun("checkout", "HEAD", "--", f.Name)
	}
	g.afterFileAction()
}

func (g *Gui) discardUnstaged(node *FileNode) {
	for _, f := range node.Files() {
		if !f.Tracked {
			os.RemoveAll(filepath.Join(g.repo.WorkTree, f.Name))
			continue
		}
		g.gitRun("checkout", "--", f.Name)
	}
	g.afterFileAction()
}

func (g *Gui) showResetMenu() {
	run := func(args ...[]string) func() {
		return func() {
			for _, a := range args {
				if err := g.gitRun(a...); err != nil {
					g.showErrorPopup(err.Error())
					break
				}
			}
			g.refreshAll()
			g.updateMainView()
		}
	}
	items := []*MenuItem{
		{Label: "Nuke working tree", Key: "x", Command: "git reset --hard HEAD && git clean -fd", Tooltip: "If you want to make all the changes in the worktree go away, this is the way to do it. If there are dirty submodule changes this will stash those changes in the submodule(s).", OnPress: run([]string{"reset", "--hard", "HEAD"}, []string{"clean", "-fd"})},
		{Label: "Discard unstaged changes", Key: "u", Command: "git checkout -- .", OnPress: run([]string{"checkout", "--", "."})},
		{Label: "Discard untracked files", Key: "c", Command: "git clean -fd", OnPress: run([]string{"clean", "-fd"})},
		{Label: "Discard staged changes", Key: "S", Command: "stash staged and drop stash", Tooltip: "This will stash your staged changes and drop the stash.", OnPress: func() {
			g.gitRun("stash", "push", "--staged")
			g.gitRun("stash", "drop")
			g.refreshAll()
			g.updateMainView()
		}},
		{Label: "Soft reset", Key: "s", Command: "git reset --soft HEAD", OnPress: run([]string{"reset", "--soft", "HEAD"})},
		{Label: "mixed reset", Key: "m", Command: "git reset --mixed HEAD", OnPress: run([]string{"reset", "--mixed", "HEAD"})},
		{Label: "Hard reset", Key: "h", Command: "git reset --hard HEAD", OnPress: run([]string{"reset", "--hard", "HEAD"})},
		{Label: "Cancel"},
	}
	g.showMenu("", items)
}

