func (g *Gui) showStashOptionsMenu() {
	prompt := func(args ...string) func() {
		return func() {
			g.showPrompt("Stash changes", "", func(msg string) {
				full := append([]string{"stash", "push"}, args...)
				if msg != "" {
					full = append(full, "-m", msg)
				}
				if err := g.gitRun(full...); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			})
		}
	}
	items := []*MenuItem{
		{Label: "Stash all changes", Key: "a", OnPress: prompt()},
		{Label: "Stash all changes and keep index", Key: "i", OnPress: prompt("--keep-index")},
		{Label: "Stash all changes including untracked files", Key: "U", OnPress: prompt("--include-untracked")},
		{Label: "Stash staged changes", Key: "s", OnPress: prompt("--staged")},
		{Label: "Stash unstaged changes", Key: "u", OnPress: prompt("--keep-index")},
		{Label: "Cancel"},
