func (g *Gui) showIgnoreMenu(node *FileNode) {
	appendLine := func(file string) {
		path := filepath.Join(g.repo.WorkTree, file)
		os.MkdirAll(filepath.Dir(path), 0o755)
		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
		if err != nil {
			g.showErrorPopup(err.Error())
			return
		}
		f.WriteString(node.Path + "\n")
		f.Close()
		g.afterFileAction()
	}
	items := []*MenuItem{
		{Label: "Add to .gitignore", Key: "i", OnPress: func() { appendLine(".gitignore") }},
		{Label: "Add to .git/info/exclude", Key: "e", OnPress: func() { appendLine(".git/info/exclude") }},
		{Label: "Cancel"},
	}
	g.showMenu("Ignore or exclude file", items)
}

func (g *Gui) enterStagingView(node *FileNode) {
	// staging individual lines is not supported; focus the main view instead
	g.focusMain()
}

