func (g *Gui) handleCommitsKey(name string) bool {
	kb := &g.cfg.Keybinding
	c := g.selectedCommit()
	switch name {
	case kb.Universal.Select:
		if c == nil {
			return true
		}
		g.showConfirm("Checkout commit", fmt.Sprintf("Are you sure you want to checkout this commit?"), func() {
			g.checkout(c.Hash)
		}, nil)
		return true
	case kb.Commits.RenameCommit:
		if c == nil {
			return true
		}
		if g.contexts["commits"].selected != 0 {
			g.showErrorPopup("Can only reword the head commit here")
			return true
		}
		g.showPrompt("Reword commit", c.Subject, func(msg string) {
			if strings.TrimSpace(msg) == "" {
				return
			}
			if err := g.gitRun("commit", "--allow-empty", "--amend", "--only", "-m", msg); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Commits.RevertCommit:
		if c == nil {
			return true
		}
		g.showConfirm("Revert commit", fmt.Sprintf("Are you sure you want to revert %s?", c.Hash[:8]), func() {
			if err := g.gitRun("revert", "--no-edit", c.Hash); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Commits.TagCommit:
		if c == nil {
			return true
		}
		g.showPrompt("Tag name", "", func(t string) {
			t = strings.TrimSpace(t)
			if t == "" {
				return
			}
			if err := g.gitRun("tag", "--", t, c.Hash); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Commits.ViewResetOptions:
		if c == nil {
			return true
		}
		g.showResetToCommitMenu(c.Hash, c.Hash[:8])
		return true
	case kb.Universal.Remove:
		if c == nil {
			return true
		}
		if g.contexts["commits"].selected != 0 {
			g.showErrorPopup("Interactive rebase is not supported")
			return true
		}
		g.showConfirm("Drop commit", "Are you sure you want to drop the selected commit(s)?", func() {
			if err := g.gitRun("reset", "--hard", "HEAD~1"); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Commits.CopyCommitAttributeToClipboard:
		if c == nil {
			return true
		}
		g.showMenu("Copy to clipboard", []*MenuItem{
			{Label: "Commit hash", Key: "h"},
			{Label: "Commit subject", Key: "s"},
			{Label: "Commit message", Key: "m"},
			{Label: "Commit URL", Key: "u"},
			{Label: "Commit diff", Key: "d"},
			{Label: "Commit author", Key: "a"},
			{Label: "Cancel"},
		})
		return true
	case kb.Commits.OpenLogMenu:
		g.showMenu("Log menu", []*MenuItem{
			{Label: "Commit sort order", Key: "s"},
			{Label: "Show git graph", Key: "g"},
			{Label: "Show whole git graph", Key: "w"},
			{Label: "Cancel"},
		})
		return true
	case kb.Universal.GoInto:
		return true
	}
	return false
}

