func (g *Gui) gitRun(args ...string) error {
	g.logCommand("git "+strings.Join(args, " "), true)
	_, err := g.repo.Run(args...)
	return err
}

func (g *Gui) afterFileAction() {
	g.refreshFiles()
	g.refreshBranches()
	g.refreshCommits()
	g.updateMainView()
}

func (g *Gui) handleFilesKey(name string) bool {
	kb := &g.cfg.Keybinding
	ctx := g.contexts["files"]
	node := g.selectedFileNode()
	switch name {
	case kb.Universal.Select:
		if node == nil {
			return true
		}
		g.toggleStaged(node)
		return true
	case kb.Universal.GoInto:
		if node == nil {
			return true
		}
		if node.IsDir() {
			g.collapsed[node.Path] = !g.collapsed[node.Path]
			g.rebuildFileTree()
			g.updateMainView()
		} else {
			g.enterStagingView(node)
		}
		return true
	case kb.Files.CommitChanges:
		g.commitChanges(false)
		return true
	case kb.Files.CommitChangesWithoutHook:
		g.commitChanges(true)
		return true
	case kb.Files.CommitChangesWithEditor:
		if !g.anyStagedChanges() {
			g.showConfirm("No files staged", "You have not staged any files. Commit all files?", func() {
				g.gitRun("add", "-A")
				g.runSubprocess([]string{"git", "commit"})
			}, nil)
			return true
		}
		g.runSubprocess([]string{"git", "commit"})
		return true
	case kb.Files.AmendLastCommit:
		if !g.hasCommits {
			g.showErrorPopup("There's no commit to amend")
			return true
		}
		g.showConfirm("Amend last commit", "Are you sure you want to amend last commit?", func() {
			if err := g.gitRun("commit", "--amend", "--no-edit", "--allow-empty"); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.afterFileAction()
		}, nil)
		return true
	case kb.Files.ToggleStagedAll:
		g.toggleStagedAll()
		return true
	case kb.Files.RefreshFiles:
		g.refreshFiles()
		g.updateMainView()
		return true
	case kb.Files.StashAllChanges:
		if len(g.files) == 0 {
			g.showErrorPopup("You have no changes to stash")
			return true
		}
		g.showPrompt("Stash changes", "", func(msg string) {
			args := []string{"stash", "push"}
			if msg != "" {
				args = append(args, "-m", msg)
			}
			if err := g.gitRun(args...); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Files.ViewStashOptions:
		g.showStashOptionsMenu()
		return true
	case kb.Universal.Remove:
		if node == nil {
			return true
		}
		g.showDiscardMenu(node)
		return true
	case kb.Files.ViewResetOptions:
		g.showResetMenu()
		return true
	case kb.Files.ViewUpstreamResetOptions():
		g.showUpstreamResetMenu()
		return true
	case kb.Files.IgnoreFile:
		if node == nil {
			return true
		}
		g.showIgnoreMenu(node)
		return true
	case kb.Files.ToggleTreeView:
		g.flatFileTree = !g.flatFileTree
		g.rebuildFileTree()
		g.updateMainView()
		return true
	case kb.Files.CollapseAll:
		for _, n := range g.fileTree.allDirs() {
			g.collapsed[n.Path] = true
		}
		g.rebuildFileTree()
		g.updateMainView()
		return true
	case kb.Files.ExpandAll:
		g.collapsed = map[string]bool{}
		g.rebuildFileTree()
		g.updateMainView()
		return true
	case kb.Universal.Edit:
		if node != nil && !node.IsDir() {
			g.editFile(filepath.Join(g.repo.WorkTree, node.Path))
		}
		return true
	case kb.Universal.OpenFile:
		if node != nil && !node.IsDir() {
			g.editFile(filepath.Join(g.repo.WorkTree, node.Path))
		}
		return true
	case kb.Files.Fetch:
		g.logCommand("git fetch", true)
		g.repo.Run("fetch")
		g.refreshAll()
		g.updateMainView()
		return true
	case kb.Files.OpenMergeOptions:
		if !g.anyMergeConflicts() {
			g.showToast("Disabled: There are no files with merge conflicts.")
			return true
		}
		g.showRebaseOptionsMenu()
		return true
	case kb.Files.CopyFileInfoToClipboard:
		if node == nil {
			return true
		}
		g.showMenu("Copy to clipboard", []*MenuItem{
			{Label: "File name", Key: "n"},
			{Label: "Relative path", Key: "p"},
			{Label: "Absolute path", Key: "P"},
			{Label: "Diff of selected file", Key: "s"},
			{Label: "Diff of all files", Key: "a"},
			{Label: "Cancel"},
		})
		return true
	case kb.Files.OpenStatusFilter:
		g.showMenu("Filtering", []*MenuItem{
			{Label: "Show only staged files", Key: "s"},
			{Label: "Show only unstaged files", Key: "u"},
			{Label: "Show only tracked files", Key: "t"},
			{Label: "Show only untracked files", Key: "T"},
			{Label: "Show only conflicted files", Key: "c"},
			{Label: "Reset filter", Key: "r"},
			{Label: "Cancel"},
		})
		return true
	case kb.Files.FindBaseCommitForFixup:
		return true
	}
	_ = ctx
	return false
}

func (g *Gui) anyMergeConflicts() bool {
	for _, f := range g.files {
		if f.HasMergeConflicts {
			return true
		}
	}
	return false
}

func (g *Gui) anyStagedChanges() bool {
	for _, f := range g.files {
		if f.HasStagedChanges {
			return true
		}
	}
	return false
}

func (n *FileNode) allDirs() []*FileNode {
	var out []*FileNode
	if n.IsDir() {
		out = append(out, n)
		for _, c := range n.Children {
			out = append(out, c.allDirs()...)
		}
	}
	return out
}

func (g *Gui) toggleStaged(node *FileNode) {
	files := node.Files()
	if len(files) == 0 {
		return
	}
	if node.IsDir() {
		// if any file has unstaged changes, stage all; else unstage all
		anyUnstaged := false
		for _, f := range files {
			if f.HasUnstagedChanges {
				anyUnstaged = true
			}
		}
		path := node.Path
		if path == "" {
			path = "."
		}
		if anyUnstaged {
			g.gitRun("add", "--", path)
		} else {
			g.gitRun("reset", "--", path)
		}
		g.afterFileAction()
		return
	}
	f := files[0]
	if f.HasMergeConflicts {
		g.gitRun("add", "--", f.Name)
	} else if f.HasUnstagedChanges {
		if f.Tracked {
			g.gitRun("add", "--", f.Name)
		} else {
			g.gitRun("add", "--", f.Name)
		}
	} else {
		if f.Added && !g.hasCommits {
			g.gitRun("rm", "--cached", "--", f.Name)
		} else {
			g.gitRun("reset", "--", f.Name)
		}
	}
	g.afterFileAction()
}

func (g *Gui) toggleStagedAll() {
	anyUnstaged := false
	for _, f := range g.files {
		if f.HasUnstagedChanges {
			anyUnstaged = true
		}
	}
	if anyUnstaged {
		g.gitRun("add", "-A")
	} else {
		if g.hasCommits {
			g.gitRun("reset")
		} else {
			g.gitRun("rm", "-r", "--cached", ".")
		}
	}
	g.afterFileAction()
}

func (g *Gui) commitChanges(noVerify bool) {
	if len(g.files) == 0 {
		g.showErrorPopup("There are no files to commit")
		return
	}
	if g.anyMergeConflicts() {
		g.showErrorPopup("There are files with merge conflicts")
		return
	}
	if !g.anyStagedChanges() {
		if g.cfg.Gui.SkipNoStagedFilesWarning {
			g.gitRun("add", "-A")
			g.afterFileAction()
			g.openCommitMessagePanel(noVerify)
			return
		}
		g.showConfirm("No files staged", "You have not staged any files. Commit all files?", func() {
			g.gitRun("add", "-A")
			g.refreshFiles()
			g.openCommitMessagePanel(noVerify)
		}, nil)
		return
	}
	g.openCommitMessagePanel(noVerify)
}

func (g *Gui) showDiscardMenu(node *FileNode) {
	var items []*MenuItem
	label := "Discard all changes"
	items = append(items, &MenuItem{Label: label, Key: "x", OnPress: func() {
		g.discardAll(node)
	}})
	hasStaged := false
	for _, f := range node.Files() {
		if f.HasStagedChanges {
			hasStaged = true
		}
	}
	if hasStaged || node.IsDir() {
		items = append(items, &MenuItem{Label: "Discard unstaged changes", Key: "u", OnPress: func() {
			g.discardUnstaged(node)
		}})
	}
	items = append(items, &MenuItem{Label: "Cancel"})
	g.showMenu("Discard changes", items)
}

func (g *Gui) discardAll(node *FileNode) {
	for _, f := range node.Files() {
		if !f.Tracked {
			g.logCommand("rm "+f.Name, false)
			os.RemoveAll(filepath.Join(g.repo.WorkTree, f.Name))
			continue
		}
		if f.Added {
			g.gitRun("rm", "--cached", "--force", "--", f.Name)
			os.RemoveAll(filepath.Join(g.repo.WorkTree, f.Name))
			continue
		}
		g.gitRun("checkout", "HEAD", "--", f.Name)
	}
	g.afterFileAction()
}

func (g *Gui) discardUnstaged(node *FileNode) {
	for _, f := range node.Files() {
		if !f.Tracked {
			os.RemoveAll(filepath.Join(g.repo.WorkTree, f.Name))
			continue
		}
		g.gitRun("checkout", "--", f.Name)
	}
	g.afterFileAction()
}

func (g *Gui) showResetMenu() {
	run := func(args ...[]string) func() {
		return func() {
			for _, a := range args {
				if err := g.gitRun(a...); err != nil {
					g.showErrorPopup(err.Error())
					break
				}
			}
			g.refreshAll()
			g.updateMainView()
		}
	}
	items := []*MenuItem{
		{Label: "Nuke working tree", Key: "x", Command: "git reset --hard HEAD && git clean -fd", Tooltip: "If you want to make all the changes in the worktree go away, this is the way to do it. If there are dirty submodule changes this will stash those changes in the submodule(s).", OnPress: run([]string{"reset", "--hard", "HEAD"}, []string{"clean", "-fd"})},
		{Label: "Discard unstaged changes", Key: "u", Command: "git checkout -- .", OnPress: run([]string{"checkout", "--", "."})},
		{Label: "Discard untracked files", Key: "c", Command: "git clean -fd", OnPress: run([]string{"clean", "-fd"})},
		{Label: "Discard staged changes", Key: "S", Command: "stash staged and drop stash", Tooltip: "This will stash your staged changes and drop the stash.", OnPress: func() {
			g.gitRun("stash", "push", "--staged")
			g.gitRun("stash", "drop")
			g.refreshAll()
			g.updateMainView()
		}},
		{Label: "Soft reset", Key: "s", Command: "git reset --soft HEAD", OnPress: run([]string{"reset", "--soft", "HEAD"})},
		{Label: "mixed reset", Key: "m", Command: "git reset --mixed HEAD", OnPress: run([]string{"reset", "--mixed", "HEAD"})},
		{Label: "Hard reset", Key: "h", Command: "git reset --hard HEAD", OnPress: run([]string{"reset", "--hard", "HEAD"})},
		{Label: "Cancel"},
	}
	g.showMenu("", items)
}

func (g *Gui) showUpstreamResetMenu() {
	run := func(mode string) func() {
		return func() {
			if err := g.gitRun("reset", mode, "@{upstream}"); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}
	}
	items := []*MenuItem{
		{Label: "Mixed reset", Key: "m", Command: "reset --mixed @{upstream}", OnPress: run("--mixed")},
		{Label: "Soft reset", Key: "s", Command: "reset --soft @{upstream}", OnPress: run("--soft")},
		{Label: "Hard reset", Key: "h", Command: "reset --hard @{upstream}", OnPress: run("--hard")},
		{Label: "Cancel"},
	}
	g.showMenu("Reset to @{upstream}", items)
}

func (g *Gui) showStashOptionsMenu() {
	prompt := func(args ...string) func() {
		return func() {
			g.showPrompt("Stash changes", "", func(msg string) {
				full := append([]string{"stash", "push"}, args...)
				if msg != "" {
					full = append(full, "-m", msg)
				}
				if err := g.gitRun(full...); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			})
		}
	}
	items := []*MenuItem{
		{Label: "Stash all changes", Key: "a", OnPress: prompt()},
		{Label: "Stash all changes and keep index", Key: "i", OnPress: prompt("--keep-index")},
		{Label: "Stash all changes including untracked files", Key: "U", OnPress: prompt("--include-untracked")},
		{Label: "Stash staged changes", Key: "s", OnPress: prompt("--staged")},
		{Label: "Stash unstaged changes", Key: "u", OnPress: prompt("--keep-index")},
		{Label: "Cancel"},
	}
	g.showMenu("Stash options", items)
}

func (g *Gui) showIgnoreMenu(node *FileNode) {
	appendLine := func(file string) {
		path := filepath.Join(g.repo.WorkTree, file)
		os.MkdirAll(filepath.Dir(path), 0o755)
		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
		if err != nil {
			g.showErrorPopup(err.Error())
			return
		}
		f.WriteString(node.Path + "\n")
		f.Close()
		g.afterFileAction()
	}
	items := []*MenuItem{
		{Label: "Add to .gitignore", Key: "i", OnPress: func() { appendLine(".gitignore") }},
		{Label: "Add to .git/info/exclude", Key: "e", OnPress: func() { appendLine(".git/info/exclude") }},
		{Label: "Cancel"},
	}
	g.showMenu("Ignore or exclude file", items)
}

func (g *Gui) enterStagingView(node *FileNode) {
	// staging individual lines is not supported; focus the main view instead
	g.focusMain()
}

