// branches

func (g *Gui) handleBranchesKey(name string) bool {
	kb := &g.cfg.Keybinding
	b := g.selectedBranch()
	switch name {
	case kb.Universal.Select:
		if b == nil || b.Head {
			return true
		}
		g.checkout(b.Name)
		return true
	case kb.Universal.New:
		base := ""
		if b != nil {
			base = b.Name
		}
		g.showPrompt(fmt.Sprintf("New branch name (branch is off of '%s')", base), "", func(nameInput string) {
			if strings.TrimSpace(nameInput) == "" {
				return
			}
			args := []string{"checkout", "-b", strings.TrimSpace(nameInput)}
			if base != "" {
				args = append(args, base)
			}
			if err := g.gitRun(args...); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Universal.Remove:
		if b == nil {
			return true
		}
		if b.Head {
			g.showErrorPopup("You cannot delete the checked out branch!")
			return true
		}
		g.showMenu("Delete branch '"+b.Name+"'?", []*MenuItem{
			{Label: "Delete local branch", Key: "c", OnPress: func() {
				if err := g.gitRun("branch", "-d", b.Name); err != nil {
					g.showConfirm("Force delete branch", fmt.Sprintf("'%s' is not fully merged. Are you sure you want to delete it?", b.Name), func() {
						if err := g.gitRun("branch", "-D", b.Name); err != nil {
							g.showErrorPopup(err.Error())
						}
						g.refreshAll()
						g.updateMainView()
					}, nil)
					return
				}
				g.refreshAll()
				g.updateMainView()
			}},
			{Label: "Cancel"},
		})
		return true
	case kb.Branches.RebaseBranch:
		if b == nil || b.Head {
			return true
		}
		g.showMenu(fmt.Sprintf("Rebase '%s' onto '%s'", g.currentBranch, b.Name), []*MenuItem{
			{Label: "Simple rebase", Key: "s", OnPress: func() {
				if err := g.gitRun("rebase", b.Name); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			}},
			{Label: "Interactive rebase", Key: "i", OnPress: func() {
				g.runSubprocess([]string{"git", "rebase", "-i", b.Name})
			}},
			{Label: "Cancel"},
		})
		return true
	case kb.Branches.MergeIntoCurrentBranch:
		if b == nil || b.Head {
			return true
		}
		g.showMenu(fmt.Sprintf("Merge '%s' into '%s'", b.Name, g.currentBranch), []*MenuItem{
			{Label: "Regular merge", Key: "m", OnPress: func() {
				if err := g.gitRun("merge", "--no-edit", b.Name); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			}},
			{Label: "Squash merge and commit", Key: "s", OnPress: func() {
				if err := g.gitRun("merge", "--squash", b.Name); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			}},
			{Label: "Cancel"},
		})
		return true
	case kb.Branches.RenameBranch:
		if b == nil {
			return true
		}
		g.showPrompt("Enter new branch name", b.Name, func(n string) {
			n = strings.TrimSpace(n)
			if n == "" || n == b.Name {
				return
			}
			if err := g.gitRun("branch", "--move", b.Name, n); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Branches.CheckoutBranchByName:
		g.showPrompt("Branch name:", "", func(n string) {
			n = strings.TrimSpace(n)
			if n == "" {
				return
			}
			g.checkout(n)
		})
		return true
	case kb.Branches.CheckoutPreviousBranch:
		g.checkout("-")
		return true
	case kb.Branches.FastForward:
		if b == nil || !b.HasUpstream {
			return true
		}
		if b.Head {
			g.gitRun("pull", "--ff-only")
		} else {
			g.gitRun("fetch", strings.SplitN(b.Upstream, "/", 2)[0], fmt.Sprintf("%s:%s", strings.SplitN(b.Upstream, "/", 2)[1], b.Name))
		}
		g.refreshAll()
		g.updateMainView()
		return true
	case kb.Branches.SetUpstream:
		g.showMenu("Upstream options", []*MenuItem{
			{Label: "View divergence from upstream", Key: "v"},
			{Label: "Unset upstream of selected branch", Key: "u", OnPress: func() {
				if b != nil {
					g.gitRun("branch", "--unset-upstream", b.Name)
					g.refreshAll()
					g.updateMainView()
				}
			}},
			{Label: "Set upstream of selected branch", Key: "s"},
			{Label: "Cancel"},
		})
		return true
	case kb.Branches.CreateTag:
		if b == nil {
			return true
		}
		g.showPrompt("Tag name", "", func(t string) {
			t = strings.TrimSpace(t)
			if t == "" {
				return
			}
			if err := g.gitRun("tag", "--", t, b.Name); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Universal.GoInto:
		return true
	}
	return false
}

func (g *Gui) checkout(ref string) {
	if err := g.gitRun("checkout", ref); err != nil {
		g.showErrorPopup(err.Error())
	}
	g.refreshAll()
	g.resetMainOrigin()
	g.updateMainView()
}

// ---------------------------------------------------------------------------
// commits

func (g *Gui) handleCommitsKey(name string) bool {
	kb := &g.cfg.Keybinding
	c := g.selectedCommit()
	switch name {
	case kb.Universal.Select:
		if c == nil {
			return true
		}
		g.showConfirm("Checkout commit", fmt.Sprintf("Are you sure you want to checkout this commit?"), func() {
			g.checkout(c.Hash)
		}, nil)
		return true
	case kb.Commits.RenameCommit:
		if c == nil {
			return true
		}
		if g.contexts["commits"].selected != 0 {
			g.showErrorPopup("Can only reword the head commit here")
			return true
		}
		g.showPrompt("Reword commit", c.Subject, func(msg string) {
			if strings.TrimSpace(msg) == "" {
				return
			}
			if err := g.gitRun("commit", "--allow-empty", "--amend", "--only", "-m", msg); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Commits.RevertCommit:
		if c == nil {
			return true
		}
		g.showConfirm("Revert commit", fmt.Sprintf("Are you sure you want to revert %s?", c.Hash[:8]), func() {
			if err := g.gitRun("revert", "--no-edit", c.Hash); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Commits.TagCommit:
		if c == nil {
			return true
		}
		g.showPrompt("Tag name", "", func(t string) {
			t = strings.TrimSpace(t)
			if t == "" {
				return
			}
			if err := g.gitRun("tag", "--", t, c.Hash); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Commits.ViewResetOptions:
		if c == nil {
			return true
		}
		g.showResetToCommitMenu(c.Hash, c.Hash[:8])
		return true
	case kb.Universal.Remove:
		if c == nil {
			return true
		}
		if g.contexts["commits"].selected != 0 {
			g.showErrorPopup("Interactive rebase is not supported")
			return true
		}
		g.showConfirm("Drop commit", "Are you sure you want to drop the selected commit(s)?", func() {
			if err := g.gitRun("reset", "--hard", "HEAD~1"); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Commits.CopyCommitAttributeToClipboard:
		if c == nil {
			return true
		}
		g.showMenu("Copy to clipboard", []*MenuItem{
			{Label: "Commit hash", Key: "h"},
			{Label: "Commit subject", Key: "s"},
			{Label: "Commit message", Key: "m"},
			{Label: "Commit URL", Key: "u"},
			{Label: "Commit diff", Key: "d"},
			{Label: "Commit author", Key: "a"},
			{Label: "Cancel"},
		})
		return true
	case kb.Commits.OpenLogMenu:
		g.showMenu("Log menu", []*MenuItem{
			{Label: "Commit sort order", Key: "s"},
			{Label: "Show git graph", Key: "g"},
			{Label: "Show whole git graph", Key: "w"},
			{Label: "Cancel"},
		})
		return true
	case kb.Universal.GoInto:
		return true
	}
	return false
}

func (g *Gui) showResetToCommitMenu(ref string, display string) {
	run := func(mode string) func() {
		return func() {
			if err := g.gitRun("reset", mode, ref); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}
	}
	items := []*MenuItem{
		{Label: "Mixed reset", Key: "m", Command: "reset --mixed " + display, OnPress: run("--mixed")},
		{Label: "Soft reset", Key: "s", Command: "reset --soft " + display, OnPress: run("--soft")},
		{Label: "Hard reset", Key: "h", Command: "reset --hard " + display, OnPress: run("--hard")},
		{Label: "Cancel"},
	}
	g.showMenu("Reset to "+display, items)
}

