// stash

func (g *Gui) handleStashKey(name string) bool {
	kb := &g.cfg.Keybinding
	e := g.selectedStash()
	switch name {
	case kb.Universal.Select:
		if e == nil {
			return true
		}
		g.showConfirm("Stash apply", "Are you sure you want to apply this stash entry?", func() {
			if err := g.gitRun("stash", "apply", fmt.Sprintf("stash@{%d}", e.Index)); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			if g.cfg.Gui.SwitchToFilesAfterStashApply {
				g.focusWindow("files")
			}
			g.updateMainView()
		}, nil)
		return true
	case kb.Stash.PopStash:
		if e == nil {
			return true
		}
		g.showConfirm("Stash pop", "Are you sure you want to pop this stash entry?", func() {
			if err := g.gitRun("stash", "pop", fmt.Sprintf("stash@{%d}", e.Index)); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			if g.cfg.Gui.SwitchToFilesAfterStashPop {
				g.focusWindow("files")
			}
			g.updateMainView()
		}, nil)
		return true
	case kb.Universal.Remove:
		if e == nil {
			return true
		}
		g.showConfirm("Stash drop", "Are you sure you want to drop this stash entry?", func() {
			if err := g.gitRun("stash", "drop", fmt.Sprintf("stash@{%d}", e.Index)); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Universal.New:
		if e == nil {
			return true
		}
		g.showPrompt("New branch name", "", func(n string) {
			n = strings.TrimSpace(n)
			if n == "" {
				return
			}
			if err := g.gitRun("stash", "branch", n, fmt.Sprintf("stash@{%d}", e.Index)); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Stash.RenameStash:
		if e == nil {
			return true
		}
		g.showPrompt(fmt.Sprintf("Rename stash: stash@{%d}", e.Index), e.Name, func(n string) {
			n = strings.TrimSpace(n)
			if n == "" {
				return
			}
			out, err := g.repo.Run("rev-parse", fmt.Sprintf("stash@{%d}", e.Index))
			if err != nil {
				g.showErrorPopup(err.Error())
				return
			}
			hash := strings.TrimSpace(out)
			g.gitRun("stash", "drop", fmt.Sprintf("stash@{%d}", e.Index))
			g.gitRun("stash", "store", "-m", n, hash)
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Universal.GoInto:
		return true
	}
	return false
}

