func (g *Gui) drawCommitMessagePopup(p *Popup, width, height int) {
	st := commitMsgStates[p]
	pw := confirmationPanelWidth(width)
	x0 := width/2 - pw/2
	x1 := width/2 + pw/2
	// description height scales with terminal height
	descInner := height/4 - 3
	if descInner < 3 {
		descInner = 3
	}
	totalRows := 3 + descInner + 2
	y0 := height/2 - totalRows/2 - 1 + 1
	if y0 < 0 {
