	sv.X0, sv.X1, sv.Y0, sv.Y1 = x0, x1, y0, y0+2
	sv.Frame = true
	sv.Visible = true
	sv.Wrap = false
	sv.ShowScrollbar = false
	if st.inDesc {
		sv.FrameStyle = inactive
	} else {
		sv.FrameStyle = active
	}
	sv.Title = Line{{Text: "Commit summary", Style: sv.FrameStyle}}
	summary := string(st.summary)
	sv.SetContent([]Line{plain(summary)})
	// horizontal scroll so that the cursor is visible
	iw := sv.InnerWidth()
	if !st.inDesc {
		cw := term.StringWidth(string(st.summary[:st.cursor]))
		if cw-sv.OriginX >= iw {
			sv.OriginX = cw - iw + 1
		}
		if cw < sv.OriginX {
			sv.OriginX = cw
		}
	}
	sv.Draw(g.scr)
	// character counter subtitle
	if g.cfg.Gui.CommitLength.Show {
		counter := fmt.Sprintf(" %d ", len(st.summary))
		cx := x1 - len(counter) - 5
		for _, r := range counter {
			g.scr.Set(cx, y0, r, sv.FrameStyle)
			cx++
		}
	}

	dv := st.descView
	dv.X0, dv.X1, dv.Y0, dv.Y1 = x0, x1, y0+3, y0+3+descInner+1
	dv.Frame = true
	dv.Visible = true
	dv.Wrap = true
	dv.ShowScrollbar = false
	if st.inDesc {
		dv.FrameStyle = active
	} else {
		dv.FrameStyle = inactive
	}
	dv.Title = Line{{Text: "Commit description", Style: dv.FrameStyle}}
	dv.SetContent(ParseANSILines(string(st.description) + "\n"))
	dv.Draw(g.scr)
	subtitle := "Press <tab> to toggle focus, <c-o> to open menu"
	sx := x1 - len(subtitle) - 1
	for _, r := range subtitle {
		g.scr.Set(sx, dv.Y0, r, dv.FrameStyle)
		sx++
	}

	// cursor
	if st.inDesc {
		// compute cursor position in wrapped description
		before := string(st.description[:st.cursor])
		lines := strings.Split(before, "\n")
		row := len(lines) - 1
		col := term.StringWidth(lines[len(lines)-1])
		iw := dv.InnerWidth()
		if iw > 0 {
			// account for wrapping of previous lines approximately
			extra := 0
			for _, l := range lines[:len(lines)-1] {
				w := term.StringWidth(l)
