	st := commitMsgStates[p]
	pw := confirmationPanelWidth(width)
	x0 := width/2 - pw/2
	x1 := width/2 + pw/2
	// description height scales with terminal height
	descInner := height/4 - 3
	if descInner < 3 {
		descInner = 3
	}
	totalRows := 3 + descInner + 2
	y0 := height/2 - totalRows/2 - 1 + 1
	if y0 < 0 {
		y0 = 0
	}
	active := styleFromConfig(g.cfg.Gui.Theme.ActiveBorderColor)
	inactive := styleFromConfig(g.cfg.Gui.Theme.InactiveBorderColor)

	sv := st.summaryView
	sv.X0, sv.X1, sv.Y0, sv.Y1 = x0, x1, y0, y0+2
	sv.Frame = true
	sv.Visible = true
	sv.Wrap = false
	sv.ShowScrollbar = false
	if st.inDesc {
		sv.FrameStyle = inactive
	} else {
		sv.FrameStyle = active
	}
	sv.Title = Line{{Text: "Commit summary", Style: sv.FrameStyle}}
	summary := string(st.summary)
	sv.SetContent([]Line{plain(summary)})
	// horizontal scroll so that the cursor is visible
	iw := sv.InnerWidth()
	if !st.inDesc {
		cw := term.StringWidth(string(st.summary[:st.cursor]))
		if cw-sv.OriginX >= iw {
			sv.OriginX = cw - iw + 1
		}
		if cw < sv.OriginX {
			sv.OriginX = cw
		}
	}
	sv.Draw(g.scr)
	// character counter subtitle
	if g.cfg.Gui.CommitLength.Show {
		counter := fmt.Sprintf(" %d ", len(st.summary))
		cx := x1 - len(counter) - 5
		for _, r := range counter {
			g.scr.Set(cx, y0, r, sv.FrameStyle)
			cx++
		}
	}

	dv := st.descView
	dv.X0, dv.X1, dv.Y0, dv.Y1 = x0, x1, y0+3, y0+3+descInner+1
	dv.Frame = true
	dv.Visible = true
	dv.Wrap = true
	dv.ShowScrollbar = false
	if st.inDesc {
		dv.FrameStyle = active
	} else {
		dv.FrameStyle = inactive
	}
	dv.Title = Line{{Text: "Commit description", Style: dv.FrameStyle}}
	dv.SetContent(ParseANSILines(string(st.description) + "\n"))
	dv.Draw(g.scr)
	subtitle := "Press <tab> to toggle focus, <c-o> to open menu"
	sx := x1 - len(subtitle) - 1
	for _, r := range subtitle {
		g.scr.Set(sx, dv.Y0, r, dv.FrameStyle)
		sx++
	}

	// cursor
	if st.inDesc {
		// compute cursor position in wrapped description
		before := string(st.description[:st.cursor])
		lines := strings.Split(before, "\n")
		row := len(lines) - 1
		col := term.StringWidth(lines[len(lines)-1])
		iw := dv.InnerWidth()
		if iw > 0 {
			// account for wrapping of previous lines approximately
			extra := 0
			for _, l := range lines[:len(lines)-1] {
				w := term.StringWidth(l)
				if w > iw {
					extra += (w - 1) / iw
				}
			}
			row += extra
			for col >= iw {
				col -= iw
				row++
			}
		}
		g.scr.ShowCursor(dv.X0+1+col, dv.Y0+1+row-dv.OriginY)
	} else {
		cw := term.StringWidth(string(st.summary[:st.cursor]))
		g.scr.ShowCursor(sv.X0+1+cw-sv.OriginX, sv.Y0+1)
	}
}

func (g *Gui) handleCommitMessageKey(p *Popup, name string, ev term.Event) {
	st := commitMsgStates[p]
	buf := &st.summary
	if st.inDesc {
		buf = &st.description
	}
	switch name {
	case "<esc>":
		g.popPopup()
		delete(commitMsgStates, p)
		return
	case "<c-c>":
		g.Quit()
		return
	case "<tab>":
		st.inDesc = !st.inDesc
		if st.inDesc {
			st.cursor = len(st.description)
		} else {
			st.cursor = len(st.summary)
		}
		return
	case "<enter>":
		if st.inDesc {
			*buf = append((*buf)[:st.cursor], append([]rune{'\n'}, (*buf)[st.cursor:]...)...)
			st.cursor++
			return
		}
		g.submitCommit(p, st)
		return
	case "<a-enter>", "<c-s>":
		g.submitCommit(p, st)
		return
	case "<c-o>":
		g.showMenu("Commit Menu", []*MenuItem{
			{Label: "Open in editor", Key: "e", OnPress: func() {
				g.popPopup()
				delete(commitMsgStates, p)
				g.runSubprocess([]string{"git", "commit"})
			}},
			{Label: "Add co-author", Key: "c"},
			{Label: "Paste commit message from clipboard", Key: "p"},
			{Label: "Cancel"},
		})
		return
	case "<backspace>":
		if st.cursor > 0 {
			*buf = append((*buf)[:st.cursor-1], (*buf)[st.cursor:]...)
			st.cursor--
		}
		return
	case "<delete>":
		if st.cursor < len(*buf) {
			*buf = append((*buf)[:st.cursor], (*buf)[st.cursor+1:]...)
		}
		return
	case "<left>":
		if st.cursor > 0 {
			st.cursor--
		}
		return
	case "<right>":
		if st.cursor < len(*buf) {
			st.cursor++
		}
		return
	case "<home>", "<c-a>":
		st.cursor = 0
		return
	case "<end>", "<c-e>":
		st.cursor = len(*buf)
		return
	case "<up>":
		if st.inDesc {
			// move to previous line
			text := string((*buf)[:st.cursor])
			idx := strings.LastIndex(text, "\n")
			if idx >= 0 {
				col := len([]rune(text[idx+1:]))
				prevStart := strings.LastIndex(text[:idx], "\n") + 1
				prevLen := len([]rune(text[prevStart:idx]))
				if col > prevLen {
					col = prevLen
				}
				st.cursor = len([]rune(text[:prevStart])) + col
			}
		} else {
			// nothing
		}
		return
	case "<down>":
		if st.inDesc {
			all := *buf
			text := string(all[:st.cursor])
			lineStart := strings.LastIndex(text, "\n") + 1
			col := len([]rune(text[lineStart:]))
			rest := string(all[st.cursor:])
			nl := strings.Index(rest, "\n")
			if nl >= 0 {
				nextStart := st.cursor + len([]rune(rest[:nl])) + 1
				nextRest := string(all[nextStart:])
				nextLen := len([]rune(nextRest))
				if i := strings.Index(nextRest, "\n"); i >= 0 {
					nextLen = len([]rune(nextRest[:i]))
				}
				if col > nextLen {
					col = nextLen
				}
				st.cursor = nextStart + col
			}
		}
		return
	case "<c-u>":
		*buf = (*buf)[st.cursor:]
		st.cursor = 0
		return
	case "<c-k>":
		*buf = (*buf)[:st.cursor]
		return
	case "<c-w>":
		i := st.cursor
		for i > 0 && (*buf)[i-1] == ' ' {
			i--
		}
		for i > 0 && (*buf)[i-1] != ' ' {
			i--
		}
		*buf = append((*buf)[:i], (*buf)[st.cursor:]...)
		st.cursor = i
		return
	}
	if ev.Key == term.KeyRune && ev.Mod&term.ModAlt == 0 {
		*buf = append((*buf)[:st.cursor], append([]rune{ev.Rune}, (*buf)[st.cursor:]...)...)
		st.cursor++
	}
}

func (g *Gui) submitCommit(p *Popup, st *commitMessageState) {
	summary := strings.TrimSpace(string(st.summary))
	if summary == "" {
		g.showErrorPopup("You cannot commit without a commit message")
		return
	}
	message := summary
	desc := strings.TrimRight(string(st.description), "\n")
	if desc != "" {
		message += "\n\n" + desc
	}
	args := []string{"commit", "-m", message}
	if st.noVerify {
		args = append(args, "--no-verify")
	}
	if g.cfg.Git.Commit.SignOff {
		args = append(args, "--signoff")
	}
	g.popPopup()
	delete(commitMsgStates, p)
	if err := g.gitRun(args...); err != nil {
		g.showErrorPopup(err.Error())
	}
	g.refreshAll()
	g.updateMainView()
}
