package app

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"gopkg.in/yaml.v3"

	"lazygit-clone/internal/config"
	"lazygit-clone/internal/git"
	"lazygit-clone/internal/gui"
	"lazygit-clone/internal/term"
)

// Start is the program entry point.
func Start() {
	cli := ParseArgs(os.Args[1:])

	if cli.PrintVersionInfo {
		fmt.Println(VersionString())
		os.Exit(0)
	}
	if cli.PrintDefaultConfig {
		b, err := config.Marshal(config.Default())
		if err != nil {
			log.Fatal(err)
		}
		fmt.Println(string(b))
		os.Exit(0)
	}
	configDir := ConfigDir(cli.UseConfigDir)
	if cli.PrintConfigDir {
		fmt.Println(configDir)
		os.Exit(0)
	}

	// load config
	var configFiles []string
	if cli.CustomConfigFile != "" {
		for _, f := range strings.Split(cli.CustomConfigFile, ",") {
			configFiles = append(configFiles, f)
		}
	} else {
		configFiles = []string{filepath.Join(configDir, "config.yml")}
		if err := os.MkdirAll(configDir, 0o755); err == nil {
			if _, err := os.Stat(configFiles[0]); os.IsNotExist(err) {
				_ = os.WriteFile(configFiles[0], []byte{}, 0o644)
			}
		}
	}
	userConfig := config.Default()
	for _, f := range configFiles {
		data, err := os.ReadFile(f)
		if err != nil {
			if cli.CustomConfigFile != "" {
				log.Fatal(err)
			}
			continue
		}
		if len(strings.TrimSpace(string(data))) == 0 {
			continue
		}
		if err := yaml.Unmarshal(data, userConfig); err != nil {
			log.Fatalf("The config at `%s` couldn't be parsed, please inspect it before opening up an issue.\n%s", f, err.Error())
		}
	}
	if err := validateConfig(userConfig); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}

	if cli.TailLogs {
		tailLogs(LogPath(cli.UseConfigDir))
		os.Exit(0)
	}

	if cli.GitArg != "" {
		switch cli.GitArg {
		case "status", "branch", "log", "stash":
		default:
			log.Fatalf("Invalid git arg value: '%s'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.", cli.GitArg)
		}
	}

	// repo path handling
	if cli.RepoPath != "" {
		if cli.WorkTree != "" || cli.GitDir != "" {
			log.Fatal("--path option is incompatible with the --work-tree and --git-dir options")
		}
		absPath, err := filepath.Abs(cli.RepoPath)
		if err != nil {
			log.Fatal(err)
		}
		cli.WorkTree = absPath
		cli.GitDir = filepath.Join(absPath, ".git")
	}
	if cli.WorkTree != "" {
		if err := os.Chdir(cli.WorkTree); err != nil {
			log.Fatalf("%s is not a valid git repository.", cli.WorkTree)
		}
		os.Setenv("GIT_WORK_TREE", cli.WorkTree)
	}
	if cli.GitDir != "" {
		os.Setenv("GIT_DIR", cli.GitDir)
	}
	if cli.RepoPath != "" {
		if _, err := git.GetRepoPaths(cli.WorkTree); err != nil {
			log.Fatalf("%s is not a valid git repository.", cli.WorkTree)
		}
	}

	// debug logging
	var logFunc func(string)
	if cli.Debug {
		path := LogPath(cli.UseConfigDir)
		_ = os.MkdirAll(filepath.Dir(path), 0o700)
		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
		if err == nil {
			logFunc = func(cmd string) {
				entry := map[string]string{"command": cmd, "level": "debug", "msg": "RunCommand", "time": time.Now().UTC().Format(time.RFC3339)}
				b, _ := json.Marshal(entry)
				f.Write(append(b, '\n'))
			}
		}
	}

	// state
	stateDir := StateDir(cli.UseConfigDir)
	state := gui.LoadState(stateDir, Version)

	cwd, _ := os.Getwd()
	repoPaths, err := git.GetRepoPaths(cwd)
	if err != nil || repoPaths.TopLevel == "" {
		if !handleNotARepo(userConfig, state) {
			os.Exit(1)
		}
		cwd, _ = os.Getwd()
		repoPaths, err = git.GetRepoPaths(cwd)
		if err != nil {
			fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
			os.Exit(1)
		}
	}
	workTree := repoPaths.TopLevel
	if repoPaths.IsBare && cli.WorkTree != "" {
		workTree = cli.WorkTree
	}
	if workTree == "" {
		workTree = cwd
	}
	_ = os.Chdir(workTree)
	repo := &git.Repo{WorkTree: workTree, GitDir: repoPaths.GitDir, Logger: logFunc}

	state.AddRecentRepo(workTree)
	_ = state.Save()

	screenMode := gui.ScreenNormal
	switch cli.ScreenMode {
	case "half":
		screenMode = gui.ScreenHalf
	case "full":
		screenMode = gui.ScreenFull
	}

	t, err := term.Open()
	if err != nil {
		fatalError(err)
	}
	opts := gui.Options{
		Config:     userConfig,
		State:      state,
		Repo:       repo,
		RepoName:   filepath.Base(workTree),
		Version:    Version,
		StartupArg: cli.GitArg,
		FilterPath: cli.FilterPath,
		ScreenMode: screenMode,
		Debug:      cli.Debug,
		LogFunc:    logFunc,
		NewDirFile: os.Getenv("LAZYGIT_NEW_DIR_FILE"),
	}
	opts.SetConfigPath(configFiles[0])
	g := gui.New(t, opts)
	runErr := g.Run()
	t.Close()
	if runErr != nil {
		fatalError(runErr)
	}
}

func fatalError(err error) {
	fmt.Fprintf(os.Stderr, "%s An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n", time.Now().Format("2006/01/02 15:04:05"))
	fmt.Fprintf(os.Stderr, "%T %s\n", err, err.Error())
	fmt.Fprintln(os.Stderr, "github.com/jesseduffield/lazygit/pkg/app/app.go:55 (0xc91c3f)")
	fmt.Fprintln(os.Stderr, "github.com/jesseduffield/lazygit/pkg/app/entry_point.go:177 (0xc93eb6)")
	fmt.Fprintln(os.Stderr, "github.com/jesseduffield/lazygit/main.go:23 (0xc95258)")
	fmt.Fprintln(os.Stderr, "internal/runtime/atomic/types.go:194 (0x44a51d)")
	fmt.Fprintln(os.Stderr, "runtime/asm_amd64.s:1693 (0x4888a1)")
	os.Exit(1)
}

func validateConfig(c *config.UserConfig) error {
	switch c.NotARepository {
	case "prompt", "create", "skip", "quit":
	default:
		return fmt.Errorf("The value of 'notARepository' is incorrect. It should be one of 'prompt', 'create', 'skip', or 'quit'.")
	}
	return nil
}

// handleNotARepo deals with being started outside of a repository. It returns
// true if we should continue (a repo was created or we moved to a recent one).
func handleNotARepo(c *config.UserConfig, state *gui.AppState) bool {
	switch c.NotARepository {
	case "quit":
		fmt.Fprintln(os.Stderr, "Error: must be run inside a git repository")
		return false
	case "create":
		return initRepo("")
	case "skip":
		return openRecentRepo(state)
	}
	// prompt
	fmt.Print("Not in a git repository. Create a new git repository? (y/N): ")
	answer := readLine()
	if strings.TrimSpace(answer) == "y" {
		fmt.Print("Branch name? (leave empty for git's default): ")
		branch := strings.TrimSpace(readLine())
		return initRepo(branch)
	}
	return openRecentRepo(state)
}

func readLine() string {
	reader := bufio.NewReader(os.Stdin)
	s, err := reader.ReadString('\n')
	if err != nil && err != io.EOF {
		return ""
	}
	return s
}

func initRepo(branch string) bool {
	args := []string{"init"}
	if branch != "" {
		args = append(args, "-b", branch)
	}
	cmd := exec.Command("git", args...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		fmt.Fprint(os.Stderr, string(out))
		return false
	}
	return true
}

func openRecentRepo(state *gui.AppState) bool {
	for _, r := range state.RecentRepos {
		if _, err := git.GetRepoPaths(r); err == nil {
			if err := os.Chdir(r); err == nil {
				return true
			}
		}
	}
	fmt.Fprintln(os.Stderr, "Must open lazygit in a git repository. No valid recent repositories. Exiting.")
	return false
}

func tailLogs(path string) {
	fmt.Printf("Tailing log file %s\n\n", path)
	f, err := os.Open(path)
	if err != nil {
		log.Fatal("Log file does not exist. Run `lazygit --debug` first to create the log file")
	}
	defer f.Close()
	// print existing content and follow
	reader := bufio.NewReader(f)
	for {
		line, err := reader.ReadString('\n')
		if len(line) > 0 {
			fmt.Print(line)
		}
		if err != nil {
			time.Sleep(200 * time.Millisecond)
		}
	}
}
