package gui

import (
	"fmt"
	"strings"

	"lazygit-clone/internal/git"
)

// ---------------------------------------------------------------------------
// branches

func (g *Gui) baseBranchRef() string {
	refs := g.mainBranchRefs()
	if len(refs) == 0 {
		return ""
	}
	return strings.TrimPrefix(strings.TrimPrefix(refs[0], "refs/remotes/"), "refs/heads/")
}

func (g *Gui) handleBranchesKey(name string) bool {
	kb := &g.cfg.Keybinding
	b := g.selectedBranch()
	switch name {
	case kb.Universal.Select:
		if b == nil || b.Head {
			return true
		}
		g.checkoutBranch(b.Name)
		return true
	case kb.Universal.New:
		base := ""
		if b != nil {
			base = b.Name
		}
		g.promptNewBranch(base, base)
		return true
	case kb.Universal.Remove:
		if b == nil {
			return true
		}
		g.showDeleteBranchMenu(b)
		return true
	case kb.Branches.RebaseBranch:
		if b == nil {
			return true
		}
		g.showRebaseBranchMenu(b)
		return true
	case kb.Branches.MergeIntoCurrentBranch:
		if b == nil {
			return true
		}
		g.showMergeMenu(b)
		return true
	case kb.Branches.RenameBranch:
		if b == nil {
			return true
		}
		g.showPrompt("Enter new branch name", b.Name, func(n string) {
			n = strings.TrimSpace(n)
			if n == "" || n == b.Name {
				return
			}
			if err := g.gitRun("branch", "--move", b.Name, n); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		})
		return true
	case kb.Branches.CheckoutBranchByName:
		g.showPrompt("Branch name:", "", func(n string) {
			n = strings.TrimSpace(n)
			if n == "" {
				return
			}
			g.checkoutBranch(n)
		})
		return true
	case kb.Branches.CheckoutPreviousBranch:
		g.checkoutBranch("-")
		return true
	case kb.Branches.ForceCheckoutBranch:
		if b == nil || b.Head {
			return true
		}
		g.showConfirm("Force checkout branch", "Are you sure you want force checkout? You will lose all local changes", func() {
			if err := g.gitRun("checkout", "--force", b.Name); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Branches.FastForward:
		if b == nil {
			return true
		}
		if !b.HasUpstream {
			g.showErrorPopup("Cannot fast-forward a branch with no upstream")
			return true
		}
		g.fastForwardBranch(b)
		return true
	case kb.Branches.SetUpstream:
		if b == nil {
			return true
		}
		g.showUpstreamMenu(b)
		return true
	case kb.Branches.CreateTag:
		if b == nil {
			return true
		}
		g.openTagPanel(b.Name)
		return true
	case kb.Branches.SortOrder:
		g.showBranchSortMenu()
		return true
	case kb.Commits.ViewResetOptions:
		if b == nil {
			return true
		}
		g.showResetMenuFor(b.Name, b.Name)
		return true
	case kb.Branches.ViewGitFlowOptions:
		g.showErrorPopup("You need to install git-flow and enable it in this repo to use git-flow features")
		return true
	case kb.Branches.ViewPullRequestOptions:
		if b == nil {
			return true
		}
		g.showMenu("View create pull request options", []*MenuItem{
			{Label: b.Name + " → Default branch"},
			{Label: b.Name + " → Select branch"},
			{Label: "Cancel"},
		})
		return true
	case kb.Branches.CreatePullRequest:
		g.showErrorPopup("Unsupported git service")
		return true
	case kb.Universal.GoInto:
		return true
	}
	return false
}

func (g *Gui) promptNewBranch(base string, display string) {
	g.showPrompt(fmt.Sprintf("New branch name (branch is off of '%s')", display), "", func(nameInput string) {
		nameInput = strings.TrimSpace(nameInput)
		if nameInput == "" {
			return
		}
		args := []string{"checkout", "-b", nameInput}
		if base != "" {
			args = append(args, base)
		}
		if err := g.gitRun(args...); err != nil {
			g.showErrorPopup(err.Error())
		}
		g.refreshAll()
		g.updateMainView()
	})
}

func (g *Gui) workingTreeDirty() bool {
	for _, f := range g.files {
		if f.Tracked {
			return true
		}
	}
	return false
}

func (g *Gui) checkoutBranch(ref string) {
	if g.workingTreeDirty() {
		g.showConfirm("Autostash?", "You must stash and pop your changes to bring them across. Do this automatically? (enter/esc)", func() {
			if err := g.gitRun("stash", "push", "-m", "lazygit autostash"); err != nil {
				g.showErrorPopup(err.Error())
				return
			}
			if err := g.gitRun("checkout", ref); err != nil {
				g.showErrorPopup(err.Error())
				g.gitRun("stash", "pop")
				g.refreshAll()
				g.updateMainView()
				return
			}
			if err := g.gitRun("stash", "pop"); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return
	}
	g.checkout(ref)
}

func (g *Gui) showDeleteBranchMenu(b *git.Branch) {
	noUpstream := !b.HasUpstream || b.UpstreamGone
	reason := "The selected branch has no upstream (or the upstream is not stored locally)"
	deleteLocal := func() {
		if b.Head {
			g.showErrorPopup("You cannot delete the checked out branch!")
			return
		}
		if err := g.gitRun("branch", "-d", b.Name); err != nil {
			g.showConfirm("Force delete branch", fmt.Sprintf("'%s' is not fully merged. Are you sure you want to delete it?", b.Name), func() {
				if err := g.gitRun("branch", "-D", b.Name); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			}, nil)
			return
		}
		g.refreshAll()
		g.updateMainView()
	}
	deleteRemote := func() {
		parts := strings.SplitN(b.Upstream, "/", 2)
		if len(parts) != 2 {
			return
		}
		g.showConfirm("Delete branch '"+b.Upstream+"'?", fmt.Sprintf("Are you sure you want to delete the remote branch '%s' from '%s'?", parts[1], parts[0]), func() {
			if err := g.gitRun("push", parts[0], "--delete", parts[1]); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
	}
	items := []*MenuItem{
		{Label: "Delete local branch", Key: "c", OnPress: deleteLocal},
		{Label: "Delete remote branch", Key: "r", Disabled: noUpstream, DisabledReason: reason, OnPress: deleteRemote},
		{Label: "Delete local and remote branch", Key: "b", Disabled: noUpstream, DisabledReason: reason, OnPress: func() {
			deleteRemote()
			deleteLocal()
		}},
		{Label: "Cancel"},
	}
	g.showMenu(fmt.Sprintf("Delete branch '%s'?", b.Name), items)
}

func (g *Gui) showRebaseBranchMenu(b *git.Branch) {
	cur := g.currentBranch
	base := g.baseBranchRef()
	items := []*MenuItem{
		{Label: fmt.Sprintf("Simple rebase onto '%s'", b.Name), Key: "s", Disabled: b.Head, DisabledReason: "Cannot rebase a branch onto itself", OnPress: func() {
			if err := g.gitRun("rebase", b.Name); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}},
		{Label: fmt.Sprintf("Interactive rebase onto '%s'", b.Name), Key: "i", Tooltip: "Begin an interactive rebase with a break at the start, so you can update the TODO commits before continuing.", Disabled: b.Head, DisabledReason: "Cannot rebase a branch onto itself", OnPress: func() {
			g.runSubprocess([]string{"git", "rebase", "-i", b.Name})
		}},
	}
	if base != "" {
		items = append(items, &MenuItem{Label: fmt.Sprintf("Rebase onto base branch (%s)", base), Key: "b", Tooltip: "Rebase the checked out branch onto its base branch (i.e. the closest main branch).", OnPress: func() {
			if err := g.gitRun("rebase", base); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}})
	}
	items = append(items, &MenuItem{Label: "Cancel"})
	g.showMenu(fmt.Sprintf("Rebase '%s'", cur), items)
}

func (g *Gui) canFastForward(from, to string) bool {
	_, err := g.repo.Run("merge-base", "--is-ancestor", from, to)
	return err == nil
}

func (g *Gui) showMergeMenu(b *git.Branch) {
	cur := g.currentBranch
	if b.Head {
		g.showErrorPopup("You cannot merge a branch into itself")
		return
	}
	canFF := g.canFastForward(cur, b.Name)
	run := func(args ...string) func() {
		return func() {
			if err := g.gitRun(args...); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}
	}
	items := []*MenuItem{
		{Label: "Regular merge (with merge commit)", Key: "m", Tooltip: fmt.Sprintf("Merge '%s' into '%s', creating a merge commit.", b.Name, cur), OnPress: run("merge", "--no-edit", "--no-ff", b.Name)},
		{Label: "Regular merge (fast-forward)", Key: "f", Tooltip: fmt.Sprintf("Fast-forward '%s' to '%s' without creating a merge commit.", cur, b.Name), Disabled: !canFF, DisabledReason: fmt.Sprintf("Cannot fast-forward '%s' to '%s'", cur, b.Name), OnPress: run("merge", "--ff-only", b.Name)},
		{Label: "Squash merge and leave uncommitted", Key: "s", Tooltip: fmt.Sprintf("Squash merge '%s' into the working tree.", b.Name), OnPress: run("merge", "--squash", b.Name)},
		{Label: "Squash merge and commit", Key: "S", Tooltip: fmt.Sprintf("Squash merge '%s' into '%s' as a single commit.", b.Name, cur), OnPress: func() {
			if err := g.gitRun("merge", "--squash", b.Name); err != nil {
				g.showErrorPopup(err.Error())
				return
			}
			msg := strings.ReplaceAll(strings.ReplaceAll(g.cfg.Git.Merging.SquashMergeMessage, "{{selectedRef}}", b.Name), "{{currentBranch}}", cur)
			if err := g.gitRun("commit", "-m", msg); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}},
		{Label: "Cancel"},
	}
	g.showMenu("Merge", items)
}

func (g *Gui) fastForwardBranch(b *git.Branch) {
	if b.Head {
		if err := g.gitRun("pull", "--ff-only"); err != nil {
			g.showErrorPopup(err.Error())
		}
	} else {
		parts := strings.SplitN(b.Upstream, "/", 2)
		if len(parts) == 2 {
			if err := g.gitRun("fetch", parts[0], fmt.Sprintf("%s:%s", parts[1], b.Name)); err != nil {
				g.showErrorPopup(err.Error())
			}
		}
	}
	g.refreshAll()
	g.updateMainView()
}

func (g *Gui) showUpstreamMenu(b *git.Branch) {
	base := g.baseBranchRef()
	items := []*MenuItem{
		{Label: "View divergence from upstream", Disabled: !b.HasUpstream, DisabledReason: "The selected branch has no upstream (or the upstream is not stored locally)", OnPress: func() {
			out, _ := g.repo.RunShell(fmt.Sprintf("git log --graph --color=always --abbrev-commit --decorate --date=relative --pretty=medium --left-right %s...%s --", b.Name, b.Upstream))
			g.setMainContent("Divergence from upstream", out, false)
		}},
	}
	if base != "" {
		items = append(items, &MenuItem{Label: fmt.Sprintf("View divergence from base branch (%s)", base), Key: "b", OnPress: func() {
			out, _ := g.repo.RunShell(fmt.Sprintf("git log --graph --color=always --abbrev-commit --decorate --date=relative --pretty=medium --left-right %s...%s --", b.Name, base))
			g.setMainContent("Divergence from base branch", out, false)
		}})
	}
	items = append(items,
		&MenuItem{Label: "Unset upstream of selected branch", Key: "u", Disabled: !b.HasUpstream, DisabledReason: "The selected branch has no upstream (or the upstream is not stored locally)", OnPress: func() {
			if err := g.gitRun("branch", "--unset-upstream", b.Name); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}},
		&MenuItem{Label: "Set upstream of selected branch", Key: "s", OnPress: func() {
			g.showPrompt("Enter upstream as '<remote> <branchname>'", "", func(text string) {
				parts := strings.Fields(text)
				if len(parts) != 2 {
					g.showErrorPopup("Upstream must be in the format '<remote> <branchname>'")
					return
				}
				if err := g.gitRun("branch", "--set-upstream-to="+parts[0]+"/"+parts[1], b.Name); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			})
		}},
	)
	if base != "" {
		items = append(items,
			&MenuItem{Label: fmt.Sprintf("Reset checked-out branch onto %s", base), Key: "g", Tooltip: fmt.Sprintf("View options for resetting the checked-out branch onto %s. Note: this will not reset the selected branch onto the upstream, it will reset the checked-out branch onto the upstream.", base), OnPress: func() {
				g.showResetMenuFor(base, base)
			}},
			&MenuItem{Label: fmt.Sprintf("Rebase checked-out branch onto %s", base), Key: "r", Tooltip: fmt.Sprintf("View options for rebasing the checked-out branch onto %s. Note: this will not rebase the selected branch onto the upstream, it will rebase the checked-out branch onto the upstream.", base), OnPress: func() {
				g.showRebaseBranchMenu(&git.Branch{Name: base})
			}},
		)
	} else if b.HasUpstream {
		items = append(items,
			&MenuItem{Label: fmt.Sprintf("Reset checked-out branch onto %s", b.Upstream), Key: "g", OnPress: func() {
				g.showResetMenuFor(b.Upstream, b.Upstream)
			}},
			&MenuItem{Label: fmt.Sprintf("Rebase checked-out branch onto %s", b.Upstream), Key: "r", OnPress: func() {
				g.showRebaseBranchMenu(&git.Branch{Name: b.Upstream})
			}},
		)
	}
	items = append(items, &MenuItem{Label: "Cancel"})
	g.showMenu("Upstream options", items)
}

func (g *Gui) showBranchSortMenu() {
	cur := g.cfg.Git.LocalBranchSortOrder
	radio := func(v string) string {
		if v == cur {
			return "(•)"
		}
		return "( )"
	}
	set := func(v string) func() {
		return func() {
			g.cfg.Git.LocalBranchSortOrder = v
			g.refreshAll()
			g.updateMainView()
		}
	}
	items := []*MenuItem{
		{Label: radio("recency") + " Recency", Key: "r", Command: "(based on reflog)", OnPress: set("recency")},
		{Label: radio("alphabetical") + " Alphabetical", Key: "a", Command: "--sort=refname", OnPress: set("alphabetical")},
		{Label: radio("date") + " Date", Key: "d", Command: "--sort=-committerdate", OnPress: set("date")},
		{Label: "    Cancel"},
	}
	g.showMenuWithPrompt("Sort order", "The default sort order for local branches can be set in the config file with the key 'git.localBranchSortOrder'.", items)
}

// ---------------------------------------------------------------------------
// commits

func shortHash(h string) string {
	if len(h) > 8 {
		return h[:8]
	}
	return h
}

func (g *Gui) handleCommitsKey(name string) bool {
	kb := &g.cfg.Keybinding
	c := g.selectedCommit()
	ctx := g.contexts["commits"]
	switch name {
	case kb.Universal.Select:
		if c == nil {
			return true
		}
		g.showCheckoutCommitMenu(c)
		return true
	case kb.Commits.RenameCommit:
		if c == nil {
			return true
		}
		if ctx.selected != 0 {
			g.showErrorPopup("Can only reword the head commit here")
			return true
		}
		g.openRewordPanel(c)
		return true
	case kb.Commits.RenameCommitWithEditor:
		if c == nil {
			return true
		}
		if ctx.selected == 0 {
			g.runSubprocess([]string{"git", "commit", "--allow-empty", "--amend", "--only"})
		}
		return true
	case kb.Commits.SquashDown:
		if c == nil {
			return true
		}
		if ctx.selected >= len(g.commits)-1 {
			g.showToast("Disabled: There's no commit below to squash into")
			return true
		}
		g.showConfirm("Squash", "Are you sure you want to squash the selected commit(s) into the commit below?", func() {
			g.squashDown(ctx.selected, false)
		}, nil)
		return true
	case kb.Commits.MarkCommitAsFixup:
		if c == nil {
			return true
		}
		if ctx.selected >= len(g.commits)-1 {
			g.showToast("Disabled: There's no commit below to squash into")
			return true
		}
		g.showMenu("Fixup", []*MenuItem{
			{Label: "Fixup", Key: "f", Tooltip: "Meld the selected commit into the commit below it. Similar to squash, but the selected commit's message will be discarded.", OnPress: func() { g.squashDown(ctx.selected, true) }},
			{Label: "Fixup and use this commit's message", Key: "c", OnPress: func() { g.squashDown(ctx.selected, true) }},
			{Label: "Cancel"},
		})
		return true
	case kb.Commits.RevertCommit:
		if c == nil {
			return true
		}
		g.showConfirm("Revert commit", fmt.Sprintf("Are you sure you want to revert %s?", shortHash(c.Hash)), func() {
			if err := g.gitRun("revert", "--no-edit", c.Hash); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Commits.TagCommit:
		if c == nil {
			return true
		}
		g.openTagPanel(c.Hash)
		return true
	case kb.Commits.ViewResetOptions:
		if c == nil {
			return true
		}
		g.showResetMenuFor(c.Hash, shortHash(c.Hash))
		return true
	case kb.Universal.Remove:
		if c == nil {
			return true
		}
		g.showConfirm("Drop commit", "Are you sure you want to drop the selected commit(s)?", func() {
			g.dropCommit(ctx.selected)
		}, nil)
		return true
	case kb.Commits.AmendToCommit:
		if c == nil {
			return true
		}
		if !g.anyStagedChanges() {
			g.showErrorPopup("There are no staged files to amend the commit with")
			return true
		}
		g.showConfirm("Amend commit", "Are you sure you want to amend this commit with your staged files?", func() {
			if ctx.selected == 0 {
				if err := g.gitRun("commit", "--amend", "--no-edit", "--allow-empty"); err != nil {
					g.showErrorPopup(err.Error())
				}
			} else {
				g.amendOlderCommit(ctx.selected)
			}
			g.refreshAll()
			g.updateMainView()
		}, nil)
		return true
	case kb.Commits.CopyCommitAttributeToClipboard:
		if c == nil {
			return true
		}
		g.showMenu("Copy to clipboard", []*MenuItem{
			{Label: "Commit hash"},
			{Label: "Commit subject", Key: "s"},
			{Label: "Commit message (subject and body)", Key: "m"},
			{Label: "Commit message body", Key: "b"},
			{Label: "Commit URL", Key: "u"},
			{Label: "Commit diff", Key: "d"},
			{Label: "Commit author", Key: "a"},
			{Label: "Commit tags", Key: "t"},
			{Label: "Cancel"},
		})
		return true
	case kb.Commits.OpenLogMenu:
		g.showMenu("Commit Log Options", []*MenuItem{
			{Label: "Toggle show whole git graph (pass the `--all` flag to `git log`)"},
			{Label: "Show git graph...", OnPress: func() {
				g.showMenu("Show git graph", []*MenuItem{
					{Label: "always", OnPress: func() { g.cfg.Git.Log.ShowGraph = "always" }},
					{Label: "never", OnPress: func() { g.cfg.Git.Log.ShowGraph = "never" }},
					{Label: "when maximised", OnPress: func() { g.cfg.Git.Log.ShowGraph = "when-maximised" }},
					{Label: "Cancel"},
				})
			}},
			{Label: "Commit sort order...", OnPress: func() {
				g.showMenu("Commit sort order", []*MenuItem{
					{Label: "topological (topo-order)", OnPress: func() { g.cfg.Git.Log.Order = "topo-order"; g.refreshCommits() }},
					{Label: "date-order", OnPress: func() { g.cfg.Git.Log.Order = "date-order"; g.refreshCommits() }},
					{Label: "author-date-order", OnPress: func() { g.cfg.Git.Log.Order = "author-date-order"; g.refreshCommits() }},
					{Label: "Cancel"},
				})
			}},
			{Label: "Cancel"},
		})
		return true
	case kb.Commits.ViewBisectOptions:
		if c == nil {
			return true
		}
		g.showMenu("Bisect", []*MenuItem{
			{Label: fmt.Sprintf("Mark %s as bad (start bisect)", shortHash(c.Hash)), Key: "b", OnPress: func() {
				g.gitRun("bisect", "start")
				g.gitRun("bisect", "bad", c.Hash)
				g.refreshAll()
				g.updateMainView()
			}},
			{Label: fmt.Sprintf("Mark %s as good (start bisect)", shortHash(c.Hash)), Key: "g", OnPress: func() {
				g.gitRun("bisect", "start")
				g.gitRun("bisect", "good", c.Hash)
				g.refreshAll()
				g.updateMainView()
			}},
			{Label: "Choose bisect terms", Key: "t"},
			{Label: "Cancel"},
		})
		return true
	case kb.Universal.New:
		if c == nil {
			return true
		}
		short := c.Hash
		if len(short) > 7 {
			short = short[:7]
		}
		g.promptNewBranch(c.Hash, short+" "+c.Subject)
		return true
	case kb.Commits.CherryPickCopy, kb.Commits.PasteCommits, kb.Commits.ResetCherryPick:
		return true
	case kb.Commits.StartInteractiveRebase, kb.Universal.Edit:
		if c == nil {
			return true
		}
		g.runSubprocess([]string{"git", "rebase", "-i", c.Hash + "^"})
		return true
	case kb.Universal.GoInto:
		return true
	}
	return false
}

func (g *Gui) showCheckoutCommitMenu(c *git.Commit) {
	items := []*MenuItem{
		{Label: fmt.Sprintf("Checkout commit %s as detached head", shortHash(c.Hash)), Key: "d", OnPress: func() {
			g.checkoutBranch(c.Hash)
		}},
	}
	// branches pointing at this commit
	n := 0
	for _, b := range g.branches {
		if b.Hash == c.Hash && !b.Head {
			n++
			branch := b
			items = append(items, &MenuItem{Label: "Checkout branch '" + branch.Name + "'", Key: fmt.Sprintf("%d", n), OnPress: func() {
				g.checkoutBranch(branch.Name)
			}})
		}
	}
	if n == 0 {
		items = append(items, &MenuItem{Label: "Checkout branch", Key: "1", Disabled: true, DisabledReason: "No branches point at this commit"})
	}
	items = append(items, &MenuItem{Label: "Cancel"})
	g.showMenu("Checkout branch or commit", items)
}

func (g *Gui) squashDown(idx int, fixup bool) {
	if idx != 0 {
		g.showErrorPopup("Squashing non-head commits is not supported")
		return
	}
	if idx+1 >= len(g.commits) {
		return
	}
	below := g.commits[idx+1]
	msg := below.Subject
	fullBelow, _ := g.repo.Run("log", "-1", "--format=%B", below.Hash)
	fullTop, _ := g.repo.Run("log", "-1", "--format=%B", g.commits[idx].Hash)
	if fixup {
		msg = strings.TrimRight(fullBelow, "\n")
	} else {
		msg = strings.TrimRight(fullBelow, "\n") + "\n\n" + strings.TrimRight(fullTop, "\n")
	}
	if err := g.gitRun("reset", "--soft", "HEAD~1"); err != nil {
		g.showErrorPopup(err.Error())
		return
	}
	if err := g.gitRun("commit", "--amend", "-m", msg); err != nil {
		g.showErrorPopup(err.Error())
	}
	g.refreshAll()
	g.updateMainView()
}

func (g *Gui) dropCommit(idx int) {
	if idx != 0 {
		g.showErrorPopup("Dropping non-head commits is not supported")
		return
	}
	if len(g.commits) == 1 {
		if err := g.gitRun("update-ref", "-d", "HEAD"); err != nil {
			g.showErrorPopup(err.Error())
		}
	} else if err := g.gitRun("reset", "--hard", "HEAD~1"); err != nil {
		g.showErrorPopup(err.Error())
	}
	g.refreshAll()
	g.updateMainView()
}

func (g *Gui) amendOlderCommit(idx int) {
	g.showErrorPopup("Amending older commits is not supported")
}
