package gui

import (
	"strings"

	"lazygit-clone/internal/term"
)

type searchState struct {
	active   bool // typing in the prompt
	text     string
	window   string
	filter   bool // filter mode (list is filtered) vs search mode (jump to matches)
	matches  []int
	matchIdx int
	// filter mode state
	filteredIdx []int
}

func (g *Gui) isFilterContext(ctx *ListContext) bool {
	if ctx == nil {
		return false
	}
	switch ctx.key {
	case "files", "commits", "status":
		return false
	}
	return true
}

func (g *Gui) startSearch() {
	ctx := g.currentContext()
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		g.searchState = &searchState{active: true, window: g.currentWindow}
		return
	}
	if ctx == nil {
		return
	}
	g.searchState = &searchState{active: true, window: g.currentWindow, filter: g.isFilterContext(ctx)}
}

func (g *Gui) handleSearchKey(name string, ev term.Event) {
	s := g.searchState
	switch name {
	case "<esc>":
		g.endSearch()
		return
	case "<enter>":
		s.active = false
		if s.text == "" {
			g.searchState = nil
			return
		}
		if s.filter {
			return
		}
		g.applySearch(true)
		return
	case "<backspace>":
		r := []rune(s.text)
		if len(r) > 0 {
			s.text = string(r[:len(r)-1])
		}
		if s.filter {
			g.applyFilter()
		}
		return
	case "<c-c>":
		g.Quit()
		return
	case "<c-u>":
		s.text = ""
		if s.filter {
			g.applyFilter()
		}
		return
	}
	if ev.Key == term.KeyRune && ev.Mod&term.ModAlt == 0 {
		s.text += string(ev.Rune)
		if s.filter {
			g.applyFilter()
		}
	}
}

// handleSearchModeKey handles keys while search results are being navigated.
func (g *Gui) handleSearchModeKey(name string) bool {
	s := g.searchState
	if s == nil || s.active {
		return false
	}
	switch name {
	case "<esc>":
		g.endSearch()
		return true
	}
	if !s.filter {
		switch name {
		case g.cfg.Keybinding.Universal.NextMatch:
			g.gotoMatch(1)
			return true
		case g.cfg.Keybinding.Universal.PrevMatch:
			g.gotoMatch(-1)
			return true
		}
	}
	return false
}

func (g *Gui) endSearch() {
	if g.searchState != nil && g.searchState.filter {
		// keep the selected item when exiting filter mode
		ctx := g.currentContext()
		sel := -1
		if ctx != nil && g.searchState.filteredIdx != nil && ctx.selected < len(g.searchState.filteredIdx) {
			sel = g.searchState.filteredIdx[ctx.selected]
		}
		g.searchState = nil
		if ctx != nil {
			if sel >= 0 {
				ctx.selected = sel
			}
			ctx.clampSelection()
			g.updateMainView()
		}
		return
	}
	g.searchState = nil
}

func (g *Gui) searchTargetLines() []Line {
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		return g.views[g.currentWindow].displayLines()
	}
	ctx := g.currentContext()
	if ctx == nil {
		return nil
	}
	return ctx.render()
}

func (g *Gui) applySearch(jumpToFirst bool) {
	s := g.searchState
	if s == nil {
		return
	}
	text := strings.ToLower(s.text)
	s.matches = nil
	for i, l := range g.searchTargetLines() {
		if strings.Contains(strings.ToLower(l.String()), text) {
			s.matches = append(s.matches, i)
		}
	}
	if len(s.matches) == 0 {
		return
	}
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		s.matchIdx = 0
		g.views[g.currentWindow].OriginY = s.matches[0]
		return
	}
	ctx := g.currentContext()
	// start from the first match at or after the current selection
	s.matchIdx = 0
	for i, m := range s.matches {
		if m >= ctx.selected {
			s.matchIdx = i
			break
		}
	}
	g.setSelection(ctx, s.matches[s.matchIdx])
}

func (g *Gui) gotoMatch(delta int) {
	s := g.searchState
	if s == nil || len(s.matches) == 0 {
		return
	}
	s.matchIdx = (s.matchIdx + delta + len(s.matches)) % len(s.matches)
	if g.currentWindow == "main" || g.currentWindow == "secondary" {
		g.views[g.currentWindow].OriginY = s.matches[s.matchIdx]
		return
	}
	ctx := g.currentContext()
	g.setSelection(ctx, s.matches[s.matchIdx])
}

// applyFilter recomputes the filtered indices for filter mode.
func (g *Gui) applyFilter() {
	s := g.searchState
	ctx := g.currentContext()
	if s == nil || ctx == nil {
		return
	}
	text := strings.ToLower(s.text)
	s.filteredIdx = nil
	if text == "" {
		s.filteredIdx = nil
		return
	}
	for i, l := range ctx.renderUnfiltered() {
		if strings.Contains(strings.ToLower(l.String()), text) {
			s.filteredIdx = append(s.filteredIdx, i)
		}
	}
	if ctx.selected >= len(s.filteredIdx) {
		ctx.selected = len(s.filteredIdx) - 1
	}
	if ctx.selected < 0 {
		ctx.selected = 0
	}
	g.updateMainView()
}

// filterActive reports whether ctx is currently filtered.
func (g *Gui) filterActive(ctx *ListContext) bool {
	return g.searchState != nil && g.searchState.filter && g.searchState.window == ctx.window && g.searchState.text != ""
}

func (g *Gui) drawSearchLine(width, y int) {
	s := g.searchState
	prefix := "Search: "
	if s.filter {
		prefix = "Filter: "
	}
	x := 0
	put := func(text string, st term.Style) {
		for _, r := range text {
			g.scr.Set(x, y, r, st)
			x += term.RuneWidth(r)
		}
	}
	if s.active {
		put(prefix, styleDefault)
		put(s.text, styleDefault)
		g.scr.ShowCursor(x, y)
		return
	}
	if s.filter {
		put(prefix+"matches for '"+s.text+"' ", styleDefault)
		put("<esc>: Exit filter mode", styleBlue)
		return
	}
	if len(s.matches) == 0 {
		put(prefix+"No matches for '"+s.text+"' ", styleDefault)
		put("<esc>: Exit search mode", styleBlue)
		return
	}
	put(prefix+"matches for '"+s.text+"' ("+itoa(s.matchIdx+1)+" of "+itoa(len(s.matches))+") ", styleDefault)
	put("n: Next match, N: Previous match, <esc>: Exit search mode", styleBlue)
}

// highlightMatches highlights occurrences of the search text in a line.
func highlightMatches(l Line, text string) Line {
	if text == "" {
		return l
	}
	lower := strings.ToLower(l.String())
	ltext := strings.ToLower(text)
	if !strings.Contains(lower, ltext) {
		return l
	}
	// flatten
	var cells []styledRune
	for _, sp := range l {
		for _, r := range sp.Text {
			cells = append(cells, styledRune{r, sp.Style})
		}
	}
	lowerRunes := []rune(lower)
	tRunes := []rune(ltext)
	matchStyle := term.DefaultStyle.WithFg(term.ColorBlack).WithBg(term.ColorCyan)
	for i := 0; i+len(tRunes) <= len(lowerRunes); i++ {
		ok := true
		for j, tr := range tRunes {
			if lowerRunes[i+j] != tr {
				ok = false
				break
			}
		}
		if ok {
			for j := range tRunes {
				if i+j < len(cells) {
					cells[i+j].st = matchStyle
				}
			}
			i += len(tRunes) - 1
		}
	}
	return cellsToLine(cells)
}

// keyEventFromName converts a key name like "<enter>" or "a" to an event.
func keyEventFromName(name string) term.Event {
	switch name {
	case "<enter>":
		return term.Event{Key: term.KeyEnter}
	case "<esc>":
		return term.Event{Key: term.KeyEsc}
	case "<space>":
		return term.Event{Key: term.KeyRune, Rune: ' '}
	case "<tab>":
		return term.Event{Key: term.KeyTab}
	case "<backtab>":
		return term.Event{Key: term.KeyBacktab}
	case "<up>":
		return term.Event{Key: term.KeyUp}
	case "<down>":
		return term.Event{Key: term.KeyDown}
	case "<left>":
		return term.Event{Key: term.KeyLeft}
	case "<right>":
		return term.Event{Key: term.KeyRight}
	case "<pgup>":
		return term.Event{Key: term.KeyPgUp}
	case "<pgdown>":
		return term.Event{Key: term.KeyPgDn}
	case "<home>":
		return term.Event{Key: term.KeyHome}
	case "<end>":
		return term.Event{Key: term.KeyEnd}
	}
	if strings.HasPrefix(name, "<c-") && strings.HasSuffix(name, ">") {
		r := []rune(strings.TrimSuffix(strings.TrimPrefix(name, "<c-"), ">"))
		if len(r) == 1 {
			return term.Event{Key: term.KeyCtrl, Rune: r[0]}
		}
	}
	r := []rune(name)
	if len(r) == 1 {
		return term.Event{Key: term.KeyRune, Rune: r[0]}
	}
	return term.Event{}
}

// handleMouse handles mouse events (clicks focus windows, wheel scrolls).
func (g *Gui) handleMouse(ev term.Event) {
	if !g.cfg.Gui.MouseEvents {
		return
	}
	if ev.MouseRelease {
		return
	}
	if len(g.popups) > 0 {
		p := g.popups[len(g.popups)-1]
		if p.kind == PopupMenu && p.view != nil {
			switch ev.MouseButton {
			case 4:
				p.moveSelection(-1)
			case 5:
				p.moveSelection(1)
			case 1:
				if ev.MouseX > p.view.X0 && ev.MouseX < p.view.X1 && ev.MouseY > p.view.Y0 && ev.MouseY < p.view.Y1 {
					idx := p.view.OriginY + ev.MouseY - p.view.Y0 - 1 - p.promptLineCount()
					if idx >= 0 && idx < len(p.rows) && !p.rows[idx].isHeader && !p.rows[idx].blank {
						if idx == p.selected {
							g.handleMenuKey(p, "<enter>", term.Event{})
						} else {
							p.selected = idx
						}
					}
				}
			}
		}
		return
	}
	for name, v := range g.views {
		if !v.Visible {
			continue
		}
		if ev.MouseX >= v.X0 && ev.MouseX <= v.X1 && ev.MouseY >= v.Y0 && ev.MouseY <= v.Y1 {
			switch ev.MouseButton {
			case 4:
				if name == "main" || name == "secondary" || name == "extras" {
					v.ScrollUp(g.cfg.Gui.ScrollHeight)
				} else if ctx := g.activeContextForWindow(name); ctx != nil {
					g.moveSelection(ctx, -1)
				}
			case 5:
				if name == "main" || name == "secondary" || name == "extras" {
					v.ScrollDown(g.cfg.Gui.ScrollHeight)
				} else if ctx := g.activeContextForWindow(name); ctx != nil {
					g.moveSelection(ctx, 1)
				}
			case 1:
				if name == "main" || name == "secondary" {
					g.focusMain()
					g.currentWindow = name
				} else if name == "extras" {
					g.previousSideWindow = g.currentSideWindow()
					g.currentWindow = "extras"
				} else {
					g.focusWindow(name)
					if ctx := g.activeContextForWindow(name); ctx != nil {
						idx := v.OriginY + ev.MouseY - v.Y0 - 1
						if idx >= 0 && idx < ctx.length() {
							g.setSelection(ctx, idx)
						}
					}
				}
			}
			return
		}
	}
}
