func init() {
	f, err := os.Open("/tmp/seedscan/out.txt")
	if err != nil {
		return
	}
	seeds := map[string][]uint64{}
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		parts := strings.Fields(line)
		if len(parts) < 3 {
			continue
		}
		name := parts[1]
		for _, p := range parts {
			if strings.HasPrefix(p, "seed=") {
				v, _ := strconv.ParseUint(strings.TrimPrefix(p, "seed="), 10, 64)
				seeds[parts[0]+" "+name] = append(seeds[parts[0]+" "+name], v)
			}
		}
	}
