		"adler32": func(s []byte) uint64 { return uint64(adler32.Checksum(s)) },
		"fnv32":   func(s []byte) uint64 { h := fnv.New32(); h.Write(s); return uint64(h.Sum32()) },
		"fnv32a":  func(s []byte) uint64 { h := fnv.New32a(); h.Write(s); return uint64(h.Sum32()) },
