		"md5le":   func(s []byte) uint64 { b := md5.Sum(s); return binary.LittleEndian.Uint64(b[:8]) },
		"md5be":   func(s []byte) uint64 { b := md5.Sum(s); return binary.BigEndian.Uint64(b[:8]) },
		"sha1le":  func(s []byte) uint64 { b := sha1.Sum(s); return binary.LittleEndian.Uint64(b[:8]) },
		"sha1be":  func(s []byte) uint64 { b := sha1.Sum(s); return binary.BigEndian.Uint64(b[:8]) },
		"djb2":    func(s []byte) uint64 { var h uint64 = 5381; for _, c := range s { h = h*33 + uint64(c) }; return h },
		"java":    func(s []byte) uint64 { var h int32; for _, c := range s { h = 31*h + int32(c) }; return uint64(uint32(h)) },
		"sum":     func(s []byte) uint64 { var t uint64; for _, c := range s { t += uint64(c) }; return t },
	}
	const m31 = 1<<31 - 1
	for key, list := range seeds {
		name := strings.Fields(key)[1]
		for hn, hf := range hashes {
			h := hf([]byte(name))
			cands := []uint64{h % m31, (h + 1) % m31, (h - 1) % m31, uint64(int64(h)%m31), (h % m31) + 1}
