package gui

import (
	"fmt"
	"strings"

	"lazygit-clone/internal/git"
)

// sub-views are contexts pushed on top of a window's tabs (e.g. the files of a
// commit, the commits of a branch, the branches of a remote).

func (g *Gui) pushSubview(window string, ctx *ListContext) {
	ctx.window = window
	ctx.isSubview = true
	g.subviews[window] = append(g.subviews[window], ctx)
	g.contexts[ctx.key] = ctx
	g.resetMainOrigin()
	g.updateMainView()
}

func (g *Gui) popSubview(window string) bool {
	stack := g.subviews[window]
	if len(stack) == 0 {
		return false
	}
	g.subviews[window] = stack[:len(stack)-1]
	g.resetMainOrigin()
	g.updateMainView()
	return true
}

// ---------------------------------------------------------------------------
// sub commits

type subCommitsState struct {
	ref     string
	commits []*git.Commit
}

func (g *Gui) openSubCommits(window string, ref string, title string) {
	commits, err := g.repo.Commits(ref, 300, g.cfg.Git.Log.Order, g.opts.FilterPath)
	if err != nil {
		g.showErrorPopup(err.Error())
		return
	}
	for _, c := range commits {
		switch {
		case g.unpushedSet[c.Hash]:
			c.Status = "unpushed"
		case g.unmergedSet[c.Hash]:
			c.Status = "pushed"
		default:
			c.Status = "merged"
		}
	}
	st := &subCommitsState{ref: ref, commits: commits}
	ctx := &ListContext{key: "subCommits:" + window, title: "Commits (" + title + ")", g: g, rangeStart: -1}
	ctx.getLen = func() int { return len(st.commits) }
	ctx.renderFn = func() []Line {
		sel := ""
		if g.currentWindow == window && ctx.selected < len(st.commits) && ctx.selected >= 0 {
			sel = st.commits[ctx.selected].Hash
		}
		return g.renderCommitList(st.commits, sel)
	}
	ctx.options = func() []string {
		return []string{"Checkout: <space>", "Reset: g", "Copy (cherry-pick): C", "Exit subview: <esc>", "Keybindings: ?"}
	}
	ctx.updateMain = func() {
		if ctx.selected < 0 || ctx.selected >= len(st.commits) {
			g.setMainContent("Commit", "No commits for this branch", false)
			return
		}
		g.setMainContent("Commit", g.showCommand(st.commits[ctx.selected].Hash), false)
	}
	ctx.handleKey = func(name string) bool {
		kb := &g.cfg.Keybinding
		if ctx.selected < 0 || ctx.selected >= len(st.commits) {
			return false
		}
		c := st.commits[ctx.selected]
		switch name {
		case kb.Universal.GoInto:
			short := c.Hash
			if len(short) > 7 {
				short = short[:7]
			}
			g.openCommitFiles(window, c.Hash, fmt.Sprintf("Diff files (%s %s)", short, c.Subject), false)
			return true
		case kb.Universal.Select:
			g.showCheckoutCommitMenu(c)
			return true
		case kb.Commits.ViewResetOptions:
			g.showResetMenuFor(c.Hash, c.Hash)
			return true
		case kb.Universal.New:
			short := c.Hash
			if len(short) > 7 {
				short = short[:7]
			}
			g.promptNewBranch(c.Hash, short+" "+c.Subject)
			return true
		case kb.Commits.CopyCommitAttributeToClipboard:
			g.showMenu("Copy to clipboard", []*MenuItem{
				{Label: "Commit hash"},
				{Label: "Commit subject", Key: "s"},
				{Label: "Commit message (subject and body)", Key: "m"},
				{Label: "Commit message body", Key: "b"},
				{Label: "Commit URL", Key: "u"},
				{Label: "Commit diff", Key: "d"},
				{Label: "Commit author", Key: "a"},
				{Label: "Commit tags", Key: "t"},
				{Label: "Cancel"},
			})
			return true
		}
		return false
	}
	g.pushSubview(window, ctx)
}

// renderCommitList renders a list of commits with the graph.
func (g *Gui) renderCommitList(commits []*git.Commit, selectedHash string) []Line {
	var graphLines []Line
	if g.cfg.Git.Log.ShowGraph != "never" {
		graphLines = renderCommitGraph(commits, selectedHash, g.commitAuthorStyle)
	}
	lines := make([]Line, len(commits))
	hashLen := g.cfg.Gui.CommitHashLength
	for i, c := range commits {
		var l Line
		hash := c.Hash
		if len(hash) > hashLen {
			hash = hash[:hashLen]
		}
		hashStyle := styleGreen
		switch c.Status {
		case "unpushed":
			hashStyle = styleRed
		case "pushed":
			hashStyle = styleYellow
		}
		l = append(l, Span{Text: hash, Style: hashStyle})
		l = append(l, Span{Text: " ", Style: styleDefault})
		author := padToWidth(authorInitials(c.AuthorName, g.cfg.Gui.CommitAuthorShortLength), g.cfg.Gui.CommitAuthorShortLength)
		l = append(l, Span{Text: author, Style: g.commitAuthorStyle(c)})
		l = append(l, Span{Text: " ", Style: styleDefault})
		if graphLines != nil {
			l = append(l, graphLines[i]...)
			l = append(l, Span{Text: " ", Style: styleDefault})
		}
		for _, t := range c.Tags {
			l = append(l, Span{Text: t, Style: styleMagenta.Bold()})
			l = append(l, Span{Text: " ", Style: styleDefault})
		}
		l = append(l, Span{Text: c.Subject, Style: styleDefault})
		lines[i] = l
	}
	return lines
}

// ---------------------------------------------------------------------------
// commit files

type commitFile struct {
	name   string
	status string // single letter
}

type commitFilesState struct {
	ref       string
	isStash   bool
	files     []*commitFile
	tree      *FileNode
	nodes     []*FileNode
	collapsed map[string]bool
}

func (g *Gui) loadCommitFiles(ref string, isStash bool) []*commitFile {
	var out string
	if isStash {
		out, _ = g.repo.Run("stash", "show", "--name-status", "--no-renames", "--format=", ref)
	} else {
		out, _ = g.repo.Run("show", "--no-ext-diff", "--name-status", "--no-renames", "--format=", ref, "--")
	}
	var files []*commitFile
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "\t", 2)
		if len(parts) != 2 {
			continue
		}
		files = append(files, &commitFile{name: parts[1], status: parts[0][:1]})
	}
	return files
}

func (st *commitFilesState) rebuild(showRoot bool, flat bool) {
	gitFiles := make([]*git.File, len(st.files))
	for i, f := range st.files {
		gitFiles[i] = &git.File{Name: f.name, ShortStatus: f.status, Tracked: true}
	}
	st.tree = BuildFileTree(gitFiles, showRoot, flat)
	st.nodes = st.tree.Flatten(st.collapsed, showRoot && !flat)
}

func renderCommitFileNode(node *FileNode, collapsed bool) Line {
	indent := strings.Repeat("  ", node.Depth)
	if node.IsDir() {
		icon := "▼"
		if collapsed {
			icon = "▶"
		}
		return Line{{Text: indent, Style: styleDefault}, {Text: icon, Style: styleDefault}, {Text: " " + node.Name, Style: styleDefault}}
	}
	status := node.File.ShortStatus
	st := styleDefault
	switch status {
	case "A":
		st = styleGreen
	case "D":
		st = styleRed
	case "M":
		st = styleYellow
	case "R":
		st = styleYellow
	}
	return Line{{Text: indent, Style: styleDefault}, {Text: status, Style: st}, {Text: " " + node.Name, Style: styleDefault}}
}

func (g *Gui) openCommitFiles(window string, ref string, title string, isStash bool) {
	st := &commitFilesState{ref: ref, isStash: isStash, collapsed: map[string]bool{}}
	st.files = g.loadCommitFiles(ref, isStash)
	st.rebuild(g.showRootItem, g.flatFileTree)
	ctx := &ListContext{key: "commitFiles:" + window, title: title, g: g, rangeStart: -1}
	ctx.getLen = func() int { return len(st.nodes) }
	ctx.renderFn = func() []Line {
		lines := make([]Line, len(st.nodes))
		for i, n := range st.nodes {
			lines[i] = renderCommitFileNode(n, st.collapsed[n.Path])
		}
		return lines
	}
	ctx.options = func() []string {
		opts := []string{"Checkout: c", "Remove: d"}
		if ctx.selected >= 0 && ctx.selected < len(st.nodes) && !st.nodes[ctx.selected].IsDir() {
			opts = append(opts, "Edit: e")
		}
		return append(opts, "Toggle file included in patch: <space>", "Exit subview: <esc>", "Keybindings: ?")
	}
	ctx.updateMain = func() {
		if ctx.selected < 0 || ctx.selected >= len(st.nodes) {
			g.setMainContent("Patch", "", false)
			return
		}
		node := st.nodes[ctx.selected]
		path := node.Path
		if path == "" {
			path = "."
		}
		var out string
		if isStash {
			out, _ = g.repo.Run("-C", g.repo.WorkTree, "stash", "show", "-p", "--no-ext-diff", "--color=always", fmt.Sprintf("--unified=%d", g.diffContextSize), ref, "--", path)
		} else {
			out, _ = g.repo.Run("-C", g.repo.WorkTree, "show", "--no-ext-diff", "--submodule", "--color=always", fmt.Sprintf("--unified=%d", g.diffContextSize), "--format=", ref, fmt.Sprintf("--find-renames=%d%%", g.renameThreshold), "--", path)
		}
		g.setMainContent("Patch", out, false)
	}
	ctx.handleKey = func(name string) bool {
		kb := &g.cfg.Keybinding
		if ctx.selected < 0 || ctx.selected >= len(st.nodes) {
			return false
		}
		node := st.nodes[ctx.selected]
		switch name {
		case kb.Universal.GoInto:
			if node.IsDir() {
				st.collapsed[node.Path] = !st.collapsed[node.Path]
				st.rebuild(g.showRootItem, g.flatFileTree)
				ctx.clampSelection()
				ctx.updateMain()
			}
			return true
		case kb.CommitFiles.CheckoutCommitFile:
			g.showConfirm("Checkout file", fmt.Sprintf("Are you sure you want to checkout this file?"), func() {
				for _, f := range node.Files() {
					g.gitAction("Checkout file", "checkout", ref, "--", f.Name)
				}
				g.refreshAll()
				g.updateMainView()
			}, nil)
			return true
		case kb.Files.ToggleTreeView:
			g.flatFileTree = !g.flatFileTree
			st.rebuild(g.showRootItem, g.flatFileTree)
			ctx.clampSelection()
			ctx.updateMain()
			return true
		case kb.Files.CollapseAll:
			for _, n := range st.tree.allDirs() {
				st.collapsed[n.Path] = true
			}
			st.rebuild(g.showRootItem, g.flatFileTree)
			ctx.clampSelection()
			return true
		case kb.Files.ExpandAll:
			st.collapsed = map[string]bool{}
			st.rebuild(g.showRootItem, g.flatFileTree)
			return true
		case kb.Universal.Select, kb.Universal.Remove, kb.Universal.Edit, kb.Universal.OpenFile:
			return true
		}
		return false
	}
	g.pushSubview(window, ctx)
}

// ---------------------------------------------------------------------------
// remote branches

func (g *Gui) openRemoteBranches(remote *git.Remote) {
	window := "branches"
	ctx := &ListContext{key: "remoteBranches", title: "Remote branches (" + remote.Name + ")", g: g, rangeStart: -1}
	ctx.getLen = func() int { return len(remote.Branches) }
	ctx.renderFn = func() []Line {
		lines := make([]Line, len(remote.Branches))
		for i, b := range remote.Branches {
			lines[i] = plain(b)
		}
		return lines
	}
	ctx.options = func() []string {
		return []string{"Checkout: <space>", "Merge: M", "Rebase: r", "Delete: d", "Set as upstream: u", "Exit subview: <esc>", "Keybindings: ?"}
	}
	ctx.updateMain = func() {
		if ctx.selected < 0 || ctx.selected >= len(remote.Branches) {
			g.setMainContent("Remote Branch", "No branches for this remote", false)
			return
		}
		ref := "refs/remotes/" + remote.Name + "/" + remote.Branches[ctx.selected]
		cmd := strings.ReplaceAll(g.cfg.Git.BranchLogCmd, "{{branchName}}", ref)
		out, _ := g.repo.RunShell(cmd)
		g.setMainContent("Remote Branch", out, false)
	}
	ctx.handleKey = func(name string) bool {
		kb := &g.cfg.Keybinding
		if ctx.selected < 0 || ctx.selected >= len(remote.Branches) {
			return false
		}
		full := remote.Name + "/" + remote.Branches[ctx.selected]
		switch name {
		case kb.Universal.GoInto:
			g.openSubCommits(window, full, full)
			return true
		case kb.Universal.Select:
			g.showMenu("Checkout "+full, []*MenuItem{
				{Label: "Checkout a new branch tracking " + full, Key: "n", OnPress: func() {
					if err := g.gitAction("Checkout branch", "checkout", "--track", full); err != nil {
						g.showErrorPopup(err.Error())
					}
					g.refreshAll()
					g.updateMainView()
				}},
				{Label: "Checkout " + full + " as detached head", Key: "d", OnPress: func() { g.checkoutBranch(full) }},
				{Label: "Cancel"},
			})
			return true
		case kb.Branches.MergeIntoCurrentBranch:
			g.showMergeMenu(&git.Branch{Name: full})
			return true
		case kb.Branches.RebaseBranch:
			g.showRebaseBranchMenu(&git.Branch{Name: full})
			return true
		case kb.Universal.Remove:
			g.showConfirm("Delete branch '"+full+"'?", fmt.Sprintf("Are you sure you want to delete the remote branch '%s' from '%s'?", remote.Branches[ctx.selected], remote.Name), func() {
				if err := g.gitAction("Delete remote branch", "push", remote.Name, "--delete", remote.Branches[ctx.selected]); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.popSubview(window)
			}, nil)
			return true
		case kb.Branches.SetUpstream:
			g.showConfirm("Set upstream branch", fmt.Sprintf("Are you sure you want to set the upstream branch of '%s' to '%s'", g.currentBranch, full), func() {
				if err := g.gitAction("Set upstream", "branch", "--set-upstream-to="+full, g.currentBranch); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			}, nil)
			return true
		case kb.Commits.ViewResetOptions:
			g.showResetMenuFor(full, full)
			return true
		}
		return false
	}
	g.pushSubview(window, ctx)
}
