// renderCommitsWithTodos renders the commits panel during a rebase.
func (g *Gui) renderCommitsWithTodos(selectedHash string) []Line {
	var lines []Line
	lines = append(lines, plain("--- Pending rebase todos ---"))
	hashLen := g.cfg.Gui.CommitHashLength
