type rebaseTodo struct {
	action  string
	hash    string
	subject string
	author  string
	conflict bool
}

// loadRebaseTodos reads the pending rebase todo entries.
func (g *Gui) loadRebaseTodos() {
	dir := filepath.Join(g.repo.GitDir, "rebase-merge")
	data, err := os.ReadFile(filepath.Join(dir, "git-rebase-todo"))
	var todos []rebaseTodo
	if err == nil {
		for _, line := range strings.Split(string(data), "\\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			parts := strings.SplitN(line, " ", 3)
			if len(parts) < 2 {
				continue
			}
			t := rebaseTodo{action: parts[0], hash: parts[1]}
			if len(parts) == 3 {
				t.subject = parts[2]
			}
			todos = append(todos, t)
		}
	}
	// reverse: the next todo to be applied is shown last
	for i, j := 0, len(todos)-1; i < j; i, j = i+1, j-1 {
		todos[i], todos[j] = todos[j], todos[i]
	}
	if data, err := os.ReadFile(filepath.Join(dir, "stopped-sha")); err == nil {
		hash := strings.TrimSpace(string(data))
		if hash != "" {
			g.rebaseConflictHash = hash
			subject := ""
			if out, err := g.repo.Run("log", "-1", "--format=%s", hash); err == nil {
				subject = strings.TrimSpace(out)
			}
			if done, err := os.ReadFile(filepath.Join(dir, "done")); err == nil {
				lines := strings.Split(strings.TrimSpace(string(done)), "\\n")
				if len(lines) > 0 {
					parts := strings.SplitN(lines[len(lines)-1], " ", 3)
					if len(parts) >= 2 {
						todos = append(todos, rebaseTodo{action: parts[0], hash: parts[1], subject: subject, conflict: true})
					}
				}
			}
		}
	}
	for i := range todos {
		if out, err := g.repo.Run("log", "-1", "--format=%aN", todos[i].hash); err == nil {
			todos[i].author = strings.TrimSpace(out)
		}
	}
	g.rebaseTodos = todos
}
