cat_conf = '''package gui

import (
	"os"
	"path/filepath"
	"strings"
)

// conflict describes a merge conflict block within a file.
type conflict struct {
	start  int // index of "<<<<<<<" line
	middle int // index of "=======" line
	end    int // index of ">>>>>>>" line
}

func findConflicts(lines []string) []conflict {
	var out []conflict
	var cur *conflict
	for i, l := range lines {
		switch {
		case strings.HasPrefix(l, "<<<<<<< "):
			cur = &conflict{start: i, middle: -1, end: -1}
		case l == "=======" && cur != nil:
			cur.middle = i
		case strings.HasPrefix(l, ">>>>>>> ") && cur != nil:
			cur.end = i
			if cur.middle >= 0 {
				out = append(out, *cur)
			}
			cur = nil
		}
	}
	return out
}

func (g *Gui) conflictFileLines() ([]string, string) {
	node := g.selectedFileNode()
	if node == nil || node.IsDir() || node.File == nil || !node.File.HasMergeConflicts {
		return nil, ""
	}
	path := filepath.Join(g.repo.WorkTree, node.File.Name)
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, ""
	}
	return strings.Split(strings.TrimRight(string(data), "\\n"), "\\n"), node.File.Name
}

// conflictSelection returns the line range of the selected conflict section.
func (g *Gui) conflictSelection() (int, int, bool) {
	lines, _ := g.conflictFileLines()
	conflicts := findConflicts(lines)
	if len(conflicts) == 0 {
		return 0, 0, false
	}
	if g.conflictIdx >= len(conflicts) {
		g.conflictIdx = len(conflicts) - 1
	}
	if g.conflictIdx < 0 {
		g.conflictIdx = 0
	}
	c := conflicts[g.conflictIdx]
	if g.conflictSection == 0 {
		return c.start, c.middle, true
	}
	return c.middle, c.end, true
}

// handleConflictKey handles keys in the merge conflicts view.
func (g *Gui) handleConflictKey(name string) bool {
	kb := &g.cfg.Keybinding
	lines, file := g.conflictFileLines()
	conflicts := findConflicts(lines)
	switch name {
	case kb.Universal.PrevItem, kb.Universal.PrevItemAlt:
		if g.conflictSection > 0 {
			g.conflictSection--
		}
		return true
	case kb.Universal.NextItem, kb.Universal.NextItemAlt:
		if g.conflictSection < 1 {
			g.conflictSection++
		}
		return true
	case kb.Universal.PrevBlock, kb.Universal.PrevBlockAlt:
		if g.conflictIdx > 0 {
			g.conflictIdx--
		}
		return true
	case kb.Universal.NextBlock, kb.Universal.NextBlockAlt:
		if g.conflictIdx < len(conflicts)-1 {
			g.conflictIdx++
		}
		return true
	case kb.Universal.Select, kb.Main.PickBothHunks:
		if len(conflicts) == 0 || file == "" {
			return true
		}
		c := conflicts[g.conflictIdx]
		var out []string
		out = append(out, lines[:c.start]...)
		if name == kb.Main.PickBothHunks {
			out = append(out, lines[c.start+1:c.middle]...)
			out = append(out, lines[c.middle+1:c.end]...)
		} else if g.conflictSection == 0 {
			out = append(out, lines[c.start+1:c.middle]...)
		} else {
			out = append(out, lines[c.middle+1:c.end]...)
		}
		out = append(out, lines[c.end+1:]...)
		_ = os.WriteFile(filepath.Join(g.repo.WorkTree, file), []byte(strings.Join(out, "\\n")+"\\n"), 0o644)
		if len(findConflicts(out)) == 0 && g.cfg.Git.AutoStageResolvedConflicts {
			g.logAction("Stage files whose merge conflicts were resolved")
			g.gitRun("add", "--", file)
			g.refreshAll()
			g.currentWindow = g.previousSideWindow
			g.updateMainView()
			return true
		}
		g.conflictSection = 0
		g.refreshAll()
		g.updateMainView()
		return true
	case kb.Files.OpenMergeOptions:
		g.showMergeConflictOptionsMenu(g.selectedFileNode())
		return true
	}
	return false
}
