package main

import (
	"fmt"
	"math/rand"
	"os"
	"runtime"
	"sync"

	"github.com/lucasb-eyer/go-colorful"
)

type target struct {
	name    string
	r, g, b uint8
}

var targets = []target{{"A", 10, 245, 20}, {"am", 250, 254, 30}, {"aa", 206, 38, 48}, {"Bob", 161, 225, 26}, {"zed", 252, 45, 32}}

func rgbOf(r1, r2, r3 float64) (uint8, uint8, uint8) {
	c := colorful.Hsl(r1*360.0, 0.6+0.4*r2, 0.4+r3*0.2)
	return uint8(c.R * 255), uint8(c.G * 255), uint8(c.B * 255)
}

func f64(src rand.Source64) float64 {
	return float64(src.Int63()&(1<<53-1)) / (1 << 53)
}

func first(seed int64) float64 {
	src := rand.NewSource(seed).(rand.Source64)
	return f64(src)
}

func main() {
	n := runtime.NumCPU()
	var wg sync.WaitGroup
	const m = int64(1<<31 - 1)
	chunk := m / int64(n)
	for w := 0; w < n; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			start := int64(w) * chunk
			end := start + chunk + 2
			if end > m {
				end = m
			}
			src := rand.NewSource(0).(rand.Source64)
			f := func(seed int64) float64 {
				src.Seed(seed)
				return f64(src)
			}
			a, b := f(start), f(start+1)
			for seed := start; seed+2 < end; seed++ {
				c := f(seed + 2)
				r, g, bb := rgbOf(a, b, c)
				for _, t := range targets {
					if r == t.r && g == t.g && bb == t.b {
						fmt.Printf("SEED3 %s seed=%d\n", t.name, seed)
						os.Stdout.Sync()
					}
				}
				a, b = b, c
			}
		}(w)
	}
	wg.Wait()
	fmt.Println("DONE")
}
EOF
