{"command":"cat > /workspace/internal/gui/staging.go <<'EOF'
package gui

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	"lazygit-clone/internal/term"
)

// stagingState holds the state of the line/hunk staging view.
type stagingState struct {
	file      string
	staged    bool // true when viewing the staged changes
	lines     []Line
	rawLines  []string
	hunkMode  bool
	selected  int // selected line index (line mode) or block index (hunk mode)
	blocks    [][2]int // change blocks [start,end] (inclusive) in hunk mode
	hunkStart []int    // indices of hunk headers
}

const hunkStagingHint = "Hunk selection mode is now the default for staging. If you want to stage individual lines, press 'a' to switch to line-by-line mode.\n\nIf you prefer to use line-by-line mode by default (like in earlier lazygit versions), add\n\ngui:\n  useHunkModeInStagingView: false\n\nto your config file."

func normaliseHunkHeader(line string) string {
	// lazygit renders hunk headers with explicit counts: "@@ -1 +1,2 @@" -> "@@ -1,1 +1,2 @@"
	plain := Decolorise(line)
	if !strings.HasPrefix(plain, "@@ ") {
		return line
	}
	parts := strings.SplitN(plain, " ", 4)
	if len(parts) < 4 {
		return line
	}
	fix := func(r string) string {
		if !strings.Contains(r, ",") {
			return r + ",1"
		}
		return r
	}
	return "\x1b[36m@@ " + fix(parts[1]) + " " + fix(parts[2]) + " @@" + strings.TrimPrefix(parts[3], "@@") + "\x1b[39m"
}

func (g *Gui) buildStagingState(file string, staged bool) *stagingState {
	st := &stagingState{file: file, staged: staged, hunkMode: g.cfg.Gui.UseHunkModeInStagingView}
	var diff string
	node := g.selectedFileNode()
	if node != nil && node.File != nil && !node.File.Tracked {
		diff = g.workTreeDiff(file, false, true)
	} else {
		diff = g.workTreeDiff(file, staged, false)
	}
	raw := strings.Split(strings.TrimRight(diff, "\n"), "\n")
	st.rawLines = raw
	for i, l := range raw {
		plain := Decolorise(l)
		if strings.HasPrefix(plain, "@@") {
			st.hunkStart = append(st.hunkStart, i)
			st.lines = append(st.lines, ParseANSI(normaliseHunkHeader(l)))
			continue
		}
		st.lines = append(st.lines, ParseANSI(l))
	}
	// change blocks
	inBlock := false
	start := 0
	for i, l := range raw {
		plain := Decolorise(l)
		isChange := len(st.hunkStart) > 0 && i > st.hunkStart[0] && (strings.HasPrefix(plain, "+") || strings.HasPrefix(plain, "-")) && !strings.HasPrefix(plain, "+++") && !strings.HasPrefix(plain, "---")
		if isChange && !inBlock {
			inBlock = true
			start = i
		}
		if !isChange && inBlock {
			st.blocks = append(st.blocks, [2]int{start, i - 1})
			inBlock = false
		}
	}
	if inBlock {
		st.blocks = append(st.blocks, [2]int{start, len(raw) - 1})
	}
	if st.hunkMode {
		st.selected = 0
	} else {
		if len(st.blocks) > 0 {
			st.selected = st.blocks[0][0]
		} else if len(st.hunkStart) > 0 {
			st.selected = st.hunkStart[0] + 1
		}
	}
	return st
}

func (st *stagingState) selection() (int, int) {
	if st.hunkMode {
		if len(st.blocks) == 0 {
			return -1, -1
		}
		if st.selected >= len(st.blocks) {
			st.selected = len(st.blocks) - 1
		}
		if st.selected < 0 {
			st.selected = 0
		}
		b := st.blocks[st.selected]
		return b[0], b[1]
	}
	return st.selected, st.selected
}

func (g *Gui) enterStagingView(node *FileNode) {
	if node == nil || node.IsDir() {
		return
	}
	f := node.File
	if f.HasMergeConflicts {
		g.conflictIdx = 0
		g.conflictSection = 0
		g.focusMain()
		return
	}
	staged := f.HasStagedChanges && !f.HasUnstagedChanges
	g.staging = g.buildStagingState(f.Name, staged)
	g.focusMain()
	g.currentWindow = "main"
	if f.HasStagedChanges && f.HasUnstagedChanges {
		g.staging.staged = false
	}
	if !g.state.DidShowHunkStagingHint && g.cfg.Gui.UseHunkModeInStagingView {
		g.state.DidShowHunkStagingHint = true
		g.state.Save()
		g.showAlert("", hunkStagingHint)
	}
}

func (g *Gui) exitStagingView() {
	g.staging = nil
	g.currentWindow = g.previousSideWindow
	g.updateMainView()
}

func (g *Gui) stagingOptions() []string {
	mode := "Select line-by-line: a"
	if !g.staging.hunkMode {
		mode = "Select hunks: a"
	}
	return []string{mode, "Stage: <space>", "Discard: d", "Return to files panel: <esc>", "Switch view: <tab>", "Keybindings: ?"}
}

func (g *Gui) handleStagingKey(name string, ev term.Event) bool {
	st := g.staging
	kb := &g.cfg.Keybinding
	v := g.views["main"]
	switch name {
	case kb.Universal.Return:
		g.exitStagingView()
		return true
	case kb.Main.ToggleSelectHunk:
		if st.hunkMode {
			// switch to line mode, selecting the first line of the block
			lo, _ := st.selection()
			st.hunkMode = false
			if lo >= 0 {
				st.selected = lo
			}
		} else {
			st.hunkMode = true
			idx := 0
			for i, b := range st.blocks {
				if st.selected >= b[0] {
					idx = i
				}
			}
			st.selected = idx
		}
		return true
	case kb.Universal.PrevItem, kb.Universal.PrevItemAlt:
		if st.selected > 0 {
			st.selected--
		}
		if !st.hunkMode && len(st.hunkStart) > 0 && st.selected <= st.hunkStart[0] {
			st.selected = st.hunkStart[0] + 1
		}
		g.ensureStagingVisible()
		return true
	case kb.Universal.NextItem, kb.Universal.NextItemAlt:
		max := len(st.rawLines) - 1
		if st.hunkMode {
			max = len(st.blocks) - 1
		}
		if st.selected < max {
			st.selected++
		}
		g.ensureStagingVisible()
		return true
	case kb.Universal.PrevBlock, kb.Universal.PrevBlockAlt:
		if st.hunkMode {
			if st.selected > 0 {
				st.selected--
			}
		} else {
			for i := len(st.blocks) - 1; i >= 0; i-- {
				if st.blocks[i][0] < st.selected {
					st.selected = st.blocks[i][0]
					break
				}
			}
		}
		g.ensureStagingVisible()
		return true
	case kb.Universal.NextBlock, kb.Universal.NextBlockAlt:
		if st.hunkMode {
			if st.selected < len(st.blocks)-1 {
				st.selected++
			}
		} else {
			for _, b := range st.blocks {
				if b[0] > st.selected {
					st.selected = b[0]
					break
				}
			}
		}
		g.ensureStagingVisible()
		return true
	case kb.Universal.GotoTop, kb.Universal.GotoTopAlt:
		st.selected = 0
		if !st.hunkMode && len(st.hunkStart) > 0 {
			st.selected = st.hunkStart[0] + 1
		}
		v.OriginY = 0
		return true
	case kb.Universal.GotoBottom, kb.Universal.GotoBottomAlt:
		if st.hunkMode {
			st.selected = len(st.blocks) - 1
		} else {
			st.selected = len(st.rawLines) - 1
		}
		g.ensureStagingVisible()
		return true
	case kb.Universal.Select:
		g.applyStagingSelection(false)
		return true
	case kb.Universal.Remove:
		if st.staged {
			g.applyStagingSelection(false)
			return true
		}
		g.showConfirm("Discard change", "Are you sure you want to discard this change (git reset)?", func() {
			g.applyStagingSelection(true)
		}, nil)
		return true
	case kb.Universal.TogglePanel, kb.Universal.NextBlockAlt2:
		if g.mainSplit {
			g.staging = g.buildStagingState(st.file, !st.staged)
		}
		return true
	case kb.Files.CommitChanges:
		g.commitChanges(false)
		return true
	case kb.Files.CommitChangesWithoutHook:
		g.commitChanges(true)
		return true
	}
	return false
}

func (g *Gui) ensureStagingVisible() {
	st := g.staging
	v := g.views["main"]
	lo, hi := st.selection()
	if lo < 0 {
		return
	}
	h := v.InnerHeight()
	if h <= 0 {
		return
	}
	if lo < v.OriginY {
		v.OriginY = lo
	}
	if hi >= v.OriginY+h {
		v.OriginY = hi - h + 1
	}
	if v.OriginY < 0 {
		v.OriginY = 0
	}
}

// buildPatch builds a patch containing only the selected lines.
func (st *stagingState) buildPatch(reverse bool) string {
	lo, hi := st.selection()
	if lo < 0 {
		return ""
	}
	var header []string
	var hunks [][]string
	var cur []string
	for i, l := range st.rawLines {
		plain := Decolorise(l)
		if strings.HasPrefix(plain, "@@") {
			if cur != nil {
				hunks = append(hunks, cur)
			}
			cur = []string{plain}
			continue
		}
		if cur == nil {
			header = append(header, plain)
			continue
		}
		cur = append(cur, plain)
		_ = i
	}
	if cur != nil {
		hunks = append(hunks, cur)
	}
	// find hunk containing the selection and keep only selected changes
	idx := 0
	for i, l := range st.rawLines {
		if strings.HasPrefix(Decolorise(l), "@@") {
			if i <= lo {
				idx = len(filterHunkStarts(st.hunkStart, i))
			}
		}
	}
	_ = idx
	var out []string
	out = append(out, header...)
	lineNo := 0
	for i, l := range st.rawLines {
		plain := Decolorise(l)
		if strings.HasPrefix(plain, "@@") {
			lineNo = i
			break
		}
	}
	_ = lineNo
	// walk hunks with absolute indices
	hStartIdx := st.hunkStart
	for h, start := range hStartIdx {
		end := len(st.rawLines)
		if h+1 < len(hStartIdx) {
			end = hStartIdx[h+1]
		}
		if hi < start || lo >= end {
			continue
		}
		header := Decolorise(st.rawLines[start])
		var body []string
		oldCount, newCount := 0, 0
		for i := start + 1; i < end; i++ {
			plain := Decolorise(st.rawLines[i])
			if plain == "" {
				continue
			}
			selected := i >= lo && i <= hi
			switch plain[0] {
			case '+':
				if selected {
					body = append(body, plain)
					newCount++
				}
			case '-':
				if selected {
					body = append(body, plain)
					oldCount++
				} else {
					body = append(body, " "+plain[1:])
					oldCount++
					newCount++
				}
			case '\\':
				body = append(body, plain)
			default:
				body = append(body, plain)
				oldCount++
				newCount++
			}
		}
		oldStart, newStart := parseHunkStarts(header)
		out = append(out, fmt.Sprintf("@@ -%d,%d +%d,%d @@", oldStart, oldCount, newStart, newCount))
		out = append(out, body...)
	}
	return strings.Join(out, "\n") + "\n"
}

func filterHunkStarts(starts []int, upTo int) []int {
	var out []int
	for _, s := range starts {
		if s <= upTo {
			out = append(out, s)
		}
	}
	return out
}

func parseHunkStarts(header string) (int, int) {
	var o, n int
	parts := strings.Fields(header)
	if len(parts) >= 3 {
		fmt.Sscanf(strings.TrimPrefix(parts[1], "-"), "%d", &o)
		fmt.Sscanf(strings.TrimPrefix(parts[2], "+"), "%d", &n)
	}
	return o, n
}

func (g *Gui) applyStagingSelection(discard bool) {
	st := g.staging
	node := g.selectedFileNode()
	if node != nil && node.File != nil && !node.File.Tracked && !st.staged {
		// untracked file: stage the whole file
		g.gitAction("Stage file", "add", "--", st.file)
		g.afterStaging()
		return
	}
	patch := st.buildPatch(false)
	if patch == "" {
		return
	}
	args := []string{"apply", "--cached"}
	if st.staged {
		args = append(args, "--reverse")
		g.logAction("Unstage hunk")
	} else if discard {
		args = []string{"apply", "--reverse"}
		g.logAction("Discard hunk")
	} else {
		g.logAction("Stage hunk")
	}
	args = append(args, "-")
	g.logCommand("git "+quoteArgs(args), true)
	cmd := exec.Command("git", args...)
	cmd.Dir = g.repo.WorkTree
	cmd.Stdin = strings.NewReader(patch)
	cmd.Env = os.Environ()
	if out, err := cmd.CombinedOutput(); err != nil {
		g.showErrorPopup(strings.TrimSpace(string(out)))
	}
	g.afterStaging()
}

func (g *Gui) afterStaging() {
	st := g.staging
	g.refreshFiles()
	g.refreshBranches()
	g.refreshCommits()
	node := g.selectedFileNode()
	if node == nil || node.IsDir() || node.File.Name != st.file {
		// file no longer has changes of this kind
		g.exitStagingView()
		return
	}
	f := node.File
	if st.staged && !f.HasStagedChanges {
		if f.HasUnstagedChanges {
			g.staging = g.buildStagingState(st.file, false)
		} else {
			g.exitStagingView()
		}
		return
	}
	if !st.staged && !f.HasUnstagedChanges {
		if f.HasStagedChanges {
			g.staging = g.buildStagingState(st.file, true)
		} else {
			g.exitStagingView()
		}
		return
	}
	sel := st.selected
	g.staging = g.buildStagingState(st.file, st.staged)
	if sel < len(g.staging.rawLines) {
		g.staging.selected = sel
	}
	g.updateMainView()
}
