	"hash/crc32"
	"hash/fnv"
	"math"
	"math/rand"
	"crypto/md5"
	"encoding/binary"
)

func init() {
	hashes := map[string]func([]byte) uint64{
		"crc32":  func(s []byte) uint64 { return uint64(crc32.ChecksumIEEE(s)) },
		"fnv32":  func(s []byte) uint64 { h := fnv.New32(); h.Write(s); return uint64(h.Sum32()) },
		"fnv32a": func(s []byte) uint64 { h := fnv.New32a(); h.Write(s); return uint64(h.Sum32()) },
		"fnv64":  func(s []byte) uint64 { h := fnv.New64(); h.Write(s); return h.Sum64() },
		"fnv64a": func(s []byte) uint64 { h := fnv.New64a(); h.Write(s); return h.Sum64() },
		"md5le":  func(s []byte) uint64 { b := md5.Sum(s); return binary.LittleEndian.Uint64(b[:8]) },
		"md5be":  func(s []byte) uint64 { b := md5.Sum(s); return binary.BigEndian.Uint64(b[:8]) },
	}
	draws := map[string]func(r *rand.Rand) float64{
		"f64":   func(r *rand.Rand) float64 { return r.Float64() },
		"intn":  func(r *rand.Rand) float64 { return float64(r.Intn(360)) / 360 },
		"int63": func(r *rand.Rand) float64 { return float64(r.Int63()) / float64(math.MaxInt64) },
		"f32":   func(r *rand.Rand) float64 { return float64(r.Float32()) },
		"int31": func(r *rand.Rand) float64 { return float64(r.Int31()) / float64(math.MaxInt32) },
		"intn1000": func(r *rand.Rand) float64 { return float64(r.Intn(1000)) / 1000 },
		"intn100": func(r *rand.Rand) float64 { return float64(r.Intn(100)) / 100 },
		"uint32": func(r *rand.Rand) float64 { return float64(r.Uint32()) / float64(math.MaxUint32) },
		"norm":  func(r *rand.Rand) float64 { return math.Mod(math.Abs(r.NormFloat64()), 1) },
	}
	for hn, hf := range hashes {
		for dn, df := range draws {
			ok := 0
			for _, o := range data2 {
				h, _, _ := hsl(o.r, o.g, o.b)
				hv := hf([]byte(o.name))
				v := df(rand.New(rand.NewSource(int64(hv))))
				if math.Abs(v-h) < 0.012 || math.Abs(v-h) > 0.988 {
					ok++
				}
			}
			if ok > 3 {
				fmt.Printf("DRAW %s %s: %d/%d\n", hn, dn, ok, len(data2))
			}
		}
	}
	fmt.Println("draw search done")
}
EOF
