new='''	remotes.handleKey = func(name string) bool {
		kb := &g.cfg.Keybinding
		switch name {
		case kb.Universal.GoInto:
			if r := g.selectedRemote(); r != nil {
				g.openRemoteBranches(r)
			}
			return true
		case kb.Universal.New:
			g.showPrompt("New remote name:", "", func(rname string) {
				rname = strings.TrimSpace(rname)
				if rname == "" {
					return
				}
				g.showPrompt("New remote url:", "", func(url string) {
					url = strings.TrimSpace(url)
					if url == "" {
						return
					}
					if err := g.gitAction("Add remote", "remote", "add", rname, url); err != nil {
						g.showErrorPopup(err.Error())
					}
					g.refreshAll()
					g.updateMainView()
				})
			})
			return true
		case kb.Universal.Remove:
			r := g.selectedRemote()
			if r == nil {
				return true
			}
			g.showConfirm("Remove remote", fmt.Sprintf("Are you sure you want to remove remote '%s'?", r.Name), func() {
				if err := g.gitAction("Remove remote", "remote", "remove", r.Name); err != nil {
					g.showErrorPopup(err.Error())
				}
				g.refreshAll()
				g.updateMainView()
			}, nil)
			return true
		case kb.Branches.FetchRemote:
			r := g.selectedRemote()
			if r == nil {
				return true
			}
			if err := g.gitAction("Fetch remote", "fetch", r.Name); err != nil {
				g.showErrorPopup(err.Error())
			}
			g.refreshAll()
			g.updateMainView()
			return true
		}
		return false
	}'''
